(function () {
  'use strict';

  const GENERATED_BANK_SCRIPT = "// Deterministic, locally generated practice set: 360 mechanical + 160 aptitude MCQs.\n// Every variant has a worked calculation; there are no network calls or API keys here.\n(() => {\n  const questions=[];\n  const levels=['Basic','Intermediate','Advanced'];\n  const byTrack={\n    'Engineering Mechanics':'Mechanical Core','Strength of Materials':'CAE / Analysis',\n    'Machine Design':'CAD / Design','Theory of Machines':'CAD / Design',\n    'Thermodynamics':'Maintenance / Utilities','Fluid Mechanics':'Maintenance / Utilities',\n    'Heat Transfer':'Maintenance / Utilities','Manufacturing':'Manufacturing',\n    'Metrology':'Quality / Metrology','Industrial Engineering':'Supply Chain / Production',\n    'Cross-core Engineering Basics':'Mechanical + Aptitude'\n  };\n  const round=(n,d=1)=>Number(n.toFixed(d));\n  const fmt=(n,d=1)=>Number(n).toFixed(d).replace(/\\.0$/,'');\n  function seededSort(options,id){\n    let h=0;for(const c of id)h=(h*31+c.charCodeAt(0))>>>0;\n    return options.map((v,i)=>({v,k:Math.sin(h+i*17.123)*10000})).sort((a,b)=>a.k-b.k).map(x=>x.v);\n  }\n  function addChoice({id,category='mechanical',topic,difficulty,role,prompt,correct,wrong,explain}){\n    const options=seededSort([correct,...wrong.filter(x=>x!==correct)].slice(0,4),id);\n    if(new Set(options).size<4)throw new Error(`Duplicate options in ${id}`);\n    questions.push({id,category,role:role||byTrack[topic]||'Mechanical Core',topic,difficulty,text:prompt,options,answer:options.indexOf(correct),explain});\n  }\n  function addNum({id,category='mechanical',topic,difficulty,role,prompt,value,unit='',decimals=1,step,explain}){\n    const target=round(value,decimals), delta=step||Math.max(10**(-decimals),Math.abs(target)*0.12);\n    const candidates=[target+delta,target-delta,target+2*delta,target/2,target*2,target+4*delta,target-3*delta]\n      .map(v=>round(v,decimals)).filter(v=>Number.isFinite(v)&&v!==target);\n    const wrong=[...new Set(candidates)].slice(0,3);\n    while(wrong.length<3){const next=round(target+(wrong.length+5)*delta,decimals);if(next!==target&&!wrong.includes(next))wrong.push(next);}\n    const renderValue=v=>unit==='₹'?`₹${fmt(v,decimals)}`:unit==='%'?`${fmt(v,decimals)}%`:unit?.startsWith('₹/')?`₹${fmt(v,decimals)}${unit.slice(1)}`:`${fmt(v,decimals)}${unit?` ${unit}`:''}`;\n    addChoice({id,category,topic,difficulty,role,prompt,correct:renderValue(target),wrong:wrong.map(renderValue),explain});\n  }\n  function addFamily(name,topic,fn){for(let i=0;i<15;i++)fn(i,levels[(i+name.length)%3],`${name}-${String(i+1).padStart(2,'0')}`);}\n\n  // Mechanical core: 24 families × 15 distinct parameter sets = 360 questions.\n  addFamily('moment','Engineering Mechanics',(i,d,id)=>{const F=120+24*i,arm=.25+.05*(i%6),M=round(F*arm,1);addNum({id,topic:'Engineering Mechanics',difficulty:d,prompt:`A ${F} N force acts perpendicular to a ${arm.toFixed(2)} m lever arm. What moment acts about the pivot?`,value:M,unit:'N·m',decimals:1,step:Math.max(1,round(F*.05,1)),explain:`For a perpendicular force, M=F r. Thus M=${F}×${arm.toFixed(2)}=${M} N·m.`});});\n  addFamily('axial-stress','Strength of Materials',(i,d,id)=>{const F=10+5*i,A=100+25*(i%5),v=F*1000/A;addNum({id,topic:'Strength of Materials',difficulty:d,prompt:`A uniform bar carries ${F} kN in tension over an area of ${A} mm². Find the normal stress.`,value:v,unit:'MPa',decimals:0,step:10,explain:`σ=F/A. Since 1 N/mm²=1 MPa, σ=(${F}×1000)/${A}=${fmt(v,0)} MPa.`});});\n  addFamily('axial-elongation','Strength of Materials',(i,d,id)=>{const P=5+5*i,L=300+50*(i%8),A=100+20*(i%4),E=200,v=P*L/(A*E);addNum({id,topic:'Strength of Materials',difficulty:d,prompt:`A steel rod (${A} mm², ${L} mm long) carries ${P} kN tension. Take E=200 GPa. Estimate elongation.`,value:v,unit:'mm',decimals:3,step:.025,explain:`δ=FL/(AE). With E=200,000 N/mm², δ=(${P}×1000×${L})/(${A}×200000)=${v.toFixed(3)} mm.`});});\n  addFamily('beam-bending','Strength of Materials',(i,d,id)=>{const b=24,h=40+4*(i%8),sigma=10+5*i,M=sigma*b*h*h/6;addNum({id,topic:'Strength of Materials',difficulty:d,prompt:`A rectangular beam (b=${b} mm, h=${h} mm) has I=bh³/12. If M=${M.toLocaleString('en-US')} N·mm, find the maximum bending stress.`,value:sigma,unit:'MPa',decimals:0,step:5,explain:`σ=Mc/I. Here c=h/2 and I=bh³/12, so σ=6M/(bh²)=6×${M}/(${b}×${h}²)=${sigma} MPa.`});});\n  addFamily('shaft-torsion','Strength of Materials',(i,d,id)=>{const dia=20+2*(i%8),target=10+4*i,T=round(target*Math.PI*dia**3/16,0),actual=16*T/(Math.PI*dia**3);addNum({id,topic:'Strength of Materials',difficulty:d,prompt:`A solid shaft of diameter ${dia} mm transmits ${fmt(T/1000,2)} N·m torque. Estimate maximum shear stress.`,value:actual,unit:'MPa',decimals:1,step:2,explain:`For a solid circular shaft, τmax=16T/(πd³). Convert torque to N·mm: ${T} N·mm. Substitution gives τ≈${actual.toFixed(1)} MPa.`});});\n  addFamily('beam-reactions','Engineering Mechanics',(i,d,id)=>{const P=2+2*i,R=P/2;addNum({id,topic:'Engineering Mechanics',difficulty:d,prompt:`A simply supported beam carries a ${P} kN point load at mid-span. What is the vertical reaction at each support?`,value:R,unit:'kN',decimals:0,step:1,explain:`The geometry is symmetric, so reactions are equal. From ΣFy=0, 2R=${P}; therefore each reaction is ${R} kN.`});});\n  addFamily('gear-speed','Theory of Machines',(i,d,id)=>{const z1=18+2*(i%6),ratio=2+(i%3),z2=z1*ratio,N1=300+30*i,N2=N1/ratio,correct=`${N2} rpm, opposite direction`;const wrong=[`${N1*ratio} rpm, opposite direction`,`${N2} rpm, same direction`,`${N1} rpm, opposite direction`];addChoice({id,topic:'Theory of Machines',difficulty:d,prompt:`An external ${z1}-tooth gear at ${N1} rpm drives a ${z2}-tooth gear. What is the driven speed and direction?`,correct,wrong,explain:`N₁Z₁=N₂Z₂, so N₂=${N1}×${z1}/${z2}=${N2} rpm. A single external mesh reverses direction.`});});\n  addFamily('belt-speed','Theory of Machines',(i,d,id)=>{const D1=10+(i%6),ratio=2+(i%3),D2=D1*ratio,N1=240+24*i,N2=N1/ratio;addNum({id,topic:'Theory of Machines',difficulty:d,prompt:`A ${D1} cm driver pulley rotates at ${N1} rpm and drives a ${D2} cm pulley with no slip. Find the driven speed.`,value:N2,unit:'rpm',decimals:0,step:12,explain:`With no slip, N₁D₁=N₂D₂. Thus N₂=${N1}×${D1}/${D2}=${N2} rpm.`});});\n  addFamily('first-law','Thermodynamics',(i,d,id)=>{const Q=150+40*i,W=30+10*(i%9),U=Q-W;addNum({id,topic:'Thermodynamics',difficulty:d,prompt:`A closed system receives ${Q} kJ heat and does ${W} kJ work. Find ΔU, taking work by the system as positive.`,value:U,unit:'kJ',decimals:0,step:10,explain:`For a closed system, ΔU=Q−W=${Q}−${W}=${U} kJ.`});});\n  addFamily('sensible-heat','Thermodynamics',(i,d,id)=>{const m=1+i%5,cp=round(.8+.2*(i%8),1),dt=10+5*i,Q=round(m*cp*dt,1);addNum({id,topic:'Thermodynamics',difficulty:d,prompt:`${m} kg of a solid (cp=${cp} kJ/(kg·K)) is heated by ${dt} K. Estimate heat supplied.`,value:Q,unit:'kJ',decimals:1,step:Math.max(1,round(Q*.15,1)),explain:`Q=mcₚΔT=${m}×${cp}×${dt}=${Q.toFixed(1)} kJ, assuming constant specific heat and no phase change.`});});\n  addFamily('carnot','Thermodynamics',(i,d,id)=>{const Th=500+50*i,Tc=200+10*(i%16),eta=(1-Tc/Th)*100;addNum({id,topic:'Thermodynamics',difficulty:d,prompt:`A reversible engine operates between ${Th} K and ${Tc} K reservoirs. Find its maximum thermal efficiency.`,value:eta,unit:'%',decimals:1,step:2,explain:`Carnot efficiency ηmax=1−T_L/T_H=1−${Tc}/${Th}=${eta.toFixed(1)}%.`});});\n  addFamily('continuity','Fluid Mechanics',(i,d,id)=>{const A=5+i,V=2+(i%6),Q=A*V*.1;addNum({id,topic:'Fluid Mechanics',difficulty:d,prompt:`Flow crosses a ${A} cm² section at ${V} m/s. Find volume flow rate in L/s.`,value:Q,unit:'L/s',decimals:1,step:.5,explain:`Q=Av. Since 1 cm²=10⁻⁴ m² and 1 m³/s=1000 L/s, Q=${A}×${V}×0.1=${Q.toFixed(1)} L/s.`});});\n  addFamily('reynolds','Fluid Mechanics',(i,d,id)=>{const V=round(.5+.1*i,1),D=round(.02+.005*(i%8),3),rho=1000,mu=.001,Re=rho*V*D/mu;addNum({id,topic:'Fluid Mechanics',difficulty:d,prompt:`Water (ρ=1000 kg/m³, μ=0.001 Pa·s) flows at ${V} m/s in a ${D} m pipe. Find Reynolds number.`,value:Re,unit:'',decimals:0,step:5000,explain:`Re=ρVD/μ=1000×${V}×${D}/0.001=${fmt(Re,0)}. It is dimensionless.`});});\n  addFamily('hydrostatic','Fluid Mechanics',(i,d,id)=>{const h=round(.5+.25*i,2),p=1000*10*h/1000;addNum({id,topic:'Fluid Mechanics',difficulty:d,prompt:`Find gauge pressure ${h} m below the free surface of water. Use ρ=1000 kg/m³ and g=10 m/s².`,value:p,unit:'kPa',decimals:1,step:5,explain:`p=ρgh=1000×10×${h} Pa=${p.toFixed(1)} kPa.`});});\n  addFamily('darcy-loss','Fluid Mechanics',(i,d,id)=>{const f=.02,ratio=20+4*i,V=1+(i%4),g=10,hf=f*ratio*V*V/(2*g);addNum({id,topic:'Fluid Mechanics',difficulty:d,prompt:`A pipe has Darcy f=${f}, L/D=${ratio}, mean speed ${V} m/s. Estimate friction head loss using g=10 m/s².`,value:hf,unit:'m',decimals:2,step:.2,explain:`Darcy–Weisbach: h_f=f(L/D)V²/(2g)=${f}×${ratio}×${V}²/20=${hf.toFixed(2)} m.`});});\n  addFamily('conduction','Heat Transfer',(i,d,id)=>{const k=round(.5+.1*(i%5),1),A=1+i%4,dt=20+5*i,L=round(.1+.05*(i%4),2),Q=k*A*dt/L;addNum({id,topic:'Heat Transfer',difficulty:d,prompt:`A plane wall has k=${k} W/(m·K), area ${A} m², thickness ${L} m and ΔT=${dt} K. Find steady heat rate.`,value:Q,unit:'W',decimals:0,step:20,explain:`For 1-D steady conduction, Q̇=kAΔT/L=${k}×${A}×${dt}/${L}=${fmt(Q,0)} W.`});});\n  addFamily('convection','Heat Transfer',(i,d,id)=>{const h=10+5*i,A=round(.1+.05*(i%4),2),dt=10+2*i,Q=h*A*dt;addNum({id,topic:'Heat Transfer',difficulty:d,prompt:`A surface (area ${A} m²) is at ${dt} K above ambient. If h=${h} W/(m²·K), find convective heat rate.`,value:Q,unit:'W',decimals:1,step:5,explain:`Newton’s cooling law: Q̇=hA(Ts−T∞)=${h}×${A}×${dt}=${Q.toFixed(1)} W.`});});\n  addFamily('cutting-speed','Manufacturing',(i,d,id)=>{const D=20+5*(i%8),N=500+100*i,V=Math.PI*D*N/1000;addNum({id,topic:'Manufacturing',difficulty:d,prompt:`A ${D} mm workpiece rotates at ${N} rpm. Estimate cutting speed.`,value:V,unit:'m/min',decimals:1,step:5,explain:`V=πDN/1000=π×${D}×${N}/1000≈${V.toFixed(1)} m/min.`});});\n  addFamily('turning-mrr','Manufacturing',(i,d,id)=>{const D=40+5*(i%8),N=200+25*i,f=round(.1+.05*(i%4),2),depth=1+(i%3),mrr=Math.PI*D*N*f*depth/1000;addNum({id,topic:'Manufacturing',difficulty:d,prompt:`In turning, D=${D} mm, N=${N} rpm, feed=${f} mm/rev and depth=${depth} mm. Estimate MRR in cm³/min.`,value:mrr,unit:'cm³/min',decimals:1,step:5,explain:`MRR≈πDNfd/1000=${Math.PI.toFixed(3)}×${D}×${N}×${f}×${depth}/1000≈${mrr.toFixed(1)} cm³/min.`});});\n  addFamily('capability','Metrology',(i,d,id)=>{const sigma=round(.25+.25*(i%4),2),target=1+(i%8),width=6*sigma*target;addNum({id,topic:'Metrology',difficulty:d,prompt:`A stable process has specification width ${width.toFixed(2)} mm and σ=${sigma.toFixed(2)} mm. Find Cp.`,value:target,unit:'',decimals:1,step:.5,explain:`Cp=(USL−LSL)/(6σ)=${width.toFixed(2)}/(6×${sigma.toFixed(2)})=${target.toFixed(1)}.`});});\n  addFamily('eoq','Industrial Engineering',(i,d,id)=>{const Q=50+10*i,S=50,H=2,D=Q*Q*H/(2*S);addNum({id,topic:'Industrial Engineering',difficulty:d,prompt:`Annual demand D=${D} units, ordering cost S=₹${S}/order and holding cost H=₹${H}/unit-year. Find EOQ.`,value:Q,unit:'units',decimals:0,step:20,explain:`EOQ=√(2DS/H)=√(2×${D}×${S}/${H})=${Q} units under the basic EOQ assumptions.`});});\n  addFamily('spring-rate','Machine Design',(i,d,id)=>{const k=10+5*i,x=4+(i%7),F=k*x;addNum({id,topic:'Machine Design',difficulty:d,prompt:`A linear spring extends ${x} mm under a ${F} N load. Find its stiffness.`,value:k,unit:'N/mm',decimals:0,step:5,explain:`For a linear spring, F=kx, so k=F/x=${F}/${x}=${k} N/mm.`});});\n  addFamily('motor-power','Cross-core Engineering Basics',(i,d,id)=>{const V=24+4*i,I=2+(i%8),P=V*I;addNum({id,topic:'Cross-core Engineering Basics',difficulty:d,prompt:`A DC motor draws ${I} A from a ${V} V supply. Find electrical input power.`,value:P,unit:'W',decimals:0,step:20,explain:`Electrical input power P=VI=${V}×${I}=${P} W. Shaft output is lower when losses are present.`});});\n  addFamily('pump-power','Fluid Mechanics',(i,d,id)=>{const qL=10+2*i,H=10+2*(i%10),eta=.8,P=.01*qL*H/eta;addNum({id,topic:'Fluid Mechanics',difficulty:d,prompt:`A water pump delivers ${qL} L/s through ${H} m head at ${eta*100}% efficiency. Estimate input power (g=10 m/s²).`,value:P,unit:'kW',decimals:2,step:.5,explain:`P_in=ρgQH/η. With Q=${qL}/1000 m³/s, P_in=1000×10×(${qL}/1000)×${H}/${eta}=${P.toFixed(2)} kW.`});});\n\n  // General Aptitude: 16 families × 10 distinct variants = 160 questions.\n  const aptitude=(name,fn)=>{for(let i=0;i<10;i++)fn(i,levels[(i+name.length)%3],`AP-${name}-${String(i+1).padStart(2,'0')}`);};\n  const aptNum=(x)=>addNum({...x,category:'aptitude',role:'General Aptitude'});\n  aptitude('discount',(i,d,id)=>{const price=500+100*i,pct=10+5*(i%7),sale=price*(1-pct/100);aptNum({id,topic:'Aptitude — Percentages',difficulty:d,prompt:`A tool priced at ₹${price} receives a ${pct}% discount. What is the sale price?`,value:sale,unit:'₹',decimals:0,step:50,explain:`Discount=${pct}% of ₹${price}=₹${price*pct/100}. Sale price=${price}−${price*pct/100}=₹${sale}.`});});\n  aptitude('ratio-share',(i,d,id)=>{const a=2+i%5,b=3+(i*2)%6,total=(a+b)*(10+i);const part=total*a/(a+b);aptNum({id,topic:'Aptitude — Ratios',difficulty:d,prompt:`₹${total} is divided in the ratio ${a}:${b}. What is the first share?`,value:part,unit:'₹',decimals:0,step:a+b,explain:`Total ratio parts=${a}+${b}=${a+b}. First share=${total}×${a}/${a+b}=₹${part}.`});});\n  aptitude('weighted-average',(i,d,id)=>{const n1=10+2*i,n2=8+2*(i%7),m1=60+2*i,m2=70+3*(i%8),avg=(n1*m1+n2*m2)/(n1+n2);aptNum({id,topic:'Aptitude — Averages',difficulty:d,prompt:`Group A has ${n1} people averaging ${m1}; group B has ${n2} people averaging ${m2}. Find the combined average.`,value:avg,unit:'',decimals:1,step:2,explain:`Combined average=(n₁m₁+n₂m₂)/(n₁+n₂)=(${n1}×${m1}+${n2}×${m2})/(${n1}+${n2})=${avg.toFixed(1)}.`});});\n  aptitude('work-rates',(i,d,id)=>{const a=6+2*i,b=2*a,combined=a*b/(a+b);aptNum({id,topic:'Aptitude — Work and Time',difficulty:d,prompt:`Worker A completes a job in ${a} days and B in ${b} days. How many days do they need working together?`,value:combined,unit:'days',decimals:1,step:.5,explain:`Combined rate=1/${a}+1/${b}=${(1/a+1/b).toFixed(3)} job/day. Time=1/rate=${combined.toFixed(1)} days.`});});\n  aptitude('distance-speed',(i,d,id)=>{const speed=36+6*i,time=1+(i%5)*.5,dist=speed*time;aptNum({id,topic:'Aptitude — Speed and Distance',difficulty:d,prompt:`A vehicle maintains ${speed} km/h for ${time} h. How far does it travel?`,value:dist,unit:'km',decimals:0,step:10,explain:`Distance=speed×time=${speed}×${time}=${dist} km.`});});\n  aptitude('simple-interest',(i,d,id)=>{const P=1000+500*i,r=5+(i%6),t=2+(i%4),SI=P*r*t/100;aptNum({id,topic:'Aptitude — Interest',difficulty:d,prompt:`Find simple interest on ₹${P} at ${r}% per year for ${t} years.`,value:SI,unit:'₹',decimals:0,step:50,explain:`SI=Prt/100=${P}×${r}×${t}/100=₹${SI}.`});});\n  aptitude('compound-interest',(i,d,id)=>{const P=1000+1000*i,r=10,n=2,A=P*Math.pow(1+r/100,n),CI=A-P;aptNum({id,topic:'Aptitude — Interest',difficulty:d,prompt:`₹${P} is invested at ${r}% compound interest annually for ${n} years. Find the interest earned.`,value:CI,unit:'₹',decimals:0,step:100,explain:`Amount=P(1+r/100)^n=${P}(1.1)^2=₹${Math.round(A)}. Interest=A−P=₹${Math.round(CI)}.`});});\n  aptitude('probability',(i,d,id)=>{const red=2+i,blue=4+2*(i%6),total=red+blue,p=red/total;aptNum({id,topic:'Aptitude — Probability',difficulty:d,prompt:`A bag has ${red} red and ${blue} blue counters. One is chosen at random. What is P(red)?`,value:p,unit:'',decimals:3,step:.1,explain:`P(red)=favourable outcomes/total outcomes=${red}/(${red}+${blue})=${p.toFixed(3)}.`});});\n  aptitude('permutations',(i,d,id)=>{const n=5+i%5,r=2+i%3;let value=1;for(let k=0;k<r;k++)value*=n-k;aptNum({id,topic:'Aptitude — Counting',difficulty:d,prompt:`How many ordered arrangements of ${r} different items can be selected from ${n} distinct items?`,value,unit:'ways',decimals:0,step:10,explain:`Use nPr=n!/(n−r)!=${n}×${Array.from({length:r-1},(_,j)=>n-j-1).join('×')}=${value}.`});});\n  aptitude('arithmetic-sequence',(i,d,id)=>{const first=3+2*i,diff=2+i%7,n=8,term=first+(n-1)*diff;aptNum({id,topic:'Aptitude — Number Series',difficulty:d,prompt:`An arithmetic sequence starts at ${first} and increases by ${diff} each term. What is its ${n}th term?`,value:term,unit:'',decimals:0,step:diff,explain:`aₙ=a₁+(n−1)d=${first}+(${n}−1)×${diff}=${term}.`});});\n  aptitude('profit-percent',(i,d,id)=>{const cp=500+100*i,pct=10+5*(i%8),sp=cp*(1+pct/100);aptNum({id,topic:'Aptitude — Profit and Loss',difficulty:d,prompt:`An item costs ₹${cp} and is sold at a ${pct}% profit. Find the selling price.`,value:sp,unit:'₹',decimals:0,step:50,explain:`Selling price=cost×(1+profit rate)=${cp}×${1+pct/100}=₹${sp}.`});});\n  aptitude('missing-average',(i,d,id)=>{const count=5+i%6,avg=40+5*i,sum=count*avg,known=sum-(10+3*i);aptNum({id,topic:'Aptitude — Averages',difficulty:d,prompt:`The average of ${count} values is ${avg}. The first ${count-1} values sum to ${known}. Find the remaining value.`,value:sum-known,unit:'',decimals:0,step:5,explain:`Total sum=${count}×${avg}=${sum}. Remaining value=${sum}−${known}=${sum-known}.`});});\n  aptitude('unit-speed',(i,d,id)=>{const kmh=18*(2+i),ms=kmh/3.6;aptNum({id,topic:'Aptitude — Units',difficulty:d,prompt:`Convert ${kmh} km/h to m/s.`,value:ms,unit:'m/s',decimals:0,step:5,explain:`Multiply by 5/18: ${kmh}×5/18=${ms} m/s.`});});\n  aptitude('routes',(i,d,id)=>{const a=2+i,b=3+(i%7),routes=a*b;aptNum({id,topic:'Aptitude — Counting',difficulty:d,prompt:`There are ${a} routes from A to B and ${b} routes from B to C. How many A-to-C journeys pass through B?`,value:routes,unit:'routes',decimals:0,step:5,explain:`By the multiplication rule, choose one A–B route and one B–C route: ${a}×${b}=${routes}.`});});\n  aptitude('successive-percent',(i,d,id)=>{const up=5+5*(i%6),down=5+5*((i+2)%6),factor=round((1+up/100)*(1-down/100),4),net=(factor-1)*100;aptNum({id,topic:'Aptitude — Percentages',difficulty:d,prompt:`A value rises by ${up}% and then falls by ${down}%. Find the net percentage change.`,value:net,unit:'%',decimals:2,step:1,explain:`Multiply the factors: (1+${up}/100)×(1−${down}/100)=${factor}. Net change=(${factor}−1)×100=${net.toFixed(2)}%.`});});\n  aptitude('mixture-average',(i,d,id)=>{const m1=2+i%5,m2=3+(2*i)%6,c1=10+5*i,c2=30+4*i,avg=(m1*c1+m2*c2)/(m1+m2);aptNum({id,topic:'Aptitude — Weighted Averages',difficulty:d,prompt:`Mix ${m1} kg of a ₹${c1}/kg material with ${m2} kg of a ₹${c2}/kg material. Find the average price per kg.`,value:avg,unit:'₹/kg',decimals:2,step:2,explain:`Weighted average=(m₁c₁+m₂c₂)/(m₁+m₂)=(${m1}×${c1}+${m2}×${c2})/${m1+m2}=₹${avg.toFixed(2)}/kg.`});});\n\n  if(questions.length!==520)throw new Error(`Expected 520 generated questions, got ${questions.length}`);\n  window.MECHPREP_GENERATED_QUESTIONS=questions;\n})();\n";

  const STUDY_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"theme-color\" content=\"#0b1020\">\n<title>Mechanical + TCS Study Studio</title>\n<style>\n:root{--bg:#0b1020;--panel:#131b2f;--panel2:#17223a;--line:#27334c;--text:#edf3ff;--muted:#9cabc4;--cyan:#63d8df;--blue:#7898ff;--lime:#a5e6b2;--amber:#ffcb78;--danger:#ff8e9c;--shadow:0 22px 60px rgba(0,0,0,.24)}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 70% 0%,#1d3152 0,transparent 31rem),var(--bg);color:var(--text);font:15px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif}\nbutton,input,select{font:inherit}button{cursor:pointer}.app{min-height:100vh;display:grid;grid-template-columns:250px 1fr}.sidebar{background:rgba(8,13,26,.82);border-right:1px solid var(--line);padding:24px 16px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column;gap:26px}.brand{display:flex;align-items:center;gap:12px;padding:4px 10px}.brand-mark{width:38px;height:38px;border-radius:13px;background:linear-gradient(135deg,var(--cyan),var(--blue));color:#091426;display:grid;place-items:center;font-weight:900;font-size:19px;box-shadow:0 8px 24px #63d8df38}.brand strong{display:block;font-size:14px;letter-spacing:.04em}.brand small{color:var(--muted);font-size:11px}.nav-label{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#71809b;padding:0 12px;margin-bottom:7px}.nav{display:grid;gap:5px}.nav button{border:0;background:transparent;color:#aebbd0;padding:11px 12px;border-radius:11px;text-align:left;display:flex;align-items:center;gap:11px;transition:.2s}.nav button:hover,.nav button.active{background:#1a2944;color:white}.nav button.active{box-shadow:inset 3px 0 var(--cyan)}.nav .ico{width:22px;text-align:center;color:var(--cyan);font-size:16px}.side-note{margin-top:auto;background:#121d31;border:1px solid var(--line);border-radius:15px;padding:13px;color:var(--muted);font-size:12px}.side-note b{color:var(--text);display:block;margin-bottom:3px}\nmain{min-width:0;padding:28px clamp(18px,4vw,54px) 60px}.topbar{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:26px}.eyebrow{color:var(--cyan);letter-spacing:.16em;text-transform:uppercase;font-size:10px;font-weight:800}.topbar h1{font-size:clamp(24px,3vw,36px);margin:4px 0 0;line-height:1.12;letter-spacing:-.04em}.top-actions{display:flex;gap:9px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#17243b;color:var(--text);padding:10px 14px;border-radius:10px;font-weight:650;font-size:13px}.btn:hover{border-color:var(--cyan);transform:translateY(-1px)}.btn.primary{background:linear-gradient(120deg,#54d1db,#7c9bff);color:#071426;border:0}.btn.ghost{background:transparent}.hero{background:linear-gradient(118deg,#182945,#15223a 60%,#16213b);border:1px solid #2d4665;border-radius:22px;padding:28px;display:grid;grid-template-columns:1.3fr .7fr;gap:24px;box-shadow:var(--shadow);overflow:hidden;position:relative}.hero:after{content:\"\";position:absolute;width:300px;height:300px;border-radius:50%;border:1px solid #63d8df33;right:-95px;top:-140px;box-shadow:0 0 0 38px #63d8df0a,0 0 0 80px #63d8df08}.hero h2{font-size:clamp(25px,3vw,38px);line-height:1.12;letter-spacing:-.04em;margin:9px 0 11px;max-width:650px}.hero p{color:#b1bfd4;max-width:660px;margin:0 0 20px}.hero-art{min-height:170px;display:grid;place-items:center;position:relative;z-index:1}.orbit{width:175px;height:175px;border:1px solid #6cdde4aa;border-radius:50%;display:grid;place-items:center;position:relative;box-shadow:0 0 55px #61d9df22,inset 0 0 38px #61d9df13}.orbit:before,.orbit:after{content:\"\";position:absolute;border:1px dashed #6cdde455;border-radius:50%;inset:18px;transform:rotate(38deg)}.orbit:after{inset:37px;transform:rotate(-42deg)}.orbit span{font-size:49px;font-weight:900;color:var(--cyan);text-shadow:0 0 26px #63d8df88}.stat-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:16px 0 28px}.stat{padding:16px;background:#121b2e;border:1px solid var(--line);border-radius:15px}.stat strong{font-size:25px;letter-spacing:-.04em;display:block}.stat small{color:var(--muted);font-size:12px}.section-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin:30px 0 14px}.section-head h2{font-size:20px;letter-spacing:-.025em;margin:0}.section-head p{color:var(--muted);margin:3px 0 0;font-size:13px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.tile{padding:17px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(150deg,#17243a,#121b2e);min-height:140px}.tile .tile-ico{font-size:22px;color:var(--cyan)}.tile h3{margin:8px 0 5px;font-size:15px}.tile p{margin:0;color:var(--muted);font-size:12px}.tile .count{margin-top:12px;font-size:11px;color:var(--cyan);font-weight:750;letter-spacing:.04em}\n.page{display:none}.page.active{display:block}.filters{display:grid;grid-template-columns:minmax(180px,1.4fr) repeat(3,minmax(135px,.7fr));gap:10px;padding:14px;background:#121b2e;border:1px solid var(--line);border-radius:16px;margin:18px 0}.field{display:grid;gap:5px}.field label{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.12em}.field input,.field select{width:100%;background:#0b1426;color:var(--text);border:1px solid #2a3954;border-radius:9px;padding:10px 11px;outline:none}.field input:focus,.field select:focus{border-color:var(--cyan)}.results-meta{color:var(--muted);font-size:12px;display:flex;justify-content:space-between;align-items:center;gap:12px;margin:12px 2px}.question-list{display:grid;gap:12px}.q-card{background:linear-gradient(155deg,#16223a,#111a2d);border:1px solid #293852;border-radius:16px;padding:17px;box-shadow:0 12px 32px #00000016}.q-top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:9px}.q-badges{display:flex;gap:6px;flex-wrap:wrap}.pill{display:inline-flex;align-items:center;padding:4px 8px;border-radius:999px;background:#1f304c;border:1px solid #304565;color:#bbcada;font-size:10px;font-weight:700}.pill.pdf{color:#9be4d4;border-color:#33695f;background:#14352f}.pill.gen{color:#c5ccff;border-color:#4a5187;background:#20274b}.pill.topic{color:#f2d39b;border-color:#68563c;background:#392c1e}.q-card h3{font-size:14px;margin:0 0 10px}.q-text{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.68 ui-monospace,SFMono-Regular,Consolas,monospace;color:#dbe5f4;background:#0c1527;border:1px solid #27344b;border-radius:11px;padding:13px;margin:0}.q-image{margin:12px 0 0;background:#0a1323;border:1px solid #2b3b55;border-radius:12px;padding:9px}.q-image img{display:block;max-width:100%;max-height:360px;object-fit:contain;border-radius:6px;margin:auto}.q-image small{display:block;color:var(--muted);font-size:10px;margin-top:7px}.q-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:12px}.reveal{display:none;background:#132f2c;border:1px solid #2c6557;border-radius:12px;padding:13px;margin-top:12px}.reveal.open{display:block}.reveal strong{color:#9ce7c4;font-size:11px;text-transform:uppercase;letter-spacing:.1em}.reveal p{white-space:pre-wrap;margin:6px 0 0;font-size:13px;color:#e0f5eb}.reveal .explain{color:#b8d1c7;margin-top:8px}.option-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:12px}.answer-option{border:1px solid #2b3b55;background:#0d182a;color:#d9e5f8;padding:10px;border-radius:10px;text-align:left;font-size:12px}.answer-option:hover{border-color:var(--cyan);background:#142b3a}.answer-option.correct{border-color:#4cbb8a;background:#15352f}.answer-option.wrong{border-color:#db687d;background:#3a1d2b}.option-feedback{font-size:12px;color:var(--muted);margin-top:8px}.pager{display:flex;justify-content:center;align-items:center;gap:12px;margin:20px 0}.pager span{color:var(--muted);font-size:12px}\n.formula-layout{display:grid;grid-template-columns:1fr 1fr;gap:14px}.formula-card{background:#141f33;border:1px solid var(--line);border-radius:15px;padding:16px}.formula-card h3{margin:0 0 9px;font-size:14px}.formula{background:#0b1527;border:1px solid #26354e;border-radius:10px;padding:12px;color:#c8f4f0;font:600 16px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}.formula-card p{color:var(--muted);font-size:12px;margin:9px 0 0}.formula-group{margin:23px 0}.formula-group h2{font-size:18px;margin:0 0 12px}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.gallery-card{background:#141f33;border:1px solid var(--line);border-radius:15px;padding:12px}.gallery-card img{display:block;max-width:100%;height:215px;width:100%;object-fit:contain;background:#f6f6f6;border-radius:9px}.gallery-card h3{font-size:13px;margin:10px 0 3px}.gallery-card small{color:var(--cyan);font-size:10px}.gallery-card p{color:var(--muted);font-size:11px;margin:5px 0 0}\n.guide-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.guide-card{padding:18px;border-radius:16px;background:#141f33;border:1px solid var(--line)}.guide-card h3{margin:0 0 8px;font-size:15px}.guide-card p,.guide-card li{font-size:12px;color:#b7c4d8}.guide-card ul{padding-left:17px;margin:8px 0}.guide-card li{margin:5px 0}.plan{display:grid;gap:8px}.plan-row{display:grid;grid-template-columns:74px 1fr;gap:12px;padding:12px;background:#111a2d;border:1px solid #273650;border-radius:12px}.plan-row b{color:var(--cyan);font-size:12px}.plan-row span{font-size:12px;color:#c3cee0}.sources{display:grid;gap:9px}.source-row{padding:12px 14px;border:1px solid var(--line);border-radius:12px;background:#121b2e}.source-row b{display:block;font-size:12px}.source-row span{font-size:11px;color:var(--muted)}.notice{padding:12px 14px;border-left:3px solid var(--amber);background:#342918;border-radius:0 10px 10px 0;color:#f4dfbf;font-size:12px;margin:16px 0}.footnote{color:#7f8da5;font-size:11px;margin-top:25px;border-top:1px solid var(--line);padding-top:14px}\n@media(max-width:980px){.app{grid-template-columns:1fr}.sidebar{position:static;height:auto;padding:12px 14px;border-right:0;border-bottom:1px solid var(--line);gap:10px}.brand{padding:0 5px}.nav{display:flex;overflow:auto}.nav-label,.side-note{display:none}.nav button{white-space:nowrap;padding:9px 11px}.nav .ico{display:none}main{padding:20px 15px 45px}.hero{grid-template-columns:1fr}.hero-art{display:none}.stat-grid{grid-template-columns:repeat(2,1fr)}}\n@media(max-width:680px){.topbar{align-items:flex-start;flex-direction:column}.filters{grid-template-columns:1fr 1fr}.filters .field:first-child{grid-column:1/-1}.grid3,.guide-grid,.formula-layout,.gallery{grid-template-columns:1fr}.option-grid{grid-template-columns:1fr}.hero{padding:21px}.q-top{align-items:flex-start;flex-direction:column}.stat strong{font-size:22px}}\n@media print{body{background:white;color:#111}.sidebar,.top-actions,.filters,.q-actions,.pager{display:none!important}main{padding:0}.page{display:none!important}.page.active{display:block!important}.q-card,.formula-card,.guide-card{background:white;color:#111;border:1px solid #aaa;break-inside:avoid}.q-text,.formula{background:#f6f6f6;color:#111}.reveal{display:block!important}}\n</style>\n</head>\n<body>\n<div class=\"app\">\n<aside class=\"sidebar\">\n  <div class=\"brand\"><div class=\"brand-mark\">M</div><div><strong>STUDY STUDIO</strong><small>Mechanical \u00b7 Aptitude \u00b7 TCS</small></div></div>\n  <div><div class=\"nav-label\">Workspace</div><nav class=\"nav\">\n    <button class=\"active\" data-page=\"dashboard\"><span class=\"ico\">\u2302</span>Overview</button>\n    <button data-page=\"questions\"><span class=\"ico\">\u25a4</span>Question bank</button>\n    <button data-page=\"formulas\"><span class=\"ico\">\u2211</span>Formula book</button>\n    <button data-page=\"guide\"><span class=\"ico\">\u25c8</span>Study guide</button>\n    <button data-page=\"sources\"><span class=\"ico\">\u25a7</span>Sources</button>\n  </nav></div>\n  <div class=\"side-note\"><b>Works offline</b>All questions, formula notes and selected PDF image crops are embedded in this file. No sign-in or network request is used.</div>\n</aside>\n<main>\n  <header class=\"topbar\"><div><div class=\"eyebrow\">Placement preparation workspace</div><h1>Mechanical + TCS Study Studio</h1></div><div class=\"top-actions\"><button class=\"btn ghost\" id=\"printBtn\">Print current view</button><button class=\"btn primary\" data-go=\"questions\">Start practice \u2192</button></div></header>\n\n  <section class=\"page active\" id=\"page-dashboard\">\n    <div class=\"hero\"><div><div class=\"eyebrow\">Your study workspace</div><h2>Original handout questions. Mechanical practice. Formula-first revision.</h2><p>Use the original TCS questions with their answer keys and explanations, then switch to the 520 generated practice problems from your JavaScript bank. Formula snapshots are clipped from your uploaded PDFs.</p><div class=\"top-actions\"><button class=\"btn primary\" data-go=\"questions\">Practice exact PDF questions</button><button class=\"btn\" data-go=\"formulas\">Open formula book</button></div></div><div class=\"hero-art\"><div class=\"orbit\"><span>\u2211</span></div></div></div>\n    <div class=\"stat-grid\"><div class=\"stat\"><strong id=\"pdfCount\">178</strong><small>Original PDF questions</small></div><div class=\"stat\"><strong id=\"genCount\">520</strong><small>Generated JS questions</small></div><div class=\"stat\"><strong id=\"totalCount\">698</strong><small>Total practice items</small></div><div class=\"stat\"><strong id=\"attemptCount\">0</strong><small>Practice attempts on this device</small></div></div>\n    <div class=\"section-head\"><div><h2>Choose a practice track</h2><p>Question groups mirror your uploaded handouts and question-bank topics.</p></div></div>\n    <div class=\"grid3\">\n      <article class=\"tile\"><div class=\"tile-ico\">\uff05</div><h3>Numerical ability</h3><p>Interest, percentages, commission, averages, speed, work, geometry, probability and number problems.</p><div class=\"count\">TCS HANDOUT QUESTIONS</div></article>\n      <article class=\"tile\"><div class=\"tile-ico\">\u2318</div><h3>Logical reasoning</h3><p>Assumptions, arguments, course of action, series, coding, family relations, arrangements and figures.</p><div class=\"count\">TCS HANDOUT QUESTIONS</div></article>\n      <article class=\"tile\"><div class=\"tile-ico\">Aa</div><h3>Verbal & communication</h3><p>Cloze tests, paragraph ordering, comprehension, grammar, sentence correction, analogies and vocabulary.</p><div class=\"count\">TCS HANDOUT QUESTIONS</div></article>\n      <article class=\"tile\"><div class=\"tile-ico\">\u2699</div><h3>Mechanical core</h3><p>Mechanics, strength of materials, design, machines, thermodynamics, fluids, heat transfer and manufacturing.</p><div class=\"count\">GENERATED JS PRACTICE</div></article>\n      <article class=\"tile\"><div class=\"tile-ico\">\u25a6</div><h3>Production & quality</h3><p>Cutting speed, material removal, process capability, EOQ and production-oriented basics.</p><div class=\"count\">GENERATED JS PRACTICE</div></article>\n      <article class=\"tile\"><div class=\"tile-ico\">\u2234</div><h3>Worked formula revision</h3><p>Compact equation cards plus original photographed working from the numerical ability PDF.</p><div class=\"count\">FORMULA BOOK + PDF IMAGES</div></article>\n    </div>\n    <div class=\"section-head\"><div><h2>Suggested study route</h2><p>A practical sequence for revising the uploaded material.</p></div><button class=\"btn\" data-go=\"guide\">Open complete guide</button></div>\n    <div class=\"plan\">\n      <div class=\"plan-row\"><b>Days 1\u20132</b><span>Revise numerical formulas and solve the original quantitative questions. Record every error by topic.</span></div>\n      <div class=\"plan-row\"><b>Days 3\u20134</b><span>Practice reasoning patterns and selection/arrangement questions. Draw tables and diagrams before choosing an option.</span></div>\n      <div class=\"plan-row\"><b>Days 5\u20136</b><span>Revise grammar, sentence correction, paragraph ordering, comprehension and vocabulary.</span></div>\n      <div class=\"plan-row\"><b>Day 7</b><span>Mix TCS handout items with mechanical practice, then revisit only the questions you missed.</span></div>\n    </div>\n  </section>\n\n  <section class=\"page\" id=\"page-questions\">\n    <div class=\"section-head\"><div><h2>Question bank</h2><p>PDF items retain the handout wording, answer and explanation. Generated items retain the JavaScript solution logic.</p></div><button class=\"btn\" id=\"randomBtn\">Random question \u2197</button></div>\n    <div class=\"filters\">\n      <div class=\"field\"><label for=\"searchBox\">Search question text</label><input id=\"searchBox\" type=\"search\" placeholder=\"Search a formula, phrase or topic\u2026\"></div>\n      <div class=\"field\"><label for=\"sourceFilter\">Question source</label><select id=\"sourceFilter\"><option value=\"pdf\">Original PDF handouts</option><option value=\"generated\">Generated JavaScript bank</option><option value=\"all\">All 698 questions</option></select></div>\n      <div class=\"field\"><label for=\"topicFilter\">Subject / topic</label><select id=\"topicFilter\"><option value=\"all\">All topics</option></select></div>\n      <div class=\"field\"><label for=\"levelFilter\">Difficulty</label><select id=\"levelFilter\"><option value=\"all\">All levels</option><option>Basic</option><option>Intermediate</option><option>Advanced</option></select></div>\n    </div>\n    <div class=\"results-meta\"><span id=\"resultsCount\">Loading questions\u2026</span><span>Answers are hidden until you reveal them.</span></div>\n    <div class=\"question-list\" id=\"questionList\"></div>\n    <div class=\"pager\"><button class=\"btn\" id=\"prevPage\">\u2190 Previous</button><span id=\"pageNum\">Page 1</span><button class=\"btn\" id=\"nextPage\">Next \u2192</button></div>\n  </section>\n\n  <section class=\"page\" id=\"page-formulas\">\n    <div class=\"section-head\"><div><h2>Formula book</h2><p>Mechanical formulas follow the supplied JS question bank; aptitude formulas are drawn from the TCS numerical handout and the JS bank.</p></div></div>\n    <div id=\"formulaGroups\"></div>\n    <div class=\"section-head\"><div><h2>Original formula and working images</h2><p>These are image crops from your uploaded TCS Numerical Ability PDF, not recreated diagrams.</p></div></div>\n    <div class=\"gallery\" id=\"formulaGallery\"></div>\n    <div class=\"notice\">Source note: the 2022\u201323 Mechanical Engineering Handbook is a syllabus document, not a complete formula handbook. The mechanical formula cards below are taken from the worked formulas in your uploaded JavaScript practice bank; the photographed worked solutions above come from the TCS Numerical Ability PDF.</div>\n  </section>\n\n  <section class=\"page\" id=\"page-guide\">\n    <div class=\"section-head\"><div><h2>Study guide</h2><p>Revision map based on the topics appearing in your question bank and the uploaded handouts.</p></div></div>\n    <div class=\"guide-grid\">\n      <article class=\"guide-card\"><h3>Numerical ability \u2014 revise these methods</h3><ul><li>Simple and compound interest; compare amounts over multiple years.</li><li>Percentages, commission slabs, profit and loss, successive changes.</li><li>Ratio, partnership shares and weighted averages.</li><li>Speed\u2013time\u2013distance, relative motion, trains and chase problems.</li><li>Work-rate combinations and payment sharing.</li><li>Geometry: perimeter, diagonal, area, cones, circles and volumes.</li><li>Probability, divisibility, remainders and number patterns.</li></ul></article>\n      <article class=\"guide-card\"><h3>Reasoning \u2014 solve systematically</h3><ul><li>Assumptions, strong arguments and courses of action: separate facts from unsupported conclusions.</li><li>Eligibility/selection criteria: turn every rule into a checklist; apply referral exceptions only when stated.</li><li>Letter/number series and coding: compare positions, gaps and transformations.</li><li>Family relations and seating/ordering: draw a compact relation or position diagram.</li><li>Venn/set questions: map each shape to its group and locate the required overlap.</li><li>Paper folding and figure series: track orientation, symmetry and movement one step at a time.</li></ul></article>\n      <article class=\"guide-card\"><h3>Verbal ability \u2014 practice the exact formats</h3><ul><li>Sentence insertion and paragraph ordering: follow pronouns, connectors and topic continuity.</li><li>Grammar error identification: subject\u2013verb agreement, tense, pronouns and parallelism.</li><li>Sentence combining and correction: preserve the original meaning and compare like with like.</li><li>Passage comprehension: answer from the passage, not outside assumptions.</li><li>Analogies and synonyms: identify the relationship before selecting a pair.</li></ul></article>\n      <article class=\"guide-card\"><h3>English communication \u2014 focus areas</h3><ul><li>Cloze tests: use context, collocations and fixed prepositions.</li><li>Vocabulary in context: check the sentence clue and contrast words.</li><li>Sentence correction: check grammar first, then clarity and meaning.</li><li>Paragraph ordering: locate the opening sentence and reference words such as \u201cthis\u201d, \u201cthey\u201d and \u201cthese\u201d.</li><li>Analogy questions: classify the relationship (synonym, contrast, function, part/whole).</li></ul></article>\n      <article class=\"guide-card\"><h3>Mechanical core \u2014 practice topics in the JS bank</h3><ul><li>Engineering Mechanics: moment and simply supported beam reactions.</li><li>Strength of Materials: axial stress, elongation, bending stress and shaft torsion.</li><li>Theory of Machines: gear speed and belt/pulley speed ratios.</li><li>Thermodynamics: first law, sensible heat and Carnot efficiency.</li><li>Fluid Mechanics: continuity, Reynolds number, hydrostatic pressure, pipe loss and pump power.</li><li>Heat Transfer: steady conduction and convection.</li><li>Manufacturing, metrology, industrial engineering: cutting speed, MRR, Cp and EOQ.</li></ul></article>\n      <article class=\"guide-card\"><h3>Mechanical syllabus \u2014 handbook topic pointers</h3><ul><li>Machine Design: design factors, static strength, failure theories, fatigue, shaft design and joints (handbook section around printed p. 63).</li><li>Heat Transfer: conduction, fins, transient conduction, radiation, convection, heat exchangers, boiling and condensation (printed pp. 106\u2013107).</li><li>Tribology: lubricants, viscosity, friction, wear, journal bearings and hydrostatic lubrication (printed pp. 197\u2013198).</li><li>Thermodynamics includes basic systems, work and heat, first/second law, pure substances, and ideal/real gases (handbook course outline).</li></ul></article>\n    </div>\n    <div class=\"section-head\"><div><h2>7-day revision plan</h2><p>Suggested practice order; this is a study recommendation, not an exam schedule from the PDFs.</p></div></div>\n    <div class=\"plan\">\n      <div class=\"plan-row\"><b>Day 1</b><span>Interest, percentages, profit/loss and commission. Rework every numerical handout solution without looking.</span></div>\n      <div class=\"plan-row\"><b>Day 2</b><span>Ratios, partnership, averages, speed, work, geometry and probability. Build a one-page formula recall sheet.</span></div>\n      <div class=\"plan-row\"><b>Day 3</b><span>Reasoning: series, coding, family relations, arrangements and Venn diagrams.</span></div>\n      <div class=\"plan-row\"><b>Day 4</b><span>Reasoning: assumptions, arguments, course of action, eligibility and figure questions.</span></div>\n      <div class=\"plan-row\"><b>Day 5</b><span>Verbal: comprehension, cloze passages, paragraph ordering, analogies and synonyms.</span></div>\n      <div class=\"plan-row\"><b>Day 6</b><span>English communication: grammar, sentence correction, sentence combining and vocabulary.</span></div>\n      <div class=\"plan-row\"><b>Day 7</b><span>Mechanical formula review and mixed timed practice. Revisit wrong answers and write why the correct method works.</span></div>\n    </div>\n    <div class=\"notice\">The supplied Mechanical Engineering Handbook is for the 2022\u201323 scheme. Use it as a topic map, and verify current course codes or scheme details against the latest department material.</div>\n  </section>\n\n  <section class=\"page\" id=\"page-sources\">\n    <div class=\"section-head\"><div><h2>Source files & coverage</h2><p>Original PDF question wording is kept in a separate archive from generated JS practice.</p></div></div>\n    <div class=\"stat-grid\"><div class=\"stat\"><strong>36</strong><small>Numerical Ability PDF items</small></div><div class=\"stat\"><strong>36</strong><small>Reasoning Ability PDF items</small></div><div class=\"stat\"><strong>40</strong><small>Verbal Ability PDF items</small></div><div class=\"stat\"><strong>66</strong><small>English Communication PDF items</small></div></div>\n    <div class=\"sources\">\n      <div class=\"source-row\"><b>extra-question-bank.js</b><span>520 generated MCQs: 360 mechanical-core + 160 general aptitude. The original generator logic is embedded unchanged in this website.</span></div>\n      <div class=\"source-row\"><b>TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf</b><span>36 original questions (18 per set), with answer and explanation text when present in the PDF. Formula working images included.</span></div>\n      <div class=\"source-row\"><b>TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf</b><span>36 original questions (18 per set), with figure previews for selected diagram-based items.</span></div>\n      <div class=\"source-row\"><b>TCS_Verbal Ability_Trainer Handout .pdf</b><span>40 original questions, including sentence completion, grammar, comprehension, paragraph ordering and vocabulary.</span></div>\n      <div class=\"source-row\"><b>TCS_English Communication Trainer Handout Set 2.docx.pdf</b><span>66 original questions, including cloze tests, paragraph ordering, analogies, sentence correction and synonyms.</span></div>\n      <div class=\"source-row\"><b>20_12_23-2022-23-BE-Mechanical-Engineering-Syllabus.pdf</b><span>Used as a mechanical syllabus topic map, including machine design, heat transfer and tribology content; not treated as a question paper.</span></div>\n    </div>\n    <div class=\"notice\">A few PDF questions use diagrams or embedded scans. Their text extraction may not contain the picture itself, so the relevant original PDF page crop is displayed with the question where available. If a question has no visible answer text in the PDF, the site marks it as \u201cnot stated in extracted text\u201d instead of inventing an answer.</div>\n  </section>\n  <div class=\"footnote\">Local study tool \u00b7 no API keys \u00b7 no network dependency \u00b7 progress is saved only in this browser where local storage is available.</div>\n</main>\n</div>\n\n<script>\n// ---- Original 520-question JavaScript bank (embedded unchanged) ----\n// Deterministic, locally generated practice set: 360 mechanical + 160 aptitude MCQs.\n// Every variant has a worked calculation; there are no network calls or API keys here.\n(() => {\n  const questions=[];\n  const levels=['Basic','Intermediate','Advanced'];\n  const byTrack={\n    'Engineering Mechanics':'Mechanical Core','Strength of Materials':'CAE / Analysis',\n    'Machine Design':'CAD / Design','Theory of Machines':'CAD / Design',\n    'Thermodynamics':'Maintenance / Utilities','Fluid Mechanics':'Maintenance / Utilities',\n    'Heat Transfer':'Maintenance / Utilities','Manufacturing':'Manufacturing',\n    'Metrology':'Quality / Metrology','Industrial Engineering':'Supply Chain / Production',\n    'Cross-core Engineering Basics':'Mechanical + Aptitude'\n  };\n  const round=(n,d=1)=>Number(n.toFixed(d));\n  const fmt=(n,d=1)=>Number(n).toFixed(d).replace(/\\.0$/,'');\n  function seededSort(options,id){\n    let h=0;for(const c of id)h=(h*31+c.charCodeAt(0))>>>0;\n    return options.map((v,i)=>({v,k:Math.sin(h+i*17.123)*10000})).sort((a,b)=>a.k-b.k).map(x=>x.v);\n  }\n  function addChoice({id,category='mechanical',topic,difficulty,role,prompt,correct,wrong,explain}){\n    const options=seededSort([correct,...wrong.filter(x=>x!==correct)].slice(0,4),id);\n    if(new Set(options).size<4)throw new Error(`Duplicate options in ${id}`);\n    questions.push({id,category,role:role||byTrack[topic]||'Mechanical Core',topic,difficulty,text:prompt,options,answer:options.indexOf(correct),explain});\n  }\n  function addNum({id,category='mechanical',topic,difficulty,role,prompt,value,unit='',decimals=1,step,explain}){\n    const target=round(value,decimals), delta=step||Math.max(10**(-decimals),Math.abs(target)*0.12);\n    const candidates=[target+delta,target-delta,target+2*delta,target/2,target*2,target+4*delta,target-3*delta]\n      .map(v=>round(v,decimals)).filter(v=>Number.isFinite(v)&&v!==target);\n    const wrong=[...new Set(candidates)].slice(0,3);\n    while(wrong.length<3){const next=round(target+(wrong.length+5)*delta,decimals);if(next!==target&&!wrong.includes(next))wrong.push(next);}\n    const renderValue=v=>unit==='\u20b9'?`\u20b9${fmt(v,decimals)}`:unit==='%'?`${fmt(v,decimals)}%`:unit?.startsWith('\u20b9/')?`\u20b9${fmt(v,decimals)}${unit.slice(1)}`:`${fmt(v,decimals)}${unit?` ${unit}`:''}`;\n    addChoice({id,category,topic,difficulty,role,prompt,correct:renderValue(target),wrong:wrong.map(renderValue),explain});\n  }\n  function addFamily(name,topic,fn){for(let i=0;i<15;i++)fn(i,levels[(i+name.length)%3],`${name}-${String(i+1).padStart(2,'0')}`);}\n\n  // Mechanical core: 24 families \u00d7 15 distinct parameter sets = 360 questions.\n  addFamily('moment','Engineering Mechanics',(i,d,id)=>{const F=120+24*i,arm=.25+.05*(i%6),M=round(F*arm,1);addNum({id,topic:'Engineering Mechanics',difficulty:d,prompt:`A ${F} N force acts perpendicular to a ${arm.toFixed(2)} m lever arm. What moment acts about the pivot?`,value:M,unit:'N\u00b7m',decimals:1,step:Math.max(1,round(F*.05,1)),explain:`For a perpendicular force, M=F r. Thus M=${F}\u00d7${arm.toFixed(2)}=${M} N\u00b7m.`});});\n  addFamily('axial-stress','Strength of Materials',(i,d,id)=>{const F=10+5*i,A=100+25*(i%5),v=F*1000/A;addNum({id,topic:'Strength of Materials',difficulty:d,prompt:`A uniform bar carries ${F} kN in tension over an area of ${A} mm\u00b2. Find the normal stress.`,value:v,unit:'MPa',decimals:0,step:10,explain:`\u03c3=F/A. Since 1 N/mm\u00b2=1 MPa, \u03c3=(${F}\u00d71000)/${A}=${fmt(v,0)} MPa.`});});\n  addFamily('axial-elongation','Strength of Materials',(i,d,id)=>{const P=5+5*i,L=300+50*(i%8),A=100+20*(i%4),E=200,v=P*L/(A*E);addNum({id,topic:'Strength of Materials',difficulty:d,prompt:`A steel rod (${A} mm\u00b2, ${L} mm long) carries ${P} kN tension. Take E=200 GPa. Estimate elongation.`,value:v,unit:'mm',decimals:3,step:.025,explain:`\u03b4=FL/(AE). With E=200,000 N/mm\u00b2, \u03b4=(${P}\u00d71000\u00d7${L})/(${A}\u00d7200000)=${v.toFixed(3)} mm.`});});\n  addFamily('beam-bending','Strength of Materials',(i,d,id)=>{const b=24,h=40+4*(i%8),sigma=10+5*i,M=sigma*b*h*h/6;addNum({id,topic:'Strength of Materials',difficulty:d,prompt:`A rectangular beam (b=${b} mm, h=${h} mm) has I=bh\u00b3/12. If M=${M.toLocaleString('en-US')} N\u00b7mm, find the maximum bending stress.`,value:sigma,unit:'MPa',decimals:0,step:5,explain:`\u03c3=Mc/I. Here c=h/2 and I=bh\u00b3/12, so \u03c3=6M/(bh\u00b2)=6\u00d7${M}/(${b}\u00d7${h}\u00b2)=${sigma} MPa.`});});\n  addFamily('shaft-torsion','Strength of Materials',(i,d,id)=>{const dia=20+2*(i%8),target=10+4*i,T=round(target*Math.PI*dia**3/16,0),actual=16*T/(Math.PI*dia**3);addNum({id,topic:'Strength of Materials',difficulty:d,prompt:`A solid shaft of diameter ${dia} mm transmits ${fmt(T/1000,2)} N\u00b7m torque. Estimate maximum shear stress.`,value:actual,unit:'MPa',decimals:1,step:2,explain:`For a solid circular shaft, \u03c4max=16T/(\u03c0d\u00b3). Convert torque to N\u00b7mm: ${T} N\u00b7mm. Substitution gives \u03c4\u2248${actual.toFixed(1)} MPa.`});});\n  addFamily('beam-reactions','Engineering Mechanics',(i,d,id)=>{const P=2+2*i,R=P/2;addNum({id,topic:'Engineering Mechanics',difficulty:d,prompt:`A simply supported beam carries a ${P} kN point load at mid-span. What is the vertical reaction at each support?`,value:R,unit:'kN',decimals:0,step:1,explain:`The geometry is symmetric, so reactions are equal. From \u03a3Fy=0, 2R=${P}; therefore each reaction is ${R} kN.`});});\n  addFamily('gear-speed','Theory of Machines',(i,d,id)=>{const z1=18+2*(i%6),ratio=2+(i%3),z2=z1*ratio,N1=300+30*i,N2=N1/ratio,correct=`${N2} rpm, opposite direction`;const wrong=[`${N1*ratio} rpm, opposite direction`,`${N2} rpm, same direction`,`${N1} rpm, opposite direction`];addChoice({id,topic:'Theory of Machines',difficulty:d,prompt:`An external ${z1}-tooth gear at ${N1} rpm drives a ${z2}-tooth gear. What is the driven speed and direction?`,correct,wrong,explain:`N\u2081Z\u2081=N\u2082Z\u2082, so N\u2082=${N1}\u00d7${z1}/${z2}=${N2} rpm. A single external mesh reverses direction.`});});\n  addFamily('belt-speed','Theory of Machines',(i,d,id)=>{const D1=10+(i%6),ratio=2+(i%3),D2=D1*ratio,N1=240+24*i,N2=N1/ratio;addNum({id,topic:'Theory of Machines',difficulty:d,prompt:`A ${D1} cm driver pulley rotates at ${N1} rpm and drives a ${D2} cm pulley with no slip. Find the driven speed.`,value:N2,unit:'rpm',decimals:0,step:12,explain:`With no slip, N\u2081D\u2081=N\u2082D\u2082. Thus N\u2082=${N1}\u00d7${D1}/${D2}=${N2} rpm.`});});\n  addFamily('first-law','Thermodynamics',(i,d,id)=>{const Q=150+40*i,W=30+10*(i%9),U=Q-W;addNum({id,topic:'Thermodynamics',difficulty:d,prompt:`A closed system receives ${Q} kJ heat and does ${W} kJ work. Find \u0394U, taking work by the system as positive.`,value:U,unit:'kJ',decimals:0,step:10,explain:`For a closed system, \u0394U=Q\u2212W=${Q}\u2212${W}=${U} kJ.`});});\n  addFamily('sensible-heat','Thermodynamics',(i,d,id)=>{const m=1+i%5,cp=round(.8+.2*(i%8),1),dt=10+5*i,Q=round(m*cp*dt,1);addNum({id,topic:'Thermodynamics',difficulty:d,prompt:`${m} kg of a solid (cp=${cp} kJ/(kg\u00b7K)) is heated by ${dt} K. Estimate heat supplied.`,value:Q,unit:'kJ',decimals:1,step:Math.max(1,round(Q*.15,1)),explain:`Q=mc\u209a\u0394T=${m}\u00d7${cp}\u00d7${dt}=${Q.toFixed(1)} kJ, assuming constant specific heat and no phase change.`});});\n  addFamily('carnot','Thermodynamics',(i,d,id)=>{const Th=500+50*i,Tc=200+10*(i%16),eta=(1-Tc/Th)*100;addNum({id,topic:'Thermodynamics',difficulty:d,prompt:`A reversible engine operates between ${Th} K and ${Tc} K reservoirs. Find its maximum thermal efficiency.`,value:eta,unit:'%',decimals:1,step:2,explain:`Carnot efficiency \u03b7max=1\u2212T_L/T_H=1\u2212${Tc}/${Th}=${eta.toFixed(1)}%.`});});\n  addFamily('continuity','Fluid Mechanics',(i,d,id)=>{const A=5+i,V=2+(i%6),Q=A*V*.1;addNum({id,topic:'Fluid Mechanics',difficulty:d,prompt:`Flow crosses a ${A} cm\u00b2 section at ${V} m/s. Find volume flow rate in L/s.`,value:Q,unit:'L/s',decimals:1,step:.5,explain:`Q=Av. Since 1 cm\u00b2=10\u207b\u2074 m\u00b2 and 1 m\u00b3/s=1000 L/s, Q=${A}\u00d7${V}\u00d70.1=${Q.toFixed(1)} L/s.`});});\n  addFamily('reynolds','Fluid Mechanics',(i,d,id)=>{const V=round(.5+.1*i,1),D=round(.02+.005*(i%8),3),rho=1000,mu=.001,Re=rho*V*D/mu;addNum({id,topic:'Fluid Mechanics',difficulty:d,prompt:`Water (\u03c1=1000 kg/m\u00b3, \u03bc=0.001 Pa\u00b7s) flows at ${V} m/s in a ${D} m pipe. Find Reynolds number.`,value:Re,unit:'',decimals:0,step:5000,explain:`Re=\u03c1VD/\u03bc=1000\u00d7${V}\u00d7${D}/0.001=${fmt(Re,0)}. It is dimensionless.`});});\n  addFamily('hydrostatic','Fluid Mechanics',(i,d,id)=>{const h=round(.5+.25*i,2),p=1000*10*h/1000;addNum({id,topic:'Fluid Mechanics',difficulty:d,prompt:`Find gauge pressure ${h} m below the free surface of water. Use \u03c1=1000 kg/m\u00b3 and g=10 m/s\u00b2.`,value:p,unit:'kPa',decimals:1,step:5,explain:`p=\u03c1gh=1000\u00d710\u00d7${h} Pa=${p.toFixed(1)} kPa.`});});\n  addFamily('darcy-loss','Fluid Mechanics',(i,d,id)=>{const f=.02,ratio=20+4*i,V=1+(i%4),g=10,hf=f*ratio*V*V/(2*g);addNum({id,topic:'Fluid Mechanics',difficulty:d,prompt:`A pipe has Darcy f=${f}, L/D=${ratio}, mean speed ${V} m/s. Estimate friction head loss using g=10 m/s\u00b2.`,value:hf,unit:'m',decimals:2,step:.2,explain:`Darcy\u2013Weisbach: h_f=f(L/D)V\u00b2/(2g)=${f}\u00d7${ratio}\u00d7${V}\u00b2/20=${hf.toFixed(2)} m.`});});\n  addFamily('conduction','Heat Transfer',(i,d,id)=>{const k=round(.5+.1*(i%5),1),A=1+i%4,dt=20+5*i,L=round(.1+.05*(i%4),2),Q=k*A*dt/L;addNum({id,topic:'Heat Transfer',difficulty:d,prompt:`A plane wall has k=${k} W/(m\u00b7K), area ${A} m\u00b2, thickness ${L} m and \u0394T=${dt} K. Find steady heat rate.`,value:Q,unit:'W',decimals:0,step:20,explain:`For 1-D steady conduction, Q\u0307=kA\u0394T/L=${k}\u00d7${A}\u00d7${dt}/${L}=${fmt(Q,0)} W.`});});\n  addFamily('convection','Heat Transfer',(i,d,id)=>{const h=10+5*i,A=round(.1+.05*(i%4),2),dt=10+2*i,Q=h*A*dt;addNum({id,topic:'Heat Transfer',difficulty:d,prompt:`A surface (area ${A} m\u00b2) is at ${dt} K above ambient. If h=${h} W/(m\u00b2\u00b7K), find convective heat rate.`,value:Q,unit:'W',decimals:1,step:5,explain:`Newton\u2019s cooling law: Q\u0307=hA(Ts\u2212T\u221e)=${h}\u00d7${A}\u00d7${dt}=${Q.toFixed(1)} W.`});});\n  addFamily('cutting-speed','Manufacturing',(i,d,id)=>{const D=20+5*(i%8),N=500+100*i,V=Math.PI*D*N/1000;addNum({id,topic:'Manufacturing',difficulty:d,prompt:`A ${D} mm workpiece rotates at ${N} rpm. Estimate cutting speed.`,value:V,unit:'m/min',decimals:1,step:5,explain:`V=\u03c0DN/1000=\u03c0\u00d7${D}\u00d7${N}/1000\u2248${V.toFixed(1)} m/min.`});});\n  addFamily('turning-mrr','Manufacturing',(i,d,id)=>{const D=40+5*(i%8),N=200+25*i,f=round(.1+.05*(i%4),2),depth=1+(i%3),mrr=Math.PI*D*N*f*depth/1000;addNum({id,topic:'Manufacturing',difficulty:d,prompt:`In turning, D=${D} mm, N=${N} rpm, feed=${f} mm/rev and depth=${depth} mm. Estimate MRR in cm\u00b3/min.`,value:mrr,unit:'cm\u00b3/min',decimals:1,step:5,explain:`MRR\u2248\u03c0DNfd/1000=${Math.PI.toFixed(3)}\u00d7${D}\u00d7${N}\u00d7${f}\u00d7${depth}/1000\u2248${mrr.toFixed(1)} cm\u00b3/min.`});});\n  addFamily('capability','Metrology',(i,d,id)=>{const sigma=round(.25+.25*(i%4),2),target=1+(i%8),width=6*sigma*target;addNum({id,topic:'Metrology',difficulty:d,prompt:`A stable process has specification width ${width.toFixed(2)} mm and \u03c3=${sigma.toFixed(2)} mm. Find Cp.`,value:target,unit:'',decimals:1,step:.5,explain:`Cp=(USL\u2212LSL)/(6\u03c3)=${width.toFixed(2)}/(6\u00d7${sigma.toFixed(2)})=${target.toFixed(1)}.`});});\n  addFamily('eoq','Industrial Engineering',(i,d,id)=>{const Q=50+10*i,S=50,H=2,D=Q*Q*H/(2*S);addNum({id,topic:'Industrial Engineering',difficulty:d,prompt:`Annual demand D=${D} units, ordering cost S=\u20b9${S}/order and holding cost H=\u20b9${H}/unit-year. Find EOQ.`,value:Q,unit:'units',decimals:0,step:20,explain:`EOQ=\u221a(2DS/H)=\u221a(2\u00d7${D}\u00d7${S}/${H})=${Q} units under the basic EOQ assumptions.`});});\n  addFamily('spring-rate','Machine Design',(i,d,id)=>{const k=10+5*i,x=4+(i%7),F=k*x;addNum({id,topic:'Machine Design',difficulty:d,prompt:`A linear spring extends ${x} mm under a ${F} N load. Find its stiffness.`,value:k,unit:'N/mm',decimals:0,step:5,explain:`For a linear spring, F=kx, so k=F/x=${F}/${x}=${k} N/mm.`});});\n  addFamily('motor-power','Cross-core Engineering Basics',(i,d,id)=>{const V=24+4*i,I=2+(i%8),P=V*I;addNum({id,topic:'Cross-core Engineering Basics',difficulty:d,prompt:`A DC motor draws ${I} A from a ${V} V supply. Find electrical input power.`,value:P,unit:'W',decimals:0,step:20,explain:`Electrical input power P=VI=${V}\u00d7${I}=${P} W. Shaft output is lower when losses are present.`});});\n  addFamily('pump-power','Fluid Mechanics',(i,d,id)=>{const qL=10+2*i,H=10+2*(i%10),eta=.8,P=.01*qL*H/eta;addNum({id,topic:'Fluid Mechanics',difficulty:d,prompt:`A water pump delivers ${qL} L/s through ${H} m head at ${eta*100}% efficiency. Estimate input power (g=10 m/s\u00b2).`,value:P,unit:'kW',decimals:2,step:.5,explain:`P_in=\u03c1gQH/\u03b7. With Q=${qL}/1000 m\u00b3/s, P_in=1000\u00d710\u00d7(${qL}/1000)\u00d7${H}/${eta}=${P.toFixed(2)} kW.`});});\n\n  // General Aptitude: 16 families \u00d7 10 distinct variants = 160 questions.\n  const aptitude=(name,fn)=>{for(let i=0;i<10;i++)fn(i,levels[(i+name.length)%3],`AP-${name}-${String(i+1).padStart(2,'0')}`);};\n  const aptNum=(x)=>addNum({...x,category:'aptitude',role:'General Aptitude'});\n  aptitude('discount',(i,d,id)=>{const price=500+100*i,pct=10+5*(i%7),sale=price*(1-pct/100);aptNum({id,topic:'Aptitude \u2014 Percentages',difficulty:d,prompt:`A tool priced at \u20b9${price} receives a ${pct}% discount. What is the sale price?`,value:sale,unit:'\u20b9',decimals:0,step:50,explain:`Discount=${pct}% of \u20b9${price}=\u20b9${price*pct/100}. Sale price=${price}\u2212${price*pct/100}=\u20b9${sale}.`});});\n  aptitude('ratio-share',(i,d,id)=>{const a=2+i%5,b=3+(i*2)%6,total=(a+b)*(10+i);const part=total*a/(a+b);aptNum({id,topic:'Aptitude \u2014 Ratios',difficulty:d,prompt:`\u20b9${total} is divided in the ratio ${a}:${b}. What is the first share?`,value:part,unit:'\u20b9',decimals:0,step:a+b,explain:`Total ratio parts=${a}+${b}=${a+b}. First share=${total}\u00d7${a}/${a+b}=\u20b9${part}.`});});\n  aptitude('weighted-average',(i,d,id)=>{const n1=10+2*i,n2=8+2*(i%7),m1=60+2*i,m2=70+3*(i%8),avg=(n1*m1+n2*m2)/(n1+n2);aptNum({id,topic:'Aptitude \u2014 Averages',difficulty:d,prompt:`Group A has ${n1} people averaging ${m1}; group B has ${n2} people averaging ${m2}. Find the combined average.`,value:avg,unit:'',decimals:1,step:2,explain:`Combined average=(n\u2081m\u2081+n\u2082m\u2082)/(n\u2081+n\u2082)=(${n1}\u00d7${m1}+${n2}\u00d7${m2})/(${n1}+${n2})=${avg.toFixed(1)}.`});});\n  aptitude('work-rates',(i,d,id)=>{const a=6+2*i,b=2*a,combined=a*b/(a+b);aptNum({id,topic:'Aptitude \u2014 Work and Time',difficulty:d,prompt:`Worker A completes a job in ${a} days and B in ${b} days. How many days do they need working together?`,value:combined,unit:'days',decimals:1,step:.5,explain:`Combined rate=1/${a}+1/${b}=${(1/a+1/b).toFixed(3)} job/day. Time=1/rate=${combined.toFixed(1)} days.`});});\n  aptitude('distance-speed',(i,d,id)=>{const speed=36+6*i,time=1+(i%5)*.5,dist=speed*time;aptNum({id,topic:'Aptitude \u2014 Speed and Distance',difficulty:d,prompt:`A vehicle maintains ${speed} km/h for ${time} h. How far does it travel?`,value:dist,unit:'km',decimals:0,step:10,explain:`Distance=speed\u00d7time=${speed}\u00d7${time}=${dist} km.`});});\n  aptitude('simple-interest',(i,d,id)=>{const P=1000+500*i,r=5+(i%6),t=2+(i%4),SI=P*r*t/100;aptNum({id,topic:'Aptitude \u2014 Interest',difficulty:d,prompt:`Find simple interest on \u20b9${P} at ${r}% per year for ${t} years.`,value:SI,unit:'\u20b9',decimals:0,step:50,explain:`SI=Prt/100=${P}\u00d7${r}\u00d7${t}/100=\u20b9${SI}.`});});\n  aptitude('compound-interest',(i,d,id)=>{const P=1000+1000*i,r=10,n=2,A=P*Math.pow(1+r/100,n),CI=A-P;aptNum({id,topic:'Aptitude \u2014 Interest',difficulty:d,prompt:`\u20b9${P} is invested at ${r}% compound interest annually for ${n} years. Find the interest earned.`,value:CI,unit:'\u20b9',decimals:0,step:100,explain:`Amount=P(1+r/100)^n=${P}(1.1)^2=\u20b9${Math.round(A)}. Interest=A\u2212P=\u20b9${Math.round(CI)}.`});});\n  aptitude('probability',(i,d,id)=>{const red=2+i,blue=4+2*(i%6),total=red+blue,p=red/total;aptNum({id,topic:'Aptitude \u2014 Probability',difficulty:d,prompt:`A bag has ${red} red and ${blue} blue counters. One is chosen at random. What is P(red)?`,value:p,unit:'',decimals:3,step:.1,explain:`P(red)=favourable outcomes/total outcomes=${red}/(${red}+${blue})=${p.toFixed(3)}.`});});\n  aptitude('permutations',(i,d,id)=>{const n=5+i%5,r=2+i%3;let value=1;for(let k=0;k<r;k++)value*=n-k;aptNum({id,topic:'Aptitude \u2014 Counting',difficulty:d,prompt:`How many ordered arrangements of ${r} different items can be selected from ${n} distinct items?`,value,unit:'ways',decimals:0,step:10,explain:`Use nPr=n!/(n\u2212r)!=${n}\u00d7${Array.from({length:r-1},(_,j)=>n-j-1).join('\u00d7')}=${value}.`});});\n  aptitude('arithmetic-sequence',(i,d,id)=>{const first=3+2*i,diff=2+i%7,n=8,term=first+(n-1)*diff;aptNum({id,topic:'Aptitude \u2014 Number Series',difficulty:d,prompt:`An arithmetic sequence starts at ${first} and increases by ${diff} each term. What is its ${n}th term?`,value:term,unit:'',decimals:0,step:diff,explain:`a\u2099=a\u2081+(n\u22121)d=${first}+(${n}\u22121)\u00d7${diff}=${term}.`});});\n  aptitude('profit-percent',(i,d,id)=>{const cp=500+100*i,pct=10+5*(i%8),sp=cp*(1+pct/100);aptNum({id,topic:'Aptitude \u2014 Profit and Loss',difficulty:d,prompt:`An item costs \u20b9${cp} and is sold at a ${pct}% profit. Find the selling price.`,value:sp,unit:'\u20b9',decimals:0,step:50,explain:`Selling price=cost\u00d7(1+profit rate)=${cp}\u00d7${1+pct/100}=\u20b9${sp}.`});});\n  aptitude('missing-average',(i,d,id)=>{const count=5+i%6,avg=40+5*i,sum=count*avg,known=sum-(10+3*i);aptNum({id,topic:'Aptitude \u2014 Averages',difficulty:d,prompt:`The average of ${count} values is ${avg}. The first ${count-1} values sum to ${known}. Find the remaining value.`,value:sum-known,unit:'',decimals:0,step:5,explain:`Total sum=${count}\u00d7${avg}=${sum}. Remaining value=${sum}\u2212${known}=${sum-known}.`});});\n  aptitude('unit-speed',(i,d,id)=>{const kmh=18*(2+i),ms=kmh/3.6;aptNum({id,topic:'Aptitude \u2014 Units',difficulty:d,prompt:`Convert ${kmh} km/h to m/s.`,value:ms,unit:'m/s',decimals:0,step:5,explain:`Multiply by 5/18: ${kmh}\u00d75/18=${ms} m/s.`});});\n  aptitude('routes',(i,d,id)=>{const a=2+i,b=3+(i%7),routes=a*b;aptNum({id,topic:'Aptitude \u2014 Counting',difficulty:d,prompt:`There are ${a} routes from A to B and ${b} routes from B to C. How many A-to-C journeys pass through B?`,value:routes,unit:'routes',decimals:0,step:5,explain:`By the multiplication rule, choose one A\u2013B route and one B\u2013C route: ${a}\u00d7${b}=${routes}.`});});\n  aptitude('successive-percent',(i,d,id)=>{const up=5+5*(i%6),down=5+5*((i+2)%6),factor=round((1+up/100)*(1-down/100),4),net=(factor-1)*100;aptNum({id,topic:'Aptitude \u2014 Percentages',difficulty:d,prompt:`A value rises by ${up}% and then falls by ${down}%. Find the net percentage change.`,value:net,unit:'%',decimals:2,step:1,explain:`Multiply the factors: (1+${up}/100)\u00d7(1\u2212${down}/100)=${factor}. Net change=(${factor}\u22121)\u00d7100=${net.toFixed(2)}%.`});});\n  aptitude('mixture-average',(i,d,id)=>{const m1=2+i%5,m2=3+(2*i)%6,c1=10+5*i,c2=30+4*i,avg=(m1*c1+m2*c2)/(m1+m2);aptNum({id,topic:'Aptitude \u2014 Weighted Averages',difficulty:d,prompt:`Mix ${m1} kg of a \u20b9${c1}/kg material with ${m2} kg of a \u20b9${c2}/kg material. Find the average price per kg.`,value:avg,unit:'\u20b9/kg',decimals:2,step:2,explain:`Weighted average=(m\u2081c\u2081+m\u2082c\u2082)/(m\u2081+m\u2082)=(${m1}\u00d7${c1}+${m2}\u00d7${c2})/${m1+m2}=\u20b9${avg.toFixed(2)}/kg.`});});\n\n  if(questions.length!==520)throw new Error(`Expected 520 generated questions, got ${questions.length}`);\n  window.MECHPREP_GENERATED_QUESTIONS=questions;\n})();\n\n// ---- Original PDF question archive extracted from the supplied handouts ----\nconst PDF_QUESTIONS = [{\"id\":\"numerical-1-1\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":1,\"page\":1,\"text\":\"1. The difference between the simple interest and compound Interest calculated annually on a\\ncertain amount at the rate of 20% per annum for 2 years is Rs. 248.20. What is the amount?\\n\\nA. 6205\\nB. 6002\\nC. 6022.5\\nD. 6202.5\",\"answer\":\"6205\",\"explanation\":\"\",\"imageId\":\"num-si-ci\"},{\"id\":\"numerical-1-2\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":2,\"page\":1,\"text\":\"2. If a and b represent the frequencies of the modal class and median class respectively of\\nthe data, the value of 3a+4b is _______.\\n\\nA. 98\\nB. 27\\nC. 90\\nD. 91\",\"answer\":\"91\",\"explanation\":\"\"},{\"id\":\"numerical-1-3\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":3,\"page\":2,\"text\":\"3.  A sales representative\u2019s commission is 6% on all sales up to Rs.15000 and 5% on all sales\\nexceeding this. He remits Rs. 47350 to his company after deducting his commission. What\\nwere the total sales?\\n\\nA. Rs. 50000\\nB. Rs. 49000\\nC. Rs. 50500\\nD. Rs. 47500\",\"answer\":\"Rs. 50000\",\"explanation\":\"LET THE TOTAL SALES BE \u2018S\u2019\\nCOMMISSION ON FIRST SALES OF 15000 AT 6 % = 900\\nCOMMISSION ON BALANCE SALES OF ( S - 15000 ) AT 5 % = 0.05*S - 750\\nNET PROCEEDS TO BE REMITTED = S - [ 900 + 0.05*S -750 ] = 47350\\nSOLVING S = 50000\"},{\"id\":\"numerical-1-4\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":4,\"page\":3,\"text\":\"4.  If the area of the base of a right circular cone is 9856 cm2 and it\u2019s height is 33cm, what is the\\ncurved surface area of the cone?\\n\\nA. 21040 cm2\\nB. 11440 cm2\\nC. 12420 cm2\\nD. 12000 cm2\",\"answer\":\"11440 cm2\",\"explanation\":\"\",\"imageId\":\"num-cone-csa\"},{\"id\":\"numerical-1-5\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":5,\"page\":3,\"text\":\"5.  10% of the voters did not cast their votes in an election between two candidates. 20% of the\\nvoters were found invalid. The winning candidate got 60% of the valid votes and won by a\\nmajority of 2,880 votes. What is the total number of voters who cast their vote?\\n\\nA. 18,000\\nB. 25,000\\nC. 20,000\\nD. 24,000\",\"answer\":\"20,000\",\"explanation\":\"\"},{\"id\":\"numerical-1-6\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":6,\"page\":4,\"text\":\"6.  Two cars A and B, which are 280 Kms apart, start travelling at the same time. If they travel in\\nopposite directions, they meet after two hours. If they travel in the same direction, A meets B\\nafter 14 hrs. What is the speed of car B?\\n\\nA. 70 Kmph\\nB. 60 Kmph\\nC. 80 Kmph\\nD. 50 Kmph\",\"answer\":\"60 Kmph\",\"explanation\":\"Speed of car A=u kmph\\nSpeed of car B =v kmph\\nthen we can make two equations ,\\n2*u+2*v=280----------(1) (s*t=d) (+ since they are moving in opp direction)\\n\\n14*u-14*v=280---------(2) (s*t=d) (- since they are moving in same direction)\\n\\nsubtracting 1 & 2,we get v=60 kmph i.e, speed of car B\"},{\"id\":\"numerical-1-7\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":7,\"page\":5,\"text\":\"7. The radius of a solid sphere and a solid right circular cone are equal and the height of the cone\\nis equal to the diameter of its base. They are melted and the combined matter is recast into a\\nsolid hemisphere. What is the ratio of the radius of the hemisphere to that of the cone?\\n\\nA. Cube Root 4\\nB. Cube Root 6\\nC. Cube Root 2\\nD. Cube Root 3\",\"answer\":\"Cube Root 3\",\"explanation\":\"Let us assume that, radius of cone is r cm and Let us assume that , radius of hemisphere is R\\ncm.\\n\\nThan,\\n\\nHeight of cone = Diameter of cone = 2r.\\nRadius of sphere = r .\\nRadius of hemisphere = R.\\nwe know that,\\nvolume of cone = (1/3) * \u03c0 * (radius)\u00b2 * height.\\nVolume of sphere = (4/3) * \u03c0 * (radius)\u00b3 .\\nvolume of hemisphere = (2/3) * \u03c0 * (Radius)\u00b3.\\nThan, after recast ,\\n\\n\u2192 Volume of cone + volume of sphere = volume of hemisphere\\n\\nPutting all values we get :-\\n\u2192 [(1/3) * \u03c0 * (r)\u00b2 * 2r] + [(4/3) * \u03c0 * (r)\u00b3] = (2/3) * \u03c0 * (R)\u00b3\\n\u2192 (1/3)\u03c0[ 2r\u00b3 + 4r\u00b3 ] = (1/3)\u03c0[2R\u00b3]\\n\u2192 6r\u00b3 = 2R\u00b3\\n\u2192 3r\u00b3 = R\u00b3\\n\u2192 (R\u00b3/r\u00b3) = (3/1)\\ncube root both sides\\n\u2192 R/r = \u00b3\u221a3/1\\n\u2192 R/r = (3)^1/3 / 1\\n\u2192 R : r = (3)^(1/3) : 1\"},{\"id\":\"numerical-1-8\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":8,\"page\":6,\"text\":\"8. If a dealer makes a profit of 20% by selling an article for Rs.18 , by how much should he\\nincrease his selling price in order to make a profit of 30%?\\n\\nA. Rs. 4.5\\nB. Rs. 2.5\\nC. Rs. 3.5\\nD. Rs. 1.5\",\"answer\":\"Rs. 1.5\",\"explanation\":\"sp=18\\ng%=20\\n\\ncp=sp/(1+g%)=18/(1+20%)\\n\\n=18/1.2=15\\n\\ng=30%\\n\\nnew sp = cp(1+g%)\\n\\n= 15(1+30%)=15/1.3\\n\\n=19.5\\n\\nsp should be increased by 19.5-18=1.5\"},{\"id\":\"numerical-1-9\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":9,\"page\":6,\"text\":\"9. A sells an article to B at a profit of 15%. B then sells it to C, making a profit of 20%. If C paid\\nRs. 690. What is the original price of the article?\\n\\nA. 700\\nB. 690\\nC. 575\\nD. 500\",\"answer\":\"500\",\"explanation\":\"\"},{\"id\":\"numerical-1-10\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":10,\"page\":7,\"text\":\"10. If mean of 29 observations is 33 and on adding one more observation the new mean becomes\\n34. What is the value of the 30th observation?\\n\\nA. 68\\nB. 63\\nC. 34\\nD. 55\",\"answer\":\"63\",\"explanation\":\"\"},{\"id\":\"numerical-1-11\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":11,\"page\":8,\"text\":\"11.  If a number is divisible by 7, the remainder is 4. What will be the remainder when the\\nsquare of the same number is divided by 7?\\n\\nA. 4\\nB. 6\\nC. 3\\nD. 2\",\"answer\":\"2\",\"explanation\":\"\"},{\"id\":\"numerical-1-12\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":12,\"page\":8,\"text\":\"12. A, B and C enter into a partnership and their shares are in the ratio (1/3):(1/4):(1/6). After 3\\nmonths, A withdraws one-fourth of his capital and after 9 months a profit of Rs. 582 is divided\\namong them. What is C\u2019s share in profit.?\\n\\nA. 141.1\\nB. 200\\nC. 222\\nD. 216\",\"answer\":\"141.1\",\"explanation\":\"-\"},{\"id\":\"numerical-1-13\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":13,\"page\":8,\"text\":\"13. In a competitive exam, 5 marks are awarded for every correct answer and for every wrong\\nanswer, 2 marks are deducted. Sathwik scores 32 marks in the examination. If 4 marks had\\n\\nbeen awarded for each correct answer and 1 mark had been deducted for each incorrect answer,\\nSathwik would have scored 34 marks. If Sathwik attempted all the questions, how many\\nquestions were there in the test ?\\n\\nA. 14\\nB. 12\\nC. 20\\nD. 26\",\"answer\":\"26\",\"explanation\":\"5x - 2y = 32\\n(4x - y = 34) * 2\\nNow, on solving these two equations:\\n8x - 2y = 68\\n5x - 2y = 32\\nWe get,\\nx = 12\\nputting this value in eq(1) , we get\\ny = 14\\nTotal question = 14 + 12 = 26\"},{\"id\":\"numerical-1-14\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":14,\"page\":9,\"text\":\"14. A and B undertake a piece of work for Rs. 720. A alone can do it in 12 days while B alone can\\ndo it in 16 days. If they get C to help them and finish the work in 6 days, what should be C\u2019s\\nshare of the money earned?\\n\\nA. Rs. 270\\nB. Rs. 360\\nC. Rs. 80\\nD. Rs. 90\",\"answer\":\"90\",\"explanation\":\"\"},{\"id\":\"numerical-1-15\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":15,\"page\":10,\"text\":\"15. If the perimeter of a rectangle is 82cm and its diagonal is 29cm long, what is the area of the\\nrectangle?\\n\\nA. 420cm2\\nB. 441cm2\\nC. 400cm2\\nD. 900 cm2\",\"answer\":\"420cm2\",\"explanation\":\"\"},{\"id\":\"numerical-1-16\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":16,\"page\":11,\"text\":\"16.\\n\\nA. 3\\nB. 2\\nC. 1\\nD. 4\",\"answer\":\"1\",\"explanation\":\"\",\"imageId\":\"num-cube-root\"},{\"id\":\"numerical-1-17\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":17,\"page\":11,\"text\":\"17. There is a horse and a saddle. The sum of their cost is Rs.1100. The cost of the horse is\\nRs.1000 greater than the saddle. What is the cost of a saddle?\\n\\nA. Rs. 100\\nB. Rs. 50\\nC. Rs. 110\\nD. Rs. 1000\",\"answer\":\"Rs. 50\",\"explanation\":\"Cost of the saddle = Rs. x\\nCost of horse = Rs. (x + 1000)\\n\\nGive, Total = Rs. 1100\\n\\nx + (x+1000) = 1100\\n\\n2x = 1100 - 1000\\n2x = 100\\nx = 100/2\\nx = Rs. 50\"},{\"id\":\"numerical-1-18\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":1,\"number\":18,\"page\":12,\"text\":\"18. If company A sells a service for Rs. 50 per hour then which of the following could be a\\nrevenue function for company A?\\n\\nA. R(t) = 50 * t\\n\\nB. R(50) = 50 + t\\n\\nC. R(t) = 50 + t*t\\n\\nD. R(t) = 50 + t\",\"answer\":\"R(t) = 50 * t\",\"explanation\":\"1 hour of service = Rs. 50\\nt hours of service = Rs. 50t\\nCheck the options, Option A fits correctly.\\n\\n________________________________________________________________________\"},{\"id\":\"numerical-2-1\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":1,\"page\":13,\"text\":\"1. A lady has some socks and hats in her closet - 17 blue, 47 red, and 24 yellow. The lights are out\\nand it is totally dark. In spite of the darkness, she can make out the difference between a hat\\nand a sock. She takes out an item out of the closet only if she is sure that it is a sock. How\\nmany socks must she take out to make sure she has two socks of each colour?\\n\\nA. 73\\nB. 64\\nC. 57\\nD. 55\",\"answer\":\"73\",\"explanation\":\"Consider they are all socks and no hats.\\nFirst take out - 47 red socks\\nNext take out - 24 yellow socks\\nFinally - 2 blue socks\\nThe total number of attempts that will be required to take two socks of each colour will be 73.\"},{\"id\":\"numerical-2-2\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":2,\"page\":13,\"text\":\"2.  Udvama Pradipa Udarka is a tall, lean tower with 24 floors. Its security chief Lokabahya is\\nvery popular (or notorious depending on one's math knowledge or lack thereof) among the\\nvisitors. Once a visitor asked him the ratio of people in 24th floor to those in ground floor.\\nLokabahya said that if four persons are added to both the floors, the ratio of fraction becomes\\n9/11. Instead, if five move out of each of the floors, then the result is 3/4. What is the fraction?\\nWhat is your answer like 10/11 without any blank space anywhere.\\n\\nA. 22/39\\nB. 23/42\\nC. 23/29\\n\\nD. 21/42\",\"answer\":\"23/29\",\"explanation\":\"Actual Fraction = x/y\\na. (x+4)/(y+4) = 9/11\\n11x+44 = 9y+36\\n9y - 11x = 8 --- (1)\\n\\nb. (x-5)/(y-5) = 3/4\\n4x - 20 = 3y - 15\\n3y - 4x = -5 --- (2)\\n\\nMulitiply (2) by 3.\\n\\nSolve both equations,\\n9y-11x=8\\n9y-12x=-15\"},{\"id\":\"numerical-2-3\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":3,\"page\":14,\"text\":\"3.  i, j, k, l and m are positive integers in ascending order such that (8 - i)(8 + j)(8 - k)(8 - l)(8 + m)\\n= 3927. What is the value of I + j + k + l + m?\\n\\nA. 19\\nB. 25\\nC. 35\\nD. 14\",\"answer\":\"25\",\"explanation\":\"Given equation, (8-i)(8+j)(8-k)(8-l)(8+m) = 3927\\n3927 is the product of 5 numbers\\n\\nSplit the product,\\n3927\\n= 3 x 1309\\n= 3 x 11 x 119\\n= 3 x 11 x 17 x 7\\n= 3 x 11 x 17 x 7 x 1 (multiplying by one will not affect the product)\\n\\nNow substitute these numbers in the equation,\\n8 - i = 3 -> i = 5\\n8 + j = 11 -> j = 3\\n8 - k = 7 -> k = 1\\n8 - l = 1 -> l = 7\\n8 + m = 17 -> m = 9\\n\\nThe numbers are 1, 3, 5, 7, 9.\\nSum of these would be 25.\"},{\"id\":\"numerical-2-4\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":4,\"page\":15,\"text\":\"4.  Some scientists interpret satellite data to mean that glaciers are melting faster than in earlier\\ncenturies. In each decade since the industrial revolution, the amount of glacier melt has\\ndoubled and some scientists predict that all the glaciers will have melted away by the year\\n2037. If indeed this were true, in which year, would we have lost 50% of all the glaciers?\\n\\nA. 2027\\nB. 2037\\nC. 2017\\nD. 2008\",\"answer\":\"2027\",\"explanation\":\"End of all glaciers = 2037 - 100% melted\\nOne decade ago = 2027 - 50%\\nSince melting doubles every decade, the previous decade it would be half of this decade.\\nSo, if in 2037 it would be 100% melted, in the year 2027 it would be half of that, which is\\n50%.\"},{\"id\":\"numerical-2-5\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":5,\"page\":15,\"text\":\"5.  I have a two-digit number. The unit's digit is twice as ten\u2019s digit. If I reverse the number and\\nsubtract 36 from it, I get the initial number. What's the number I started with?\\n\\nA. 48\\nB. 53\\nC. 60\\nD. 73\",\"answer\":\"48\",\"explanation\":\"Consider the number to be,\\n10x+y (x - tens digit, y - units digit)\\n\\ngiven, y = 2x --- (1)\\n\\nreverse it,\\n10y+x-36 = 10x+y\\n10y-y+x-10x = 36\\n9(y-x)=36\\ny-x = 4 --- (2)\\n\\nUsing (1) in (2)\\n2x - x = 4\\nx = 4\\n\\ny = 2(4) = 8\\n\\n10x+y = 10(4)+8 = 40+8 = 48\"},{\"id\":\"numerical-2-6\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":6,\"page\":16,\"text\":\"6. We live and work in a time of rapidly advancing technology. A social media start-up is\\ndoubling the number of users each week. It took just 47 weeks to acquire a million users. How\\nlong did it take to acquire half a-million users?\\n\\nA. 45 weeks\\nB. 23.5 weeks\\nC. 24 weeks\\nD. 46 weeks\",\"answer\":\"46 weeks\",\"explanation\":\"Given, 47 weeks to reach 1 million and it doubles up each week. Which means in the previous\\nweek it would be half of this week. So in the 46th week it was half a million.\"},{\"id\":\"numerical-2-7\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":7,\"page\":16,\"text\":\"7. The kids Phalaa and Adhiphalaa (don't confuse with Balaa and Adhibalaa, the abracadabra that\\nsage Vishwamitra taught to Rama and Lakshmana to successfully stay the demoness Taadaka)\\ncarry some fruits. Being tender and small, each could carry only a single digit number of fruits.\\nAdhiphalaa has three times the fruits that Phalaa has. If the digits corresponding to Phalaa\u2019s\\nand Adhiphalaa\u2019s fruits are written in that order, the resulting two digit number is a multiple of\\nthree. How many fruits does Adhiphalaa have?\\n\\nA. 9\\n\\nB. 2\\nC. 3\\nD. 6\",\"answer\":\"9\",\"explanation\":\"Given, Both have single digit number of fruits. Adhiphalaa has thrice the number of fruits that\\nPhalaa has.\\nPossibilities,\\n(Phalaa, Adhiphalaa)\\n(1,3)\\n(2,6)\\n(3,9)\\n\\nThe resulting two digit number is a multiple of three, so from the possibilities we can write,\\n1 & 3 = 13\\n2 & 6 = 26\\n3 & 9 = 39\\n\\nNow, adhiphalaa has 9 fruits\"},{\"id\":\"numerical-2-8\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":8,\"page\":17,\"text\":\"8. If the average of 3 distinct positive integers is 4, what is the largest possible value of any of\\nthem?\\n\\nA. 4\\nB. 9\\nC. 12\\nD. 10\",\"answer\":\"9\",\"explanation\":\"Consider the numbers as, x, y and z\\n(x+y+z)/3 = 4\\nx+y+z = 12\\n\\nConsider the first two numbers to the least positive numbers,\\nx = 1\\ny = 2\\nthen, 1 + 2 + z = 12\\n\\nz = 9\\n\\nHence, the largest possible value is 9.\"},{\"id\":\"numerical-2-9\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":9,\"page\":18,\"text\":\"9. Arun wrapped a gift for his friend in a big box, which contains 4 small boxes. Each of these\\nsmall boxes again contain 3 boxes. Each of these boxes contain 3 boxes. The gift is randomly\\nkept in one of the smallest boxes. If you can open one of the smallest boxes, what is the\\nprobability that the gift is in it?\\n\\nA. 1/36\\nB. 1/53\\nC. 1/52\\nD. 1/48\",\"answer\":\"1/36\",\"explanation\":\"Level 1 = 1 box\\n1 big box has 4 smaller boxes\\nLevel 2 = 4 boxes\\nEach small box has 3 more boxes = 12 boxes\\nLevel 3 = 12 boxes\\nEach of these have 3 more boxes = 36 boxes\\nLevel 4 = 36 boxes\\nProbability = 1/36\"},{\"id\":\"numerical-2-10\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":10,\"page\":18,\"text\":\"10. Anmol picks sweets from a bag without looking. The distribution of sweets of each colour in\\nthe bag is given below. What is the probability that Anmol will pick a white sweet?\\n\\nA. 0.3\\nB. 0.6\\nC. 0.5\\nD. 0.2\",\"answer\":\"0.2\",\"explanation\":\"Probability = Favourable Outcomes/Total Outcomes = 6/30 = 1/5 = 0.2\"},{\"id\":\"numerical-2-11\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":11,\"page\":19,\"text\":\"11.  A racehorse starts chasing a wild pony 2 hours after the pony bolts the stable. The race horse\\nfinally catches up with the pony after 3 hours. If the average speed of the race horse is 49 km/h,\\nthen the average speed of the wild pony is _____.\\n\\nA. 30.4 km/h\\nB. 29.4 km/h\\nC. 19.6 km/h\\nD. 32.67 km/h(8/100)\",\"answer\":\"29.4 km/h\",\"explanation\":\"Speed of pony = x km/h\\nd1 = d2\\nx * (2+3) = 49 * 3\\n5x = 147\\nx = 147/5 = 29.4 km/h\"},{\"id\":\"numerical-2-12\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":12,\"page\":20,\"text\":\"12.  Ahilyanagari Express running at a speed of 60 km/h and Cholan Express at 120 km/h take 10 s\\nto cross each other, when they are running in opposite directions (these two trains operate in\\nthe same route only as a mathematical fantasy and not in reality). If Cholan express is 120 m\\nlonger than Ahilyanagari Express, what's the length in meters of the latter?\\n\\nA. 190 m\\nB. 380 m\\nC. 60 m\\nD. 70 m\",\"answer\":\"190 m\",\"explanation\":\"x => Ahilyanagari express\\nx + 120 => Cholan express\\n\\nS1 = 60 km/h = 60 x (5/18) = 50/3 m/s\\nS2 = 120 km/h = 120 x (5/18) = 100/3 m/s\\n\\nMoving towards each other, so add the speeds.\\nS1+S2 = (50/3) + (100/3)\\n\\n1500 = 6x + 360\\n1500 \u2013 360 = 6x\\n1140/6 = x\\nx = 190 m\"},{\"id\":\"numerical-2-13\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":13,\"page\":20,\"text\":\"13.  A police car starts chasing a fugitive in a BMW 4 hours after the BMW escapes from the scene\\nof crime at 10 a.m. The BMW drives for 10 Km through crowded roads of Shanghai and then\\ndrives into a highway, where the traffic allows vehicles to move twice as fast. After a while, the\\npolice car finally catches up with the BMW after a chase that lasted 5 hours. By this time the\\n\\nmoon was up in the sky for 4 hours. If the average speed of the police car is 50 km/h, then the\\naverage speed of the BMW is km/h.\\n\\nA. 27 km/h\\nB. 29 km/h\\nC. 27.78 km/h\\nD. 29.78 km/h\",\"answer\":\"27.78 km/h\",\"explanation\":\"Speed of police car = 50km/h\\nTime taken to catch up = 5hrs\\nTotal distance = speed x time = 50 x 5 = 250 km\\nAverage speed = Total DistanceTotal Time= 2505+4= 2509=27.78 km/h\"},{\"id\":\"numerical-2-14\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":14,\"page\":21,\"text\":\"14.  In the normal course, Ravi, Sanjay and Mukund can each individually build a wall in 5, 8 and\\n10 days respectively. Due to difficult terrain and slushy conditions at the site, the individual\\ntime required for each to complete the work has increased by 20%, 25% and 50% respectively.\\nHow long will they take to build the wall if they work together?\\n\\nA. 3 days\\nB. 4 days\\nC. 6 days\\nD. 2 6/17 days\",\"answer\":\"3 days\",\"explanation\":\"Ravi = 5 + 20% of 5 = 5 + 1 = 6 -> 1/6 in one day\\nSanjay = 8 + 25% of 8 = 8 + 2 = 10 -> 1/10 in one day\\nMukund = 10 + 50% of 10 = 1- + 5 = 15 -> 1/15 in one day\"},{\"id\":\"numerical-2-15\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":15,\"page\":21,\"text\":\"15.  Bhaskar called his friend Shakuntala to celebrate his wedding anniversary. Shakuntala reached\\nthe street where he was living but forgot the door number. She called Bhaskar for his door\\nnumber. Being a geek in math, he didn't give the door number directly. But told this \u201c It is the\\n\\nmiddle number of the three numbers where the difference between first and second numbers is\\nthe same as that between second and third. The product of first and last is 273 and sum of all\\nthree is 51.\\\" Shakuntala reached his house on time. His door number is ____.\\n\\nA. 17\\nB. 13\\nC. 21\\nD. 19\",\"answer\":\"17\",\"explanation\":\"Assume, Bhaskar's door no. = y\\nOther nos. = x and z\\n\\nGiven,\\ny - x = z - y\\n2y = z + x --- (1)\\n\\nx + y + z = 51\\nx + z = 51 - y --- (2)\\n\\nUse (1) in (2)\\n2y = 51 - y\\n3y = 51\\ny = 51/3\\ny = 17\"},{\"id\":\"numerical-2-16\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":16,\"page\":22,\"text\":\"16.  An equilateral triangle ABD is inscribed in a circle as shown in the figure. AC is a diameter of\\nthe circle. If the radius of the circle is 10 cm, what is the area of the shaded portion?\\n\\nA. 243.7 cm2\\nB. 192.4 cm2\\nC. 221.4 cm2\\n\\nD. 273.1 cm2\",\"answer\":\"243.7 cm2\",\"explanation\":\"\",\"imageId\":\"num-triangle-area\"},{\"id\":\"numerical-2-17\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":17,\"page\":23,\"text\":\"17.  There is a circular bookshelf under a stair in a Government library. The wall is 6 m height, the\\ndistance of the base of the stairs from the corner of the room is 8m. What is the radius of the\\ncircular bookshelf in feet?\\n\\nA. 1 m\\nB. 3 m\\nC. 2 m\\nD. 4 m\",\"answer\":\"2\",\"explanation\":\"\",\"imageId\":\"num-bookshelf\"},{\"id\":\"numerical-2-18\",\"sourceKey\":\"numerical\",\"source\":\"TCS Numerical Ability\",\"file\":\"TCS_Numerical Ability Set 1 and Set 2_Trainer Handout.pdf\",\"category\":\"Numerical Ability\",\"set\":2,\"number\":18,\"page\":24,\"text\":\"18. A semicircle and a circle are drawn in a square of side 2 cm. The circle touches two adjacent\\nsides of the square and the semicircle as given in the figure. What is the radius of the circle?\\n\\nA. 8-4\u221a3\\nB. 8+4\u221a3\\nC. 4+2\u221a3\\nD. 4-2\u221a3\",\"answer\":\"4-2\u221a3\",\"explanation\":\"\",\"imageId\":\"num-circle-square\"},{\"id\":\"reasoning-1-1\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":1,\"page\":1,\"text\":\"1. A statement is followed by three assumptions numbered I and II. Consider the statement\\nand decide which of the given assumption(s) is/are implicit in the statement\\n\\nStatement:\\nThe advancement of technology will lead to increase in the sale of smartphone due to its\\nmultipurpose usage\\n\\nAssumptions:\\nI. With the help of smartphone people use many facilities that are available online now a days\\nII. There are more functions of smartphone rather than just conversation\\n\\nA. Neither I nor II is implicit\\nB. Both I and II are implicit\\nC. Only II is implicit\\nD. Only I is implicit\",\"answer\":\"Both I and II are implicit\",\"explanation\":\"I. With the help of smartphone people use many facilities that are available online now a days\\nas per the statement above conclusion follows\\nII. There are more functions of smartphone rather than just conversation as per the statement\\nabove conclusion follows\"},{\"id\":\"reasoning-1-2\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":2,\"page\":1,\"text\":\"2. The following are the criteria for selecting a school psychologist for a reputed school. The\\ncandidates must:\\n\\n(i) be a Postgraduate in Psychology with more than 60% in the Postgraduate examination\\n(ii) have a Postgraduate diploma in Guidance and Counseling.\\n(iii) have secured more than 65% in the interview and at least 60% in the written test.\\n(iv) have at least 3 years of experience in the relevant area.\\nIn case of the candidates who satisfies all other criteria except -\\n\\n(a) at (i), above, but has secured more than 65% in the written test as well as in the interview,\\nhis/her case is to be referred to the Management.\\n\\n(b) at (ii) and (iii) above, but has more than ten-year experience in relevant field, his/her case\\nis to be referred to the Principal,\\n\\nDinesh has done his Master's degree in Psychology with 65% of marks. For the last 10 years,\\nhe has been working as a School psychologist/counsellor.\\nBased on these criteria and information provided, decide the course of action.\\n\\nA. Could not be selected\\nB. Refer to the management\\nC. Could be selected\\nD. Data inadequate\",\"answer\":\"Data Inadequate\",\"explanation\":\"information about interview score is not mentioned .\"},{\"id\":\"reasoning-1-3\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":3,\"page\":2,\"text\":\"3. Which is the wrong term in the following series ?\\n\\njkl, lin, mho, ofq, per, rds, sbt\\n\\nA. sbu\\nB. ofq\\nC. per\\nD. rds\",\"answer\":\"rds\",\"explanation\":\"\"},{\"id\":\"reasoning-1-4\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":4,\"page\":3,\"text\":\"4. In each of the five pairs of letter-clusters, the letters in the second term are rearranged /\\ntransformed form of the letters in the first term in a particular pattern. In which two pairs, the\\ntransformation has been done the same way?\\n\\n[A] RDXPQ - XDPRQ\\n[B] MUKHI - KUMIH\\n[C] GTRSK - RTGKS\\n[D] PKRHU - UPHRK\\n[E] MPQTJ - MTJQP\\n\\nA. B and C\\nB. D and B\\nC. A and D\\nD. A and C\",\"answer\":\"B and C\",\"explanation\":\"\"},{\"id\":\"reasoning-1-5\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":5,\"page\":3,\"text\":\"5. A statement is followed by three Courses of action numbered I, II and III. Consider the\\nstatement and decide which of the given courses of action follow the statement\\n\\nStatement:\\nPollution is damaging our earth securely and we need to realize its effects and prevent this\\ndamage.\\n\\nCourses of Action:\\nI. Government should control unnecessary human actions which damage the environment in\\nmany ways.\\nII. The Pollution Control Board should close down all industries in the residential areas.\\nIII. Spread awareness among the masses to reduce and prevent pollution.\\n\\nA. Only I and II follow.\\nB. All I, II and III follow.\\nC. Only III follows\\nD. Only I follows\",\"answer\":\"All I, II and III follow.\",\"explanation\":\"All course of actions follows, all actions are related with awareness and precautions.\"},{\"id\":\"reasoning-1-6\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":6,\"page\":4,\"text\":\"6. A statement is followed by two assumptions numbered I and II. Consider and decide which of\\nthe given assumptions is/are implicit in the statement\\n\\nStatement:\\nA visit of school children to the Zoo to explore their knowledge about Zoo animals.\\n\\nAssumptions:\\nl. There is no full freedom for animals in the Zoo.\\nll. Children are likely to learn from their interaction with a new environment.\\n\\nA. Neither I nor II is implicit\\nB. Only I is implicit\\nC. Both I and II are implicit\\nD. Only II is implicit.\",\"answer\":\"Only II is implicit.\",\"explanation\":\"As per above statement freedom about animals can't be determined, only 2 follows\"},{\"id\":\"reasoning-1-7\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":7,\"page\":4,\"text\":\"7. A statement is followed by two arguments numbered I and II. Consider and decide which of\\nthe given arguments is/are strong\\n\\nStatement:\\nShould all the government departments in the country be handed over to the private sector?\\n\\nArguments:\\nI. No. The private sector will not be sure to handle the entire government department which is\\nmade for social services.\\nII. Yes. Private sector will handle all departments better than the government.\\n\\nA. All of I, II  are strong\\nB. Only argument I is strong\\nC. Only argument II is strong\\nD. Both I and II are strong.\",\"answer\":\"Only argument II is strong\",\"explanation\":\"-\"},{\"id\":\"reasoning-1-8\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":8,\"page\":5,\"text\":\"8. There are 160 Students in a college hostel which contributes to three newspapers - Hindi,\\nTamil and English. 15 of them do not read any newspaper. The number of Students reading\\nHindi paper is half the number of those reading English paper and one-third of the number of\\nthose reading Tamil paper. 4 students read all the three newspapers and 8 read only two\\nnewspapers - Hindi and Tamil. 5 students read Hindi and English newspapers only and not\\nthe Tamil paper. The number of students who study Tamil and English newspapers is twice\\nthe number of students who study Hindi and English newspapers.\\n\\nHow many students read Tamil newspapers only ?\\n\\nA. 54\\nB. 64\\nC. 37\\nD. 13\",\"answer\":\"54\",\"explanation\":\"-\"},{\"id\":\"reasoning-1-9\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":9,\"page\":5,\"text\":\"9. In a row, seven people are standing for march past.\\n\\nI. B is standing right to A and left to C.\\nII. D is standing left to E but right to C.\\nIII. F is standing right to E and left to G.\\n\\nWho is standing in the middle of the row?\\n\\nA. D\\nB. Either B and G\\nC. A\\nD. Either C or E\",\"answer\":\"D\",\"explanation\":\"\"},{\"id\":\"reasoning-1-10\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":10,\"page\":6,\"text\":\"10. In each of the five pairs of the letter- clusters, the letter in the second term is a rearranged/\\ntransformed form of the letter in the first term in a particular pattern. In which two pairs, has\\nthe transformation been done the same way ?\\n\\n[A] MASON- AMNOS\\n[B] PARTY - APRYT\\n[C]FAULT - AFTLU\\n[D] LODGE- DOLEG\\n[E] CARGO - ACOGS\\n\\nA. B and D\\nB. C and D\\nC. D and E\\nD. A and C\",\"answer\":\"A and C\",\"explanation\":\"\"},{\"id\":\"reasoning-1-11\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":11,\"page\":7,\"text\":\"11. A statement is followed by three courses of action numbers i, ii and iii. Assuming everything\\nin the statements to be true, decide which of the suggested courses of action (a decision to be\\ntaken for follow up/improvement in regard to the problem ) logically follows for pursuing.\\n\\nStatement:\\nIn one of the worst road accidents,15 people died when a roadways bus carrying them\\ncollided with a running truck.\\n\\nCourses of Action:\\n(i) The bus driver should immediately be suspended without any queries.\\n(ii) The government should make markings to all accident - prone areas.\\n(iii) The department of roadways should hold an enquiry at every level and try to punish\\nthose who are responsible for negligence , in the court .\\n\\nA. Only l follow for pursuing\\nB. Both l and ll follow for pursuing\\nC. Both ll and lll follow for pursuing\\nD. Only ll follow for pursuing\",\"answer\":\"Both ll and lll follow for pursuing\",\"explanation\":\"i without any queries decision can't be taken, hence only ii and iii follows\"},{\"id\":\"reasoning-1-12\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":12,\"page\":7,\"text\":\"12. In a family of 7 persons having 4 female and 3 male members, P is the brother of Q and son\\nof R. R has two children and two grandchildren. V is the daughter of S who is the son-in-law\\nof R. W is the nephew of Q and son of T. How is V related to T?\\n\\nA. Cousin\\nB. Niece\\nC. Nephew\\nD. Sister-in-law\",\"answer\":\"Niece\",\"explanation\":\"\"},{\"id\":\"reasoning-1-13\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":13,\"page\":8,\"text\":\"13. There are four friends Roy, Prem, Amar and Dhir\\n\\n1. Each one plays one of the following games - Badminton, Hockey, Tennis and Cricket\\n2. Each owns only one of the following coloured cars - Red, Blue, White and Yellow\\n3. Prem owns a white car and plays cricket\\n4. Amar does not play either Badminton or Tennis and does not own a yellow car.\\n5. Dhir does not play Badminton and owns a red car.\\n\\nWho plays Badminton and owns a yellow car?\\n\\nA. Amar\\nB. Dhir\\nC. Roy\\nD. Prem\",\"answer\":\"Roy\",\"explanation\":\"\"},{\"id\":\"reasoning-1-14\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":14,\"page\":8,\"text\":\"14. Eight persons P, Q, R, S, T, U, V and W are sitting around the circular table facing the\\ncentre. U is sitting between S and W. P is facing W and T is second to the left of W. S is third\\nto the right of Q, who is second to the right of V.\\nWho is sitting between R and V ?\\n\\nA. Q\\nB. S\\nC. T\\nD. P\",\"answer\":\"P\",\"explanation\":\"\"},{\"id\":\"reasoning-1-15\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":15,\"page\":9,\"text\":\"15.  In a coded from A+B means A is the daughter of B; A x B means A is the brother of B; A/B\\nmeans A is the husband of B and A-B means A is the sister of B. Which of the following\\nShows that T is the niece of P?\\n\\nA. (T/ S-R+ Q x P)\\nB. (P+ Q x R- S+T)\\nC. (P x Q-R/S+T)\\nD. (T- S+R x Q/P)\",\"answer\":\"(T- S+R x Q/P)\",\"explanation\":\"\"},{\"id\":\"reasoning-1-16\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":16,\"page\":10,\"text\":\"16. If \u2018AxB\u2019 means \u2018A\u2019 is the grandfather of \u2018B\u2019, \u2018A- B\u2019 means \u2018A\u2019 is the son of \u2018B\u2019, \u2018A/B\u2019\\nmeans \u2018A\u2019 is the wife of \u2018B\u2019, \u2018A+B\u2019 means \u2018A\u2019 is the father of \u2018B\u2019 and \u2018A*B\u2019 means \u2018A\u2019 is the\\nbrother of \u2018B\u2019 then how is \u2018A\u2019 related to \u2018G\u2019 in A / B x D - C * F + G ?\\n\\nA. Grand-Mother\\nB. Grand-son\\nC. Grand-father\\nD. Grand-daughter\",\"answer\":\"Grand-Mother\",\"explanation\":\"\"},{\"id\":\"reasoning-1-17\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":17,\"page\":10,\"text\":\"17. Three statements  are given followed by two conclusions. Consider the statements  to be true\\nevents if they seem to be at variance from commonly known facts and decide which of the\\ngiven conclusion(s) logically follow(s) from the given statements.\\n\\nStatement:\\nA. Some doctors are musicians.\\nB. Some dancers are signers\\nC. All singers are musicians\\n\\nConclusion:\\nI. All dancers are musicians\\nII. Some singers are doctors\\n\\nA. Only conclusion ii follows\\nB. Only conclusion i follows\\nC. Both conclusions i and ii follows\\nD. Both conclusion i and ii do not follow\",\"answer\":\"Both conclusion i and ii do not follow\",\"explanation\":\"\"},{\"id\":\"reasoning-1-18\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":1,\"number\":18,\"page\":11,\"text\":\"18. A statement is followed by two assumptions numbered I and II. Consider the statement and\\ndecide which of the given assumptions are appropriate.\\n\\nStatement:\\nThe workers are protesting against the new incentive policy which has been implemented this\\nyear by the management this year\\n\\nAssumptions:\\nI. The workers are not happy with the changes that have been made in the new incentive\\npolicy.\\nII. The management has assured the workers for redrafting the policy to avoid further protests\\n\\nA. Only II is implicit\\nB. Neither I or II is implicit\\nC. Both I and II are implicit\\nD. Only I is implicit\",\"answer\":\"Only I is implicit\",\"explanation\":\"workers are not happy is the reason of protest, only i is implicit.\"},{\"id\":\"reasoning-2-1\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":1,\"page\":12,\"text\":\"1. In the following diagram, the triangle stands for \u2018males\u2019, the circle for \u2018doctors\u2019, the\\nrectangle for \u2018government employed\u2019, the hexagon for \u2018corona warriors\u2019. The\\nnumbers in different segments show the number of persons for that segment. How\\nmany government employed doctors are either corona warriors or males or both?\\n\\nA. 22\\nB. 73\\nC. 35\\nD. 38\",\"answer\":\"73\",\"explanation\":\"35 + 22 + 16 = 73\"},{\"id\":\"reasoning-2-2\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":2,\"page\":12,\"text\":\"2.  A statement followed by two assumptions numbered i and ii. Consider the statement and\\ndecide which of the given assumptions is implicit in the statement.\\nStatement:\\nEven though enough support is provided for potato production and its storage in cold stores,\\nthe state will continue to import from other countries.\\nAssumptions:\\ni. In spite of the support, the potato production and storage will not be able to meet the\\ndemand for potatoes by the people in the state.\\nii. The state is aware that the demand for potatoes by the consumers would rise substantially\\nin the near future.\\n\\nA. Only ii is implicit\\nB. Both i and ii are implicit\\nC. Neither i nor ii is implicit\\nD. Only i is implicit\",\"answer\":\"Both i and ii are implicit\",\"explanation\":\"Both i and ii are implicit\"},{\"id\":\"reasoning-2-3\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":3,\"page\":13,\"text\":\"3.  A team of four players are to be selected from among four girls A, B, C, D and four boys P,\\nQ, R, S such that there would be at least two girls in the team and the team selection should\\nmeet the following conditions:\\ni. B cannot go with R\\nii. D and P must go together\\niii. S cannot be put up with A\\niv. R and C must be together\\nWhich of the given options is possible to form a team satisfying the above conditions?\\n\\nA. QBSC\\nB. RCQS\\nC. BPRA\\nD. DAPQ\",\"answer\":\"DAPQ\",\"explanation\":\"B & R is not possible; D & P is possible; S & A is not possible; R & C is possible\\nQBSC \u2013 Ruled out because R & C should be together\\nRCQS \u2013 Ruled out because the statement says at least 2 girls (at least 2 means minimum\\n2\u2026it can be more than 2 as well) In RCQS there is only 1 girl\\nBPRA - Ruled out because B & R cannot go together\\nDAPQ \u2013 Satisfies all the conditions.\"},{\"id\":\"reasoning-2-4\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":4,\"page\":13,\"text\":\"4. Each of the five students, P, Q, R, S and T study two subjects from the given subjects named\\nHistory, Mathematics, English, Sanskrit, and Science. Each subject is studied by two\\nstudents.\\ni.  P studies Mathematics and Sanskrit\\nii. R studies History and Mathematics\\niii. S and T both study English\\niv. Q does not study science\\nWho from the given options study\u2019s science?\\n\\nA. P\\nB. Q\\nC. R\\n\\nD. S\",\"answer\":\"S\",\"explanation\":\"P - Mathematics and Sanskrit\\nQ - Does not study Science\\nR - Mathematics and History\\nS - English\\nT - English\\nGiven, each student studies only 2 subjects and each subject is studied by two students.\\nHence, S and T study Science. From the given options, S is the answer.\"},{\"id\":\"reasoning-2-5\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":5,\"page\":14,\"text\":\"5.  A statement is followed by three assumptions numbered I, II and III. Consider the statement\\nand decide which of the given assumption(s) is/are implicit in the statement.\\nStatement:\\nPunishment of students in any form by teachers is banned in all schools to preserve the\\nself-confidence of students.\\nAssumptions:\\nI. Punishment in a mild form is not a cognizable offence in out-of-school as it is a method for\\ndisciplining children.\\nII. Teachers taking recourse to punishing children will be held accountable for their actions.\\nIII. Punishment might induce fear, negatively affecting students\u2019 level of confidence and\\nlearning.\\n\\nA. Only III is implicit\\n\\nB. Only I and II are implicit\\nC. Only II is implicit\\n\\nD. Only II and III are implicit\",\"answer\":\"Only III is implicit\",\"explanation\":\"Only III is implicit. (Please Note: Assumption II is not implicit)\"},{\"id\":\"reasoning-2-6\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":6,\"page\":14,\"text\":\"6. Given below is a question followed by two statements, I and II, each containing some\\ninformation. Decide which of the statement(s) is/are sufficient to answer the question.\\n\\nHow is Sheela exactly related to Ramesh?\\n\\nStatements:\\nI. Mary\u2019s brother Vikash is married to Sheela and Ramesh\u2019s mother is the sister of Mary.\\nII. Sheela is the sister of Vikash and Vikash\u2019s only child is the cousin brother of Ramesh.\\n\\nA. Both the statements I and II are necessary\\nB. Both the statements I and II together are not sufficient\\nC. Statement II alone is sufficient\\nD. Statement I alone is sufficient\",\"answer\":\"Statement I alone is sufficient\",\"explanation\":\"From Statement I we can derive that Sheela is Aunt of Ramesh.\\nFrom Statement II we cannot exactly derive the relationship between Sheela and Ramesh.\\nHence, Statement I alone is sufficient\"},{\"id\":\"reasoning-2-7\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":7,\"page\":15,\"text\":\"7. In each of the five pairs of the letter-clusters, the letters in the second term is a rearranged/\\ntransformed form of the letters in the first term in a particular pattern. In which two pairs has\\nthe transformation been done the same way?\\n\\n1) MASON : AMNOS\\n2) PARTY : APRYT\\n3) FAULT : AFTLU\\n4) LODGE : DOLEG\\n5) CARGO : ACOGS\\n\\nA. 2 and 3\\nB. 3 and 4\\nC. 1 and 3\\nD. 4 and 5\",\"answer\":\"1 and 3\",\"explanation\":\"1 and 3 are the pairs that have the transformation done the same way in the second term.\"},{\"id\":\"reasoning-2-8\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":8,\"page\":15,\"text\":\"8. There are five rods K, L, M, N and O. The weight of L is equal to the weights of K and M\\ntaken together. The weight of M is twice the weight of K. The weight of N is three times the\\nweight of M. If the weight of N is 90 kg, what will be the weight of O?\\n\\nA. 120 kg\\nB. 60 kg\\nC. 105 kg\\nD. 90 kg\",\"answer\":\"105kg\",\"explanation\":\"Given,\\nThe weight of O is twice L, O = 2L --- Eq (1)\\nThe weight of L is equal to the weights of K and M together,\\nL = K+M --- Eq (2)\\nThe weight of M is twice the weight of K, M = 2K --- Eq (3)\\nThe weight of N is three times the weight of M, N = 3M --- Eq (4)\\nGiven, N = 90 kg --- Eq (5)\\nFrom Eq (4), 3M = 90\\nM = 30 --- Eq (6)\\nSubstitute Eq (6) in Eq (3)\\n30 = 2K\\nK = 15\\nSubstitute the value of K and M in Eq (2)\\nL = 15 + 30 = 45\\nNow, substitute the value of L in Eq (1)\\nO = 2(45) = 90 kg.\"},{\"id\":\"reasoning-2-9\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":9,\"page\":16,\"text\":\"9. Which of the following patterns of the boxes can be formed when the sheet given below is\\nfolded? (if the letters are shown to indicate the sides only).\\n\\nA. Only 1 and 2\\nB. Only 2 and 3\\nC. Only 2\\n\\nD. Only 1, 2 and 4\",\"answer\":\"Option C\",\"explanation\":\"If you look at the given option figures, Figure 1 can be eliminated straightaway since G and\\nwill be opposites.\\nHence, Option A and D are ruled out\\nFigure 3 can also be eliminated because N and M should be opposites. Hence, Option B is\\nalso ruled out.\\nThe correct pattern amongst the 4 option figures is only Figure 2. Hence, Option C is the\\ncorrect answer.\"},{\"id\":\"reasoning-2-10\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":10,\"page\":17,\"text\":\"10. A paper is folded and cut as shown below. How will it appear when unfolded?\",\"answer\":\"Option D\",\"explanation\":\"\",\"imageId\":\"reason-paper-fold\"},{\"id\":\"reasoning-2-11\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":11,\"page\":18,\"text\":\"11.  In the following diagram, the triangle stands for \u2018males\u2019, the circle for \u2018doctors\u2019, the rectangle\\nfor \u2018government employed\u2019, the hexagon for \u2018corona warriors\u2019. The numbers in different\\nsegments show the number of persons for that segment. How many government employed\\ndoctors are Corona warriors but are not males?\\n\\nA. 23\\n\\nB. 16\\n\\nC. 14\\n\\nD. 7\",\"answer\":\"16\",\"explanation\":\"If you observe the given diagram, rectangle stands for government employed, circle is for\\ndoctors, hexagon is for corona warriors and triangle is for males. 16 is the number which\\nsatisfies all the given conditions.\",\"imageId\":\"reason-venn\"},{\"id\":\"reasoning-2-12\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":12,\"page\":18,\"text\":\"12.  The following are the criteria of selecting a Software Engineer for an IT company.\\nThe candidates must:\\na. Have completed BCA with more than 70% marks.\\nb. Be more than 25 years and less than 30 years of age as on June 1, 2020.\\nc. Have secured more than 75% marks in the interview and more than 60% marks in the\\nwritten test.\\n\\nHowever, if the candidate fulfills all of the above criteria except:\\nd. At b, but has completed MCA with at least 75% marks, his/her case is to be referred to the\\nManaging Director.\\ne. At c, but has secured more than 85% marks in BCA, his/ her case is to be referred to the\\nChief Executive Officer.\\n\\nKeith completed BCA and MCA with 76% and 72% marks respectively. He has completed\\n27 years of age in the year 2019. He has secured 65% marks in the written test and 78%\\nmarks in the interview. What decision would be taken in his case?\\n\\nA. His case is to be referred to the Managing Director\\nB. He would not be selected\\nC. His case is to be referred to the Chief Executive Officer\\nD. He would be selected.\",\"answer\":\"He would be selected.\",\"explanation\":\"Condition a: Have completed BCA with more than 70% marks - Keith has 76% marks in\\nBCA \u2013 Satisfied\\nCondition b: Be more than 25 years and less than 30 years of age as on June 1, 2020 \u2013 Keith\\nhas completed 27 years of age in the year 2019. As on June 1, 2020, Keith will be 28 years\\nold - Satisfied\\nCondition c: Have secured more than 75% marks in the interview and more than 60% marks\\nin the written test \u2013 Keith scored 78% marks in the interview and 65% marks in the written\\ntest \u2013 Satisfied\\nHence, He would be selected.\"},{\"id\":\"reasoning-2-13\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":13,\"page\":19,\"text\":\"13. Nehal, Iqbal, Ronit, Malini and Harbhajan participate in any one of the five activities i.e.\\nQuiz, Singing, Dance, Debate and Mimicry. Ronit participates in Singing. Harbhajan does not\\nparticipate in Debate and Mimicry.\\nMalini does not participate in Mimicry. Iqbal participates in Quiz. Who participates in\\nDebate?\\n\\nA. Malini\\n\\nB. Nehal or Malini\\n\\nC. Nehal\\n\\nD. Cannot be determined\",\"answer\":\"Malini\",\"explanation\":\"Ronit \u2013 Singing\\nIqbal \u2013 Quiz\\nHarbhajan does not participate in Debate and Mimicry. So, Harbhajan \u2013 Dance\\nMalini does not participate in Mimicry. So, Malini \u2013 Debate\\nNeha \u2013 Mimicry\"},{\"id\":\"reasoning-2-14\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":14,\"page\":20,\"text\":\"14. Select the figure that will replace the question mark in the following figure series.\",\"answer\":\"Option C\",\"explanation\":\"1. If you observe the series, the figure in the top left corner appears as a middle figure in the\\nnext set. In the first set, Arrow is in the top left corner and in the next set, it is the middle\\nfigure. So, options B and D are ruled out.\\n2. The figure in the middle appears in the bottom left-hand corner in the next set. In the first set,\\nCircle is the middle figure in the first set and in the next set, it is in the bottom left-hand\\ncorner. So, star should in the bottom left-hand corner in the last set. Amongst A and C, A is\\nruled out. Hence, Option C.\",\"imageId\":\"reason-figure-series\"},{\"id\":\"reasoning-2-15\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":15,\"page\":20,\"text\":\"15. Two statements are given followed by three conclusions numbered I, II and III. Assuming the\\nstatements to be true, even if they seem to be at variance with commonly known facts, decide\\nwhich of the conclusions logically follow(s) from the statements.\\n\\nStatements:\\nAll animals are plants.\\n\\nAll plants are shrubs.\\n\\nConclusions:\\nI. Some shrubs are plants\\nII. Some animals are not shrubs\\nIII. All animals are shrubs\\n\\nA. None of the conclusions follow\\n\\nB. Only conclusions I and III follow\\nC. Only conclusion II follows\\n\\nD. Only conclusions I and II follow\",\"answer\":\"Only conclusions I and III follow\",\"explanation\":\"Only I and III follow\"},{\"id\":\"reasoning-2-16\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":16,\"page\":21,\"text\":\"16. Given below is a question followed by two statements I and II, each containing some\\ninformation. Decide which of the statements are sufficient to answer the question that\\nfollows.\\nHow many Rupees would Shalini need to spend to buy 11 pencils and 14 pens?\\nI. Shalini spent an amount of Rs.201 to buy 15 pencils and 12 pens.\\nII. Shalini spent an amount of Rs.121 to buy 7 pencils and 9 pens.\\n\\nA. The combination of both the statements I and II are not sufficient.\\nB. Statement II alone is sufficient.\\nC. Statement I alone is sufficient.\\nD. The combination of both the statements I and II are necessary.\",\"answer\":\"The combination of both the statements I and II are necessary.\",\"explanation\":\"Let the cost of pencils be x and pens be y.\\nWe need to find: 11x + 14y\\nFrom Statement I: 15x + 12y = 201 We cannot find the value of 11x + 14y from Statement I\\nalone.\\nFrom Statement II: 7x + 9y = 121 We cannot find the value of 11x + 14y from Statement I\\nalone.\\nCombining Statements, I and II, we can find the value of x and y. Hence, The combination\\nof both the statements I and II are necessary.\"},{\"id\":\"reasoning-2-17\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":17,\"page\":22,\"text\":\"17.  The following are the criteria for selecting a school psychologist for a reputed school.\\nThe candidates must:\\n(i) be a Postgraduate in Psychology with more than 60% in the Postgraduate examination.\\n(ii) have Postgraduate diploma in Guidance and Counseling.\\n(iii) have secured more than 65% in the interview and at least 60% in the written test.\\n(iv) have at least 3 years of experience in the relevant area.\\n\\nIn case of the candidates who satisfies all other criteria except -\\n(a) at (i), above, but has secured more than 65% in the written test as well as in the interview,\\nhis/her case is to be referred to the Management.\\n(b) at (ii) and (iii) above, but has more than ten-year experience in relevant field, his/her case\\nis to be referred to the Principal.\\nDinesh has done his master\u2019s degree in Psychology with 65% of marks. For the last 10 years,\\nhe has been working as a school psychologist/counselor. He scored 55% in written test and\\n50% in the interview.\\n\\nBased on these criteria and information provided, decide the course of action.\\n\\nA. Could not be selected\\n\\nB. Refer to the management\\nC. Could be selected\\n\\nD. Refer to the principal\",\"answer\":\"Refer to the principal\",\"explanation\":\"(i) be a Postgraduate in Psychology with more than 60% in the Postgraduate examination -\\nCondition Satisfied\\n(ii) have Postgraduate diploma in Guidance and Counseling - Condition Not Satisfied\\n(iii) have secured more than 65% in the interview and at least 60% in the written test -\\nCondition Not Satisfied\\n(iv) have at least 3 years of experience in the relevant area - Condition Satisfied\\n\\nHowever, Point (b) mentions that if a has more than ten-year experience in relevant field,\\nhis/her case is to be referred to the Principal. Since Dinesh has been working as a school\\npsychologist/counselor for the last 10 years, his case is to be referred to the Principal.\"},{\"id\":\"reasoning-2-18\",\"sourceKey\":\"reasoning\",\"source\":\"TCS Reasoning Ability\",\"file\":\"TCS_Reasoning Ability Set 1 and Set 2_Trainer Handout .pdf\",\"category\":\"Reasoning Ability\",\"set\":2,\"number\":18,\"page\":22,\"text\":\"18. Given below is a question followed by three statements, I, II and III, each containing some\\ninformation. Decide which of the statement(s) is/are sufficient to answer the question.\\n\\nHow is A related to B?\\n\\nStatements:\\n\\nI. A is husband of C.\\nII. C has two children B and D.\\nIII. C is married to D's father A.\\n\\nA. Statement III alone is sufficient\\n\\nB. Either I and II or II and III together are sufficient\\nC. Statement Il alone is sufficient\\n\\nD. Statement I alone is sufficient\",\"answer\":\"Either I and II or II and III together are sufficient\",\"explanation\":\"From Statement I: A is the husband of C. Using Statement I alone, we cannot find the\\nrelationship between A & B\\nFrom Statement II: C has two children B and D. Using Statement II alone, we cannot find the\\nrelationship between A & B\\nFrom Statement III: C is married to D's father A. Using Statement III alone, we cannot find\\nthe relationship between A & B\\n\\nCombining Statements I and II, we get; A is the father of B.\\nCombining Statements II and III, we get; A is the father of B.\\nHence, Either I and II or II and III together are sufficient.\"},{\"id\":\"verbal-1-1\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":1,\"page\":1,\"text\":\"1. You are going to read a text about Dragons. Some sentences are missing from the text, Choose\\nfrom the list (A-C) the most appropriate sentence for each gap (1-2) in the text. There is one\\nextra sentence that you do NOT need to use.\\n\\nDragons are mythical creatures known as Lung in China. 1._____________ They were also\\nbelieved to control the weather. 2.____________This is why in the ancient Chinese tradition,\\nemperors were believed to be successors of dragons.\\n\\nA. In China, dragon dolls and motifs dance during festivals.\\nB. They were believed to be snake-like creatures who can fly and spit fire from their mouths\\nC. These colourful snake-like creatures had a fearful appearance but they were symbols of good\\nluck and strength\\n\\nA. (1)-A,(2)-B\\nB. (1)-B,(2)-C\\nC. (1)-B,(2)-A\\nD. (1)-C,(2)-B\",\"answer\":\"(1)-B,(2)-C\",\"explanation\":\"They in B refers to dragons in the previous statement. So blank 1 should have B.\\nContinuing to it. These colourful snake like creatures should be in blank 2. Since 'these'\\nrepresent the  snake like creature which was introduced in B.\\n\\nSo the right pick is 1. B, 2. C\"},{\"id\":\"verbal-1-2\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":2,\"page\":1,\"text\":\"2. Read the following sentence and fill in the blanks by selecting the appropriate word.\\n\\nIn the prehistoric age, the early humans were hunters and gatherers who lived nomadically,\\nTheir_____were mostly caves or camps near water.\\n\\nA. dwellings\\nB. hermitages\\nC. villages\\nD. Schools\",\"answer\":\"dwellings\",\"explanation\":\"The required blank talks about the place they live. The only options which talks\\nabout such a place to live is dwellings which means a place of residence.\"},{\"id\":\"verbal-1-3\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":3,\"page\":2,\"text\":\"3. Which of these sentences represents the CORRECT indirect narration of the given sentence?\\nThe student said to the teacher,\u201dAre all these questions compulsory\u201d?\\n\\nA. The student asked the teacher if all those questions are compulsory.\\nB. The student asked the teacher if all these questions are compulsory.\\nC. The student asked the teacher if all those questions were compulsory.\\nD. The student asks the teacher if all these questions are compulsory\",\"answer\":\"The student asked the teacher if all those questions were compulsory.\",\"explanation\":\"From Direct to Indirect speech, Simple present changes to simple past. Only\\noption C has a simple past helping verb (were).\"},{\"id\":\"verbal-1-4\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":4,\"page\":2,\"text\":\"4. One part of the sentence below may contain an error. Identify the part. If there is no error,\\nchoose \u2018No Error\u2019\\n\\nAlthough he is from one of the premier college, he is not placed with an established company.\\n\\nA. premier college, he is not placed\\nB. No error\\nC. Although he is from one of the\\nD. with an established company.\",\"answer\":\"premier college, he is not placed\",\"explanation\":\"'One of the premier colleges'. one of the represents one out of many.\"},{\"id\":\"verbal-1-5\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":5,\"page\":2,\"text\":\"5. The following sentences can be revised into one better sentence. Choose the sentence that is\\nthe best revision.\\n\\nThe principal met the students. The principal had won an award.\\n\\nA. The principal met the students who had won an award.\\nB. The principal met the students and they had won an award.\\n\\nC. The principal who had won an award met the students.\\nD. The principal met the students and won an award.\",\"answer\":\"The principal who had won an award met the students.\",\"explanation\":\"The first two options give a different meaning which say students are the one\\nwho won award, which is contradictory to the actual sentence in the question.\\n\\nLast option says the time factor met students and then won an award, which is again never\\nmentioned in the question sentence.\\n\\nSo, the right answer is Option 3, The principal who had won an award met the students.\"},{\"id\":\"verbal-1-6\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":6,\"page\":3,\"text\":\"6. One part of the sentence below may contain an error. Identify the part. If there is no error,\\nchoose \u2018No error\u2019\\n\\nWhatever she said in her defence was not taken seriously by the investigating authorities.\\n\\nA. No error\\nB. Whatever she said in her defence\\nC. by the investigating authorities\\nD. was not taken seriously\",\"answer\":\"No error\",\"explanation\":\"There is no error in the sentence.\"},{\"id\":\"verbal-1-7\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":7,\"page\":3,\"text\":\"7. For the four sentence (S1 to S4) paragraph below, sentences S1 and S4 are given, From the\\noptions P, Q and R choose appropriate sentences for S2 and S3 respectively.\\n\\nS1: In India, the president enjoys the power to veto a bill\\n\\nS2:\\n\\nS3:\\n\\nS4: In practice, though, this power has been exercised only by a few former presidents\\n\\nP: it gives the president a unilateral authority to reject a bil\\n\\nQ: the constitution, however, does not state the provisions of veto explicitly\\n\\nR: The Indian Prime Minister, on the other hand, has other duties to fulfil\\n\\nA. RP\\nB. PR\\nC. QR\\nD. PQ\",\"answer\":\"PQ\",\"explanation\":\"\\\"It\\\" in P talks about the power that the president has.\\nSo after S1, P should come and there is nothing to talk about the prime minister's powers\\nhere, So R can be eliminated. So, the right choice is PQ.\"},{\"id\":\"verbal-1-8\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":8,\"page\":4,\"text\":\"8. One part of the sentence below may contain an error. Identify the part. If there is no error,\\nchoose \u2018No Error\u2019\\nToday most of the major cities of India/ are facing the twin challenges of rising air pollution/\\nand growing contamination of water\\n\\nA. and growing contamination of water\\nB. Today most of the major cities of India\\nC. are facing the twin challenges of rising air pollution\\nD. No Error\",\"answer\":\"No Error\",\"explanation\":\"There is no error in the sentence. Since subject verb agreement is followed.\"},{\"id\":\"verbal-1-9\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":9,\"page\":4,\"text\":\"9.  Select the most appropriate option to fill in the blank.\\nThe exotic remedies for some illnesses have been ________ from generation to generation.\\n\\nA. handed in\\nB. handed down\\nC. handed over\\nD. handed out\",\"answer\":\"handed down\",\"explanation\":\"Since meaning in the blank should be Passing from one generation to other\\ngeneration, the only word from the options which gives passing meaning is Handed down.\"},{\"id\":\"verbal-1-10\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":10,\"page\":5,\"text\":\"10.  One part of the sentence below may contain an error. Identify the part.\\nSomething about the way he spoke stuck a bell in Lauren\u2019s mind.\\n\\nA. stuck in bell\\nB. in Lauren\u2019s mind\\nC. way he spoke\\nD. Something about\",\"answer\":\"stuck in bell\",\"explanation\":\"It should be 'struck instead of stuck'. Struck a bell gives a meaning of remind\\nyou of something.\"},{\"id\":\"verbal-1-11\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":11,\"page\":5,\"text\":\"11. One part of the sentence below may contain an error. Identify the part, if there is no error,\\nchoose \u201cno error\u201d.\\n\\nNot a single flower seed / which Asha planted / have germinated\\n\\nA. Which Asha planted\\nB. No error\\nC. Have germinated\\nD. Not a single flower seed\",\"answer\":\"Have germinated\",\"explanation\":\"Since the subject is talking about a single flower seed, the subject is singular.\\nbut given 'have germinated', which talks about the plural verb.\\nSo the helping verb should be has germinated,\\nCorrect sentence: Not a single flower seed / which Asha planted / has germinated\"},{\"id\":\"verbal-1-12\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":12,\"page\":5,\"text\":\"12. You are going to read a text about scrubs diving. Some sentences are missing from the text,\\nchoose from the list (A-C) the most appropriate sentence for each gap (1-2) in text. There is\\none extra sentence that you do not need to use.\\n\\nScuba divers are trained to use hand signals to communicate with their buddies\\n______1_______ Not only this, the same system has proved very useful for communication\\nbetween the driver and the surface ship.________2________ All these developments have\\nmade scuba diving a very exciting recreational sport for all age groups.\\n\\nA. Today there are advanced acoustic systems for use by scuba divers which enables them to\\ntalk to each other underwater.\\nB. They are also trained to use underwater writing boards for better communication.\\nC. Scuba diving does not require more effort than walking or leisure biking.\\n\\nA. 1.C 2.B\\nB. 1.B 2.A\\nC. 1.B 2.C\\nD. 1.A 2.C\",\"answer\":\"1.B 2.A\",\"explanation\":\"'also trained to' is an addition to 'trained to'. So, blank 1 is B.\\nAfter blank 2, All these developments, should be talking about the development that is\\nmentioned in blank 2 and A talks about advanced systems which is alo a development.\\nSo, 1. B, 2. A\"},{\"id\":\"verbal-1-13\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":13,\"page\":6,\"text\":\"13. Select the most appropriate option to complete the sentence.\\n\\nWhile MSME\u2019s are awaiting ____  the release ___ around Rs. five lakh crore pending\\npayments, no major relief has come their way so far.\\nA. to, with\\nB. of, at\\nC. for, of\\nD. from, on\",\"answer\":\"for, of\",\"explanation\":\"The first blank can not have waiting to/of/from.\\nSo, waiting for the release and release of around would be the right fits in the blanks.\"},{\"id\":\"verbal-1-14\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":14,\"page\":6,\"text\":\"14.  Read the passage given below and answer the questions that follow:\\n\\nThe Academy of Motion Picture Arts and Sciences was incorporated in May 1927. Its goal\\nwas to achieve outstanding achievements in the different branches of film production, thus\\nimproving the quality of all aspects of motion picture production.\\n\\nThe art director of Metro-Goldwyn-Mayer (MGM) Studios Cedric Gibbons sketched the\\niconic statuette of the award. It was the figure of a knight holding a sword standing on a base\\n\\nwrapped with a film reel. Los Angeles sculptor George Stanley realised this design in three\\ndimensions.\\n\\nThe statuette is thirteen and a half inches tall and weighs right and a half pounds. The design\\nof the statuette has never changed but the size of the base was changed in 1945 and remains\\nthe same since then.\\n\\nEvery January, these golden statuette are hand-cast in bronze and then electroplated with 24\\nkarat gold in Brooklyn. The first of the Academy Awards was given away on 16th May 1929.\\nSInce then, over five thousand statuettes have been presented.\\n\\nOfficially named the Academy Award of Merit, the statuette is better known by its nickname,\\nOscar. Sources have it that the Academy librarian and later executive director Margaret\\nHerrick said the statuette resembled her Uncle Oscar. Thereafter, the Academy staff began\\nreferring to it as Oscar and the name stuck!\\n\\nWhich of the following best describes the purpose of incorporating the Academy of Motion\\nPicture Arts and Sciences?\\n\\nA. To honour outstanding achievements in the different branches of film production\\nB. To give away more than three thousand Academy Awards of Merit statuettes\\nC. To encourage art studies in Brooklyn to make bronze statuettes and electroplate them\\nin 24-karat gold\\nD. To encourage art directors and sculptors to design statuettes for awards\",\"answer\":\"To honour outstanding achievements in the different branches of film production\",\"explanation\":\"-\"},{\"id\":\"verbal-1-15\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":15,\"page\":7,\"text\":\"15. Which of the following statements about the Academy Awards statuette is TRUE?\\n\\nA. The statuette is made of bronze and gold\\nB. The base of the statuette has never changes since it was first designed\\nC. The statuette is a figure of a bishop holding a sword standing on a base wrapped with\\na film reel\\nD. The statuette is fourteen inches tall\",\"answer\":\"The statuette is made of bronze and gold\",\"explanation\":\"-\"},{\"id\":\"verbal-1-16\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":16,\"page\":8,\"text\":\"16. Which of the following sentences uses formal language?\\n\\nA. The report checked out the implications of capitalism.\\nB. You finished your assignment yet?\\nC. She\u2019s decided to quit.\\nD. The meeting is scheduled to commence at 10 AM.\",\"answer\":\"The meeting is scheduled to commence at 10 AM.\",\"explanation\":\"Checked out is not the . proper word to be used.\\n2 Sentence is not at all properly framed, in terms of meaning too.\\n3. Uses a contraction (she's instead of she is), so informal.\\nSo 4 is the formal language.\"},{\"id\":\"verbal-1-17\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":17,\"page\":8,\"text\":\"17. You are going to read a text about fighting pollution. Some sentences are missing from the\\ntext. Choose from the list (A-C) the most appropriate sentence for each gap (1-2) in the text.\\nThere is one extra sentence that you do not need to use.\\n\\nA team of scientists at the University of Portsmouth of England has developed a new enzyme\\nthat has the ability to break down plastics up to six times faster than standard enzymes,\\naccording to CNN (1) ___________ In reducing the amount of non- biodegradable plastic on\\nEarth, enzymes have been used to help combat pollution by breaking down polyethylene\\nterephthalate (PET) chain molecules, the most common thermoplastic that makes up everyday\\nitems like single-use bottles, clothing, and carpet. (2)________ The first altered enzyme was\\ncalled PETase, which will now be connected with MHETase to create the University\u2019s new\\nenzyme protein. Between these two enzymes connecting, PET chains in plastic were found to\\nbreak down twice as fast as PETase alone.\\n\\nA- The researchers, who had earlier engineered an enzyme found within bacteria of a plastic\\nbottle combined it with a second enzyme to accelerate the breakdown of plastics.\\n\\nB- A tool called the Diamond  Light Source was used to map the molecular structure of\\nMHETase.\\n\\nC- Enzymes, proteins that are key components in chemical reactions within the human body,\\nact as catalysts that speed up the breakdown of substances.\\n\\nA. 1-B, 2-A\\nB. 1-B, 2-C\\nC. 1-A, 2-B\\nD. 1 C, 2- A\",\"answer\":\"1 C, 2- A\",\"explanation\":\"After the second blank there are two sentences which talks about the first enzyme and one\\nmore sentence that talks about the between the two enzymes. Out of the three only A talks\\nabout the second enzyme. So, blank 2 can only have C.\\nSo we can eliminate B and C options.\\n\\nIn between A and D. First blank is talking about the breaking down of enzymes, which is\\ncontinued in the next sentence too. So the first bank can be only C.\\nSo, 1. C, 2. A\"},{\"id\":\"verbal-1-18\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":18,\"page\":9,\"text\":\"18.  Select the most appropriate option to fill in the blank.\\n\\nThe security guard _____ leave ended two days ago has not yet reported back to work.\\n\\nA. whom\\nB. who\\nC. which\\nD. whose\",\"answer\":\"whose\",\"explanation\":\"Since we are talking about the leave that is related to the security guard, there must be a\\npossessive form of pronoun to be used. The only possessive word which fits the best is\\nWhose. So, the security guard whose leave ended two days ago has not yet reported back to\\nwork\"},{\"id\":\"verbal-1-19\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":19,\"page\":9,\"text\":\"19. One part of the sentence below may contain an error. Identify the part. If there is no error,\\nchoose \u2018No Error\u2019\\n\\nThe use of some chemical substance for disinfection in primary schools trigger allergic\\nreactions in some children\\n\\nA. The use of some chemical substance for\\nB. disinfection in primary schools\\nC. No error\\nD. trigger allergic reactions in some children\",\"answer\":\"The use of some chemical substance for\",\"explanation\":\"It should be 'chemical subtances', since they are talking about the subtances\\nthat gave reactions.\"},{\"id\":\"verbal-1-20\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":20,\"page\":10,\"text\":\"20.  Select the most appropriate option to fill in the blanks:\\n\\nThe Starks _____________  the North for thousands of years.\\n\\nA. Was ruling\\nB. Has ruled\\nC. Rules\\nD. Have ruled\",\"answer\":\"Have ruled\",\"explanation\":\"The Starks is a plural subject. So, a plural helping verb to be used.\\nwas, has and rules are singular helping verbs. The only plural verb is Have. So, Have ruled is\\nthe answer.\"},{\"id\":\"verbal-1-21\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":21,\"page\":10,\"text\":\"21. Select the most appropriate option to fill in the blanks\\n\\nIf I were you. I____a complaint.\\n\\nA. May lodge\\nB. Would lodge\\nC. Can lodge\\nD. Will lodge\",\"answer\":\"Would lodge\",\"explanation\":\"If I were you ... is used when giving ADVICE about what you would do in the same situation\\nas the other person.\\nYou imagine yourself in their position or situation and what you would do or how you would\\nreact.\\nIf I were you, I would study more. If I were you, I would stop doing that.\\nSo, would lodge.\"},{\"id\":\"verbal-1-22\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":22,\"page\":11,\"text\":\"22. You are going to read a text about counselling. Some sentences are missing from the text.\\nChoose from the list (A-C) the most appropriate sentence for each gap(1-2) in the text. There\\nis one extra sentence that you do not need to use\\n\\nTo help you on the path to achieving your vision, you may find it useful to employ the\\nJapanese Techniques of Kaizen and Kaikaku, or continuous improvement and radical changes\\n1.________________ Kaikaku takes place less often. 2.__________. Look out for the\\nopportunities for radical change and use them.\\n\\nA. The shinobis who used to dominate Japan are rare or rather extinct in this modern world\\nB. Kaizen involves constantly looking for ways to improve any element of your performance\\nC. It could be going into business of yourself, moving to a new job in a new industry or new\\ncompany or both\\n\\nA. BA\\nB. AC\\nC. BC\\nD. CB\",\"answer\":\"BC\",\"explanation\":\"-\"},{\"id\":\"verbal-1-23\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":23,\"page\":11,\"text\":\"23.  Read the following passage and fill in the blanks by selecting the most appropriate option.\\n\\nYour mission should be broken down into a. 1_______ operating plan that will enable you to\\ntake concrete, achievable steps towards realising your mission firmly before your eyes, with\\nrevision as and when required, and direct your actions towards 2.__________ them.\\n\\nBlank 1: A. translucent B. successive C. feasible D. fixated\\n\\nBlank 2: A, planning B. relating C. perpetuating D. fulfilling\\n\\nA. (1)-D,(2)-B\\nB. (1)-C,(2)-C\\nC. (1)-A,(2)-D\\nD. (1)-C,(2)-D\",\"answer\":\"(1)-C,(2)-D\",\"explanation\":\"Blank 2 should give a meaing like towards success. The only such word is fulfilling.\\nSo options 1 and 2 are eliminated.\\nIn between C and D, the first blank can not take 'translucent', which means semi transparent.\\nSo, blank 1 - feasible. which means possible to do conveniently.\"},{\"id\":\"verbal-1-24\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":24,\"page\":12,\"text\":\"24. You are going to read a text about \u2018Philosophy\u2019 . Some sentences are missing from the text.\\nChoose from the list (A-C) the most appropriate sentence foe each gap (1-2)in the text . There\\nis one extra sentence that you do not need to use.\\n\\nPhilosophy is the quest for wisdom and underlying  principles of life ______1______ .This\\nvast knowledge and insights have paved the way for finding many answers. _____2______\\n.Philosophy in its true sense is an ongoing search for fulfilling the answers and then\\nsubsequent questions.\\n\\nA. Every generation has passed on to us its knowledge and experience of the essentials of life.\\nB. The possessions and assets for a comfortable life are not compatible with philosophy.\\nC. At the same time, it has also created plenty of questions for contemporary philosophers to\\nfind new knowledge.\\n\\nA. (1) C , (2) A\\nB. (1) A , (2) C\\nC. (1) A, (2) B\\nD. (1) B, (2) C\",\"answer\":\"(1) A , (2) C\",\"explanation\":\"-\"},{\"id\":\"verbal-1-25\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":25,\"page\":12,\"text\":\"25. For the four sentence (S1 to S4) paragraph below, sentences S1 and S4 are given, From the\\noptions P, Q and R choose appropriate sentences for S2 and S3 respectively.\\n\\nS1. The organic farming system aims at keeping the soil fertile using organic wastes.\\n\\nS2.\\n\\nS3.\\n\\nS4. These microbes may help manage weed, disease and pests dramatically\\n\\nP. These include animal wastes, farm wastes and aquatic wastes.\\n\\nQ. Other biological materials that have beneficial microbes can also be used to keep the soil\\nfertile.\\nR. The farming system has an impact on the conservation of wildlife and natural habitats.\\n\\nA. QR\\nB. PQ\\nC. QP\\nD. RQ\",\"answer\":\"PQ\",\"explanation\":\"The organic wastes mentioned in S1 are explained in P.\\nSo after S1, P comes. With P only option is 2. So, PQ is the order.\"},{\"id\":\"verbal-1-26\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":26,\"page\":13,\"text\":\"26.  Read the following passage and answer the questions that follow.\\n\\nInformation Processing Theory is cognitive theory that focuses on how the information is\\nencoded into our memory. The theory describes how our brains filter information, from what\\nwe\u2019re paying attention to in the present moment, to what gets stored in our short-term or\\nworking memory and ultimately into our long-term memory.\\n\\nThe premise of Information Processing Theory is that creating a long-term memory is\\nsomething that happens in stages;first we perceive something through our sensory memory,\\nwhich is everything we can see, hear, feel or taste in a given moment; our short-term memory\\nis what we use to remember things for very short periods, like a phone number; and long-term\\nmemory is stored permanently in our brains.\\n\\nDeveloped  by American psychologists including Goerge Miller in the 1950s, Information\\nProcessing Theory has in recent years compared the human brain to a computer. The \u2018input\u2019\\nis the information we give to the computer- or to our brains- while the CPU is likened to our\\nshort-term memory, and the hard-drive is our long-term memory.\\n\\nOur cognitive processes filter information, deciding what is important enough to \u2018save\u2019 from\\nour sensory memory to our short-term memory, and ultimately to encode into our long-term\\nmemory, imagining, problem-solving, our sense of judgement, and planning.\\n\\nWhich of the following about the human brain is TRUE?\\n\\nA. It manages the input and shifts what it wants to store\\nB. It carefully stores all the materials it is exposed to.\\nC. All human brains store the same information in the same way.\\nD. It produces the input in the same format when asked to.\",\"answer\":\"It carefully stores all the materials it is exposed to.\",\"explanation\":\"-\"},{\"id\":\"verbal-1-27\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":27,\"page\":14,\"text\":\"27. According to the passage, \u2018Information\u2019 relates to______________\\n\\nA. That which we watch in the television shows.\\nB. something we read about in the newspaper.\\nC. something we are told by our family or friends.\\nD. what we see,hear and observe around us.\",\"answer\":\"what we see,hear and observe around us.\",\"explanation\":\"-\"},{\"id\":\"verbal-1-28\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":28,\"page\":14,\"text\":\"28. This passage primarily focuses on____________\\n\\nA. The Description of Information processing theory.\\nB. How to practise information processing?\\nC. The growth and history of information processing.\\nD. The problems in information processing.\",\"answer\":\"The Description of Information processing theory.\",\"explanation\":\"-\"},{\"id\":\"verbal-1-29\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":29,\"page\":14,\"text\":\"29. The following pair of sentences can be combined into one better sentence. Choose the option\\nthat combines the two sentences best\\nSardar Patel was a strong and tactful leader. He was successful in merging all the princely\\nstates into the Indian Union. He used the method of persuasion. Sometimes he used the\\nmethod of coercion.\\n\\nA. A strong and tactful leader, Sardar Patel had been successfully using persuasion and\\ncoercion to merge the princely states into the Indian Union\\nB. Being a strong an tactful leader, Sardar Patel had been successfully using persuasion\\nand coercion to merge the princely states into the Indian Union\\nC. Sardar Patel, a strong and tactful leader, succeeded in merging all the princely states\\ninto the Indian Union using methods of persuasion and sometimes coercion\\nD. Sardar Patel, having been a strong and tactful leader, used persuasion and coercion\\nsometimes and successfully merged all the princely states into the Indian Union\",\"answer\":\"Sardar Patel, a strong and tactful leader, succeeded in merging all the princely states\",\"explanation\":\"-\"},{\"id\":\"verbal-1-30\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":30,\"page\":15,\"text\":\"30. One part of the sentence below may contain an error. Identify the part. If there is no error,\\nchoose \u201cNo error\u201d.\\nFingerprint is one of  the most effective way for criminal identification across the world.\\n\\nA. Identification across the world\\nB. No error\\nC. Effective way for criminal\\nD. Fingerprint is one of the most\",\"answer\":\"Effective way for criminal\",\"explanation\":\"-\"},{\"id\":\"verbal-1-31\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":31,\"page\":15,\"text\":\"31. The following pair of sentences can be combined into one better sentence. Choose the option\\nthat combines the two sentences best\\nHe is only 16. He is not eligible to vote in any election\\n\\nA. He is only 16 but not eligible to vote in any election\\nB. He is only 16 in spite of not eligible to vote in any election\\nC. He is only 16 therefore not eligible to vote in any election\\nD. He is only 16 else not eligible to vote in any election\",\"answer\":\"He is only 16 therefore not eligible to vote in any election\",\"explanation\":\"-\"},{\"id\":\"verbal-1-32\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":32,\"page\":15,\"text\":\"32. For the four sentence (S1 to S4) paragraph below, sentences S1 and S4 are given, From\\nthe options P, Q and R choose appropriate sentences for S2 and S3 respectively.\\n\\nS1. It is said that wild children grow up to be the best parents\\n\\nS2. ________________\\n\\nS3.__________________\\n\\nS4. Hence, forgiving their children\u2019s mistakes become easier for them and they can find the\\nbest\\nP. Having said that, can it be inferred those adults who were too naughty in their childhood\\ncan easily put themselves in their child\u2019s shoes.\\nQ. It might become easier for them to tolerate the Shenanigans of their children and relive\\ntheir childhood\\nR. They can enjoy and play pranks with their children thereby becoming amusing parents\\n\\nA. RP\\nB. QR\\nC. PQ\\nD. PR\",\"answer\":\"PQ\",\"explanation\":\"-\"},{\"id\":\"verbal-1-33\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":33,\"page\":16,\"text\":\"33. One part of the sentence below may contain errors , Identify the part. If there is no error ,\\nchoose \u2018no error\u2019\\nWhen Shailja will come, we will have to talk about the issue together.\\n\\nA. we will have to talk\\nB. No error\\nC. When Shailja will come,\\nD. about the issue together\",\"answer\":\"When Shailja will come,\",\"explanation\":\"It should be When Shailaja comes, we will have to talk about the issue\\ntogether.\"},{\"id\":\"verbal-1-34\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":34,\"page\":16,\"text\":\"34.  Select the appropriate  option to fill in the blank.\\n\\nThe_______ complexion of the beautiful actress was admired by everyone at the party.\\n\\nA. Infernal\\nB. Impeccable\\nC. Impetuous\\nD. Indelible\",\"answer\":\"Impeccable\",\"explanation\":\"-\"},{\"id\":\"verbal-1-35\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":35,\"page\":17,\"text\":\"35.  One part of the sentence may contain errors. Find the part\\nHer son does not have the faintest idea what will he do after leaving school\\n\\nA. After leaving school\\nB. The faintest idea what\\nC. Will he do\\nD. Her son does not have\",\"answer\":\"Will he do\",\"explanation\":\"What he will do is the correct sentence.\"},{\"id\":\"verbal-1-36\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":36,\"page\":17,\"text\":\"36.  For the four sentence (S1 to S4) paragraph below, sentences S1 and S4 are given, From the\\noptions P, Q and R choose appropriate sentences for S2 and S3 respectively.\\n\\nS1: Nearly half the population of India still relies on agriculture and allied activities for\\nearning their livelihood\\nS2:\\nS3:\\nS4: When procured, processed, and marketed by the FMCG players. The same yield earns\\nthem huge money\\n\\nP: But the contribution of the primary sector to India\u2019s GDP is still dismal\\nQ: Indian economy is still largely dependent on agriculture\\nR: One of the recurring problems that Indian farmers face is the lack of marketing and\\npromotional skills for their produce.\\n\\nA. RP\\nB. PQ\\nC. PR\\nD. QR\",\"answer\":\"PR\",\"explanation\":\"-\"},{\"id\":\"verbal-1-37\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":37,\"page\":18,\"text\":\"37.  Complete the following sentence by, filling in the blanks (1 and 2) with the right word from\\nthe list given below.\\nCompared with conventional agriculture, organic farming uses fewer pesticides, reduces soil\\nerosion, decreases nitrate leaching into groundwater and surface water and, ______\\nanimal wastes into the farm. These benefits are _______ by higher food costs for consumers\\nand generally lower yields.\\n\\n1) A- recycling B- recycle C- recycles D-recycled\\n\\n2) A- increased B- balanced C- counter-balanced D- encountered\\n\\nA. 1-D, 2-A\\nB. 1-D, 2-B\\nC. 1-B, 2-D\\nD. 1-C, 2-C\",\"answer\":\"1-C, 2-C\",\"explanation\":\"The words uses, reduces, decreases say that the tense is simple present. So the only word\\nwhich is in simple present is 'Recycles'.\\nwith 'C' in blank 1, we have only one option 4.\"},{\"id\":\"verbal-1-38\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":38,\"page\":18,\"text\":\"38.  One part of the sentence below may contain an error. Identify the part.\\nEither Rahul or Rohit accompany their grandmother and grandfather whenever they go to the\\nhospital.\\n\\nA. Either Rahul or Rohit accompany\\nB. No error\\nC. their grandmother and grandfather\\nD. whenever they go to the hospital.\",\"answer\":\"Either Rahul or Rohit accompany\",\"explanation\":\"Either of Rahul or Rohit means anyone. Anyone, the subject is singular, so the\\nverb should be also singular. So, it should be accompanies.\"},{\"id\":\"verbal-1-39\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":39,\"page\":19,\"text\":\"39.  Select the most appropriate option to fill in the blank.\\nChoosing an electric wheel over a fuel driven one will  be a _________decision in the long\\nrun.\\n\\nA. unique\\nB. fancy\\nC. tough\\nD. Judicious\",\"answer\":\"Judicious\",\"explanation\":\"-\"},{\"id\":\"verbal-1-40\",\"sourceKey\":\"verbal\",\"source\":\"TCS Verbal Ability\",\"file\":\"TCS_Verbal Ability_Trainer Handout .pdf\",\"category\":\"Verbal Ability\",\"set\":1,\"number\":40,\"page\":19,\"text\":\"40.  One part of the sentence below may contain an error. Identify the part. If there is no error,\\nchoose \u2018No Error\u2019\\nThe process of building and developing some areas of land to restore their natural state is\\nknown as rewilding\\n\\nA. their natural state is known as rewilding\\nB. The process of building and developing\\nC. No error\\nD. some areas of land to restore\",\"answer\":\"No error\",\"explanation\":\"-\"},{\"id\":\"communication-1-1\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":1,\"page\":1,\"text\":\"1. Fill in the appropriate word for blank (a)\\na) By\\n\\nb) To\\n\\nc) With\\nd) into\",\"answer\":\"\",\"explanation\":\"The expression \\\"keep to yourself\\\" means \\\"avoid the company of others\\\"\"},{\"id\":\"communication-1-2\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":2,\"page\":1,\"text\":\"2. Fill in the appropriate word for blank (b)\\na) Over\\n\\nb) On\\n\\nc) At\\n\\nd) upon\",\"answer\":\"\",\"explanation\":\"The expression \\\"ponder over\\\" means to \\\"think OR reflect over\\\"\"},{\"id\":\"communication-1-3\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":3,\"page\":1,\"text\":\"3. Fill in the appropriate word for blank (c)\\na) Shy\\n\\nb) Serious\\n\\nc) Gloom\\n\\nd) selfish\",\"answer\":\"\",\"explanation\":\"The passage talks of people liking \\\"gregarious\\\" (outgoing) souls. Thus, we seek an\\nopposite of \\\"gregarious\\\" and thus \\\"shy\\\" is the best fit.\"},{\"id\":\"communication-1-4\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":4,\"page\":1,\"text\":\"4. Fill in the appropriate word for blank (d)\\na) Likewise\\nb) Similarly\\n\\nc) Alike\\n\\nd) simply\",\"answer\":\"\",\"explanation\":\"\\\"To share joys and sorrows alike\\\" means \\\"to share joyous moments and sorrowful\\nmoments with the same vigour and sincerity\\\", \\\"without restraining one for the other\\\". Thus, alike is\\nthe best fit.\\n\\nPASSAGE 2\\nOne of the most ___(a)___ women of her time, Ingrid Bergman was never anything but her supremely\\nsimple self. At the peak of her ___(b)___, Ingrid insisted on taking screen tests and refused leads in favour\\nof lesser but more ___(c)___ roles. When the director told his prospective star that they would have to\\nchange her name, cap her ___(d)___ and pluck her eyebrows, Ingrid threatened to return to Sweden.\"},{\"id\":\"communication-1-5\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":5,\"page\":1,\"text\":\"5. Fill in the appropriate word for blank (a)\\na) non-descript\\nb) average\\n\\nc) self-effacing\\nd) glamorous\",\"answer\":\"\",\"explanation\":\"The word \\\"non-descript\\\" means having no interesting features or characteristics. This\\ncoheres with the continuation of the paragraph \\\"... simple self.\\\" and so, is the correct answer.\"},{\"id\":\"communication-1-6\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":6,\"page\":1,\"text\":\"6. Fill in the appropriate word for blank (b)\\na) Freedom\\nb) Kingdom\\n\\nc) Famous\\n\\nd) stardom\\n\\nTCS\u2013 ENGLISH COMMUNICATION - TRAINER HANDOUT SET 2\",\"answer\":\"\",\"explanation\":\"The term \\\"stardom\\\" refers to the state of being a star. It is clear that this is the best fit\\nfor the context.\"},{\"id\":\"communication-1-7\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":7,\"page\":2,\"text\":\"7. Fill in the appropriate word for blank (c)\\na)Monotonous\\nb) Humdrum\\nc) Boring\\n\\nd) challenging\",\"answer\":\"\",\"explanation\":\"lesser but more challenging is the right answer\"},{\"id\":\"communication-1-8\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":8,\"page\":2,\"text\":\"8.  Fill in the appropriate word for blank (d)\\na)Nose\\n\\nb) Cheeks\\n\\nc) Ears\\n\\nd) teeth\",\"answer\":\"\",\"explanation\":\"Capping is a procedure done to improve appearance of teeth and / or improve damaged\\nteeth. The other options don\u2019t make sense.\\n\\nPASSAGE 3\\nNew industries supported by foreign interests ___(a)___ offer better salaries to their employees at all levels\\nof responsibility than ___(b)___ locally-owned industries. They need talented people and are willing to pay\\nhigh wages to retain them. Local industries often ___(c)___ against the high salaries offered by foreign\\nsupported industries, arguing that this will unreasonably raise all wages to an excessive level. Workers in\\nlocal industries, seeing the sharp ___(d)___ in job-pay will agitate for an improvement in their salaries. This\\neventually will drain the resources and lower their profitability.\"},{\"id\":\"communication-1-9\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":9,\"page\":2,\"text\":\"9. Fill in the appropriate word for blank (a)\\na) Hardly\\n\\nb) Reluctantly\\nc) Seldom\\n\\nd) Usually\",\"answer\":\"\",\"explanation\":\"The second sentence in the paragraph reads \\\"..they need talented people and are willing\\nto pay huge wages to retain them.\\\" This is the clue.\"},{\"id\":\"communication-1-10\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":10,\"page\":2,\"text\":\"10.Fill in the appropriate word for blank (a)\\na) did\\n\\nb) could\\n\\nc) do\\n\\nd) their\",\"answer\":\"\",\"explanation\":\"The \\\"their\\\" refers to the new industries\u2019.\"},{\"id\":\"communication-1-11\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":11,\"page\":2,\"text\":\"11.Fill in the appropriate word for blank (a)\\na) uphold\\n\\nb) imitate\\n\\nc) protest\\n\\nd) pay\",\"answer\":\"\",\"explanation\":\"The second part of the sentence says that local industries argue that this will\\nunreasonably raise wages to an excessive level.. Further only the word \u201cprotest\u201d goes with \u201cagainst\u201d.\\nThus, the answer should be \u201cprotest\u201d.\"},{\"id\":\"communication-1-12\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":12,\"page\":2,\"text\":\"12.Fill in the appropriate word for blank (a)\\na) difference\\nb) cut\\n\\nc) hike\\n\\nd) decrease\",\"answer\":\"\",\"explanation\":\"Sharp difference. So, this is the best fit for the blank\\nPASSAGE 4\\nWhen she appeared on the screen without ___Q1___, cosmetic sales declined. When she played a nun,\\nconvent enrolments ___Q2___. Letters were delivered to her addressed simply \u201cIngrid Bergman\u201d.\\nIndustrialist Howard Hughes once ___Q3___ every available air tickets from New York to Los Angeles to\\nbe sure she would accept a seat in his private plane. An ___Q4___ walked a sheep all the way from Sweden\\nto Rome as a gift for her.\"},{\"id\":\"communication-1-13\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":13,\"page\":2,\"text\":\"13.Fill in the appropriate word for blank (a)\\na) shoes\\n\\nb) hat\\n\\nc) gloves\\n\\nd) make-up\",\"answer\":\"\",\"explanation\":\"'cosmetics' refers to 'make-up'.\"},{\"id\":\"communication-1-14\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":14,\"page\":2,\"text\":\"14. Fill in the appropriate word for blank (b)\\na) increased\\nb) decreased\\nc) lessened\\n\\nd) indifferent\",\"answer\":\"\",\"explanation\":\"'increased' is the logically correct answer.\"},{\"id\":\"communication-1-15\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":15,\"page\":3,\"text\":\"15.Fill in the appropriate word for blank (c)\\na) brought\\n\\nb) bought\\n\\nc) sold\\n\\nd) boarded\",\"answer\":\"\",\"explanation\":\"'bought' is the correct word to be used here.\"},{\"id\":\"communication-1-16\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":16,\"page\":3,\"text\":\"16.Fill in the appropriate word for blank (d)\\na) administrator\\nb) Accomplice\\nc) acrobat\\n\\nd) admirer\",\"answer\":\"\",\"explanation\":\"'admirer' is the right word in this context.\\nORDERING OF SENTENCES\\nDirections: In each of the following questions, choose the most logical order of sentences among the\\ngiven choices to construct a coherent paragraph.\"},{\"id\":\"communication-1-17\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":17,\"page\":3,\"text\":\"17.A. If you are used to having your stimulation come in from outside, your mind never develops its own\\nhabits of thinking and reflecting.\\nB. Marx thought that religion was the opiate, because it soothed people\u2019s pain and suffering and prevented\\nthem from rising in rebellion.\\nC. If Karl Marx were alive today, he would say that television is the opiate of the people.\\nD. Television and similar entertainments are even more of an opiate because of their addictive tendencies.\\na) BACD\\n\\nb) CBDA\\n\\nc) ADBC\\n\\nd) BDCA\",\"answer\":\"\",\"explanation\":\"Sentence B uses \u201cMarx\u201d (short form) when referring to Karl Marx. Sentence C uses the\\nfull name. So, C should come before B. Now in the given options BACD, ADBC and BDCA, we can\\nclearly see that B is placed before C which is wrong. Hence, we are left with only option CBDA which\\nis the correct answer. Therefore, the correct order is CBDA.\"},{\"id\":\"communication-1-18\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":18,\"page\":3,\"text\":\"18.A. The situations in which violence occurs and the nature of that violence tends to be clearly defined at least\\nin theory, as in the proverbial Irishman\u2019s question: \u201cIs this a private fight or can anyone join in?\u201d\\nB. So the actual risk to outsiders, though no doubt higher than our societies, is calculable.\\nC. Probably the only uncontrolled applications of force are those of social superiors to social inferiors and\\neven here there are probably some rules.\\nD. However binding the obligation to kill, members of feuding families engaged in mutual massacre will be\\ngenuinely appalled if by some mischance a bystander or outsider is killed.\\na) DBAC\\n\\nb) ACDB\\n\\nc) DBAC\\n\\nd) DABC\",\"answer\":\"\",\"explanation\":\"The word \\\"calculable and the phrase \\\"clearly defined in theory\\\" show that the first and\\nsecond sentences should occur in sequence. The only option in which this sequence is present is\\nDABC.\"},{\"id\":\"communication-1-19\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":19,\"page\":3,\"text\":\"19.A. The Supreme Court in various judgements in the last 25 years has further emphasised this.\\nB. The Right to Information is derived from Article 19 of the Constitution.\\nC. The RTI Act was passed in May 2005 and came into force in October 2005.\\nD. It is intended to give relevant information about the government and its institutions.\\nE. This Act enables citizens to obtain information without going to court each time.\\na) BDACE\\nb) ABDCE\\n\\nc) BDECA\\n\\nd) CEBAD\",\"answer\":\"\",\"explanation\":\"The ABDCE option cannot be correct because there has to be a sentence (before\\nsentence A) that explains what \\\"this\\\" is. The abbreviation RTI in sentence C indicates that its\\nexpansion must come in a sentence before it. Thus, the CEBAD option is also ruled\\nout. Between BDACE and BDECA options,\\nwe\\ngo\\nfor\\nthe BDACE\\nbecause\\nthe\\nphrase\\n\\\"this act\\\" gains significance only if ordered as in this option.\"},{\"id\":\"communication-1-20\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":20,\"page\":4,\"text\":\"20.A. Riots had to be contained, food shortages to be overcome, princely states (as many as five hundred) to be\\nintegrated, refugees (almost ten million) to be resettled.\\nB. It is safe to say that no modern politician had anywhere near as difficult a job as Jawaharlal Nehru\u2019s.\\nC. At Independence, the country he was asked to lead was faced with horrific problems.\\nD. This, so to say, was the task of fire-fighting; to be followed by the equally daunting task of\\nnation-building.\\na)\\nABDC\\n\\nb) BCAD\\n\\nc) BACD\\n\\nd) DCBA\",\"answer\":\"\",\"explanation\":\"The pronoun \\\"he\\\" in sentence C should induce the solver to look for a noun to whom it\\nmight refer to and have some preceding sentence. Among those given, the only sentence which this\\ncould be sentence B. BCAD is the only option which contains B and C in that sequence AS WELL AS\\nread coherently. Thus, this is the correct order.\"},{\"id\":\"communication-1-21\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":21,\"page\":4,\"text\":\"21.A. Mr. Sherlock House, who was usually very late in the mornings, save upon those not infrequent\\noccasions when he was up all night, was seated at the breakfast table.\\nB. \\\"To James Morrisson, M.R.C.S., from his friends of the C.C.H.,\\\" was engraved upon it, with the date\\n\\\"1884.\\\"\\nC. It was a fine, thick piece of wood, bulbous-headed, of the sort which is known as a \\\"Penang lawyer.\\\"\\nD. It was just such a stick as the old-fashioned family practitioner used to carry--dignified, solid, and\\nreassuring.\\nE. I stood upon the hearth-rug and picked up the stick which our visitor had left behind him the night before.\\nF. Just under the head was a broad silver band nearly an inch across.\\na) AECFBD\\nb) ABCEDF\\nc) FDBAEC\\nd) FBAECD\",\"answer\":\"\",\"explanation\":\"The opening statement cannot be F, since the paragraph cannot start with \\\"Just under\\nthe head...\\\" Under whose head? Thus two options are eliminated.\\nABCDEF is definitely not the answer. There is no connection between A and B for instance.\\nAECFBD is the answer then, through elimination method. For your reference, let's confirm it.\\nC - \\\"It was a fine, thick piece of wood.....\\\" What is this 'it'?\\n'The stick' introduced in E. Thus, there's an EC link.\"},{\"id\":\"communication-1-22\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":22,\"page\":4,\"text\":\"22.A. Their entire philosophy is based on the recognition that all men are made by nature to be equals,\\ntherefore no one has a natural right to govern others, and therefore the only justified authority is the\\nauthority that is generated out of agreements or covenants.\\nB. The social contract theorists recognised the need to have an agency for the protection of man and his\\nproperty.\\nC. Therefore, this period built on the concept of an individual, inalienable rights as maintainable in a\\ncollective whole.\\nD. What was built on did not lead to the advocation of the creation of a sovereign state though.\\na)\\nDBCA\\n\\nb) DCBA\\n\\nc) BACD\\n\\nd) BADC\",\"answer\":\"\",\"explanation\":\"D cannot be the starting sentence since 'what was built on' feels incomplete and the\\nparagraph cannot start that way. Thus two options starting with D are eliminated.\\nBADC vs. BACD - D - What was built on - This is introduced in C. Thus C should come before D.\\nTherefore the answer is BACD.\"},{\"id\":\"communication-1-23\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":23,\"page\":4,\"text\":\"23.A. Not unlike most other Asian countries, Indian children are socialized into a system where they are\\nexpected to obey and respect authority figures without ever questioning their actions.\\nB. An all pervasive sensibility that rebellion is a sign of bad upbringing breeds a culture of abuse by\\nencouraging sexual predators.\\nC. Two adults in India are often seen to exercise a near feudal hold over children demanding their\\nunquestioned\\n\\nand complete obedience.\\nD. The reasons for the rampant instances of sexual abuse in India are manifold and rooted deep within the\\ncountry\u2019s social fabric.\\na) DABC\\n\\nb) ABDC\\n\\nc) DBAC\\n\\nd) CBAD\",\"answer\":\"\",\"explanation\":\"Sentence \u2018D\u2019 says there are various reasons for child abuse in India and sentence \u2018A\u2019\\ntalks about the primary reason for this child abuse. Hence , there is a DA link. The only option with\\nthis link is \u2018DABC\u2019.\"},{\"id\":\"communication-1-24\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":24,\"page\":5,\"text\":\"24.A. This is problematic both theoretically and practically, because it has grave consequences for the way\\nsociety views and treats the fundamental issues of women\u2019s lives.\\nB. Crimes such as these against any group other than women would be recognized as a civil and political\\nemergency as well as a gross violation of the victims\u2019 humanity.\\nC. Significant numbers of the world\u2019s population are routinely subject to torture, starvation, terrorism,\\nhumiliation, mutilation, and even murder simply because they are female.\\nD. Yet, despite a clear record of deaths and demonstrable abuse, women\u2019s rights are not commonly\\nclassified as human rights.\\na) BACD\\n\\nb) DACB\\n\\nc) ADBC\\n\\nd) CBDA\",\"answer\":\"\",\"explanation\":\"Sentence 'B' talks about the unfairness towards females and sentence 'D' supports this\\nclaim. Hence, the answer is CBDA.\\nDirections: In the questions below, each passage consists of six sentences. The first and sixth sentences\\nare given in the beginning. The middle four sentences in each have been jumbled up. These are\\nlabelled as P, Q, R and S. Find out the proper order for the four sentences.\"},{\"id\":\"communication-1-25\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":25,\"page\":5,\"text\":\"25.A. Wundt was interested in the study of conscious experience and wanted to analyse the constituents or the\\nbuilding blocks of the mind.\\nB. It grew out of ancient philosophy concerned with questions of psychological significance.\\nC. Psychology as a modern discipline, which is influenced to a large extent by Western developments, has a\\nshort history.\\nD. But the formal beginning of modern psychology is traced back to 1879 when the first experimental\\nlaboratory was established in Leipzig, Germany by Wilhelm Wundt.\\na)\\nCABD\\n\\nb) CBDA\\n\\nc) DABC\\n\\nd) DACB\",\"answer\":\"\",\"explanation\":\"C is clearly the beginning sentence. There is CB and DA links. The correct sequence is\\nCBDA\"},{\"id\":\"communication-1-26\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":26,\"page\":5,\"text\":\"26.A.  Albus never attempted to deny that his father (who was to die in Azkaban) had committed this crime; on\\nthe contrary, when I plucked up courage to ask him, he assured me that he knew his father to be guilty.\\nB. Some, indeed, were disposed to praise his father\u2019s action and assumed that Albus too was a\\nMuggle-hater.\\nC. They could not have been more mistaken: As anybody who knew Albus would attest, he never revealed\\nthe remotest anti-Muggle tendency.\\nD. Beyond that, Dumbledore refused to speak of the sad business, though many attempted to make him do\\nso.\\na)\\nBCAD\\n\\nb) ADBC\\n\\nc) DBCA\\n\\nd) ACBD\",\"answer\":\"\",\"explanation\":\"B or D can't be the beginning sentence. A is clearly the beginning. We can see AD link in\\nthe paragraph so, ADBC is the answer.\\n\\nANALOGY\\nDirections: In the following questions, select the lettered pair that best expresses a relationship similar\\nto that expressed by the original pair.\"},{\"id\":\"communication-1-27\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":27,\"page\":6,\"text\":\"27.COLT : HORSE ::\\na) Dog : pet\\nb) Snake : slither\\nc) Cow : milk\\nd) Kitten : cat\",\"answer\":\"\",\"explanation\":\"Colt is the young one of the horse\\nSimilarly, Kitten is the child of Cat.\"},{\"id\":\"communication-1-28\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":28,\"page\":6,\"text\":\"28.TOOTH : ORTHODONTIST ::\\na)Surgeon : patient\\n\\nb) Tree : arborist\\na)\\nGardener : florist\\n\\nd) Petal : botanist\",\"answer\":\"\",\"explanation\":\"An Orthodontist is a dentist who specialises in correcting irregularities of the Tooth.\\nSimilarly, an Arborist is a specialist in treating damaged trees. (tree)\"},{\"id\":\"communication-1-29\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":29,\"page\":6,\"text\":\"29.ESSAY : SHORT STORY ::\\na)symphony : concerto\\n\\nb) biography : novel\\na)\\nacrylic : watercolour\\n\\nd) comedy : burlesque\",\"answer\":\"\",\"explanation\":\"Two literary works that widely vary in length are paired as the stem. Upon browsing\\nthrough the answer choices, we see that the only such a pair is \\\"biography : novel\\\". Thus, this is the\\nanswer.\"},{\"id\":\"communication-1-30\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":30,\"page\":6,\"text\":\"30.UNPRECEDENTED : FORERUNNERS ::\\na)\\nnauseating : neuralgia\\n\\nb) holistic : incomplete\\nc)bloodthirsty : carnivorous\\n\\nd) polluted : purity\",\"answer\":\"\",\"explanation\":\"The words in the stem can be connected with the bridge \\\"Something that is\\nunprecedented lacks forerunners.\\\" When we look at the answer options, we find that we could\\nconnect the \\\"polluted : purity\\\" option with the same bridge as \\\"Something that is polluted lacks\\npurity\\\". Thus, polluted : purity is the best fit.\"},{\"id\":\"communication-1-31\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":31,\"page\":6,\"text\":\"31.THWART : ABET ::\\na)\\nstrip : befit\\n\\nb) lacerate : incise\\nb)\\nsavor : enjoy\\n\\nd) murmur : caterwaul\",\"answer\":\"\",\"explanation\":\"To \u201cthwart\u201d is to \u201cprevent\u201d it and to \u201cabet\u201d something is to encourage or assist\\nsomething. Thus, the stem pair actually consists of kind of opposites. The only pair in which you have\\nopposites is the last one. While murmur means to say something in a soft voice, \u201ccaterwaul\u201d means to\\n\u201cutter long wailing cries\u201d.\"},{\"id\":\"communication-1-32\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":32,\"page\":6,\"text\":\"32.COLD : FRIGID ::\\na)\\nhot : warm b) proper : prudish\\nc) dark : light\\nd) colourful : pale\",\"answer\":\"\",\"explanation\":\"Extremely cold is 'frigid'. Extremely proper is 'prudish'.\"},{\"id\":\"communication-1-33\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":33,\"page\":6,\"text\":\"33.BREAKFAST : DINNER ::\\na) lark : nightingale\\n\\nb) stone : wood\\nc)tent : tepee\\n\\nd) radar : sonar\",\"answer\":\"\",\"explanation\":\"Breakfast is 'morning food' and Dinner is 'night food'. Lark is a bird active in the\\nmorning and Nightingale is a bird active at night.\"},{\"id\":\"communication-1-34\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":34,\"page\":6,\"text\":\"34.WAX : CANDLE ::\\na)\\nstring : kite b) ink : pen\\n\\nc) liquid : cup\\nd) clay : pot\",\"answer\":\"\",\"explanation\":\"Wax is used to make candle and clay is used to make pot.\"},{\"id\":\"communication-1-35\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":35,\"page\":6,\"text\":\"35.PLAN : SCHEME ::\\na) antiquity : age\\n\\nb) annoyance : evasion\\nc) statesman : politician\\n\\nd) assignment : homework\",\"answer\":\"\",\"explanation\":\"The words in the stem are synonymous. If we seek a synonymous pair in the list of\\nanswer options, we stumble upon \\\"statesman : politician\\\"\"},{\"id\":\"communication-1-36\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":36,\"page\":7,\"text\":\"36.CUPOLA : ROOF ::\\na) branch : tree\\nb) building : story\\nc) airplane : propeller\\nd) statue : pedestal\",\"answer\":\"\",\"explanation\":\"A cupola is a light structure on a roof just as a statue is a structure on a pedestal.\\nSENTENCE CORRECTION\\nDirections: Identify the part of the sentence which has errors.\"},{\"id\":\"communication-1-37\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":37,\"page\":7,\"text\":\"37.It ought to be (A)/ she with whom (B)/ you share your secrets, (C)/ not me. (D)\\na) A\\n\\nb) B\\n\\nc) C\\n\\nd) D\",\"answer\":\"\",\"explanation\":\"After the different forms of the verb to be, we use subject form of pronouns.\\nHence, we should use her instead of she.\"},{\"id\":\"communication-1-38\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":38,\"page\":7,\"text\":\"38.Having answered the question paper well in time (A)/ the supervisor allowed me (B)/ to leave the hall\\nquietly (C)/ without disturbing the others. (D)\\na) A\\n\\nb) B\\n\\nc) C\\n\\nd) D\",\"answer\":\"\",\"explanation\":\"Part A is supposed to talk about the speaker, but seems to say that the supervisor had\\ntaken the exam. This doesn\u2019t make any sense and hence is the erroneous part.\"},{\"id\":\"communication-1-39\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":39,\"page\":7,\"text\":\"39.China\u2019s economy continued to (A)/ flourish this year: (B)/ industrial production was growing (C)/ inflation\\neased and the trade surplus swelled. (D)\\na) A\\n\\nb) B\\n\\nc) C\\n\\nd) D\",\"answer\":\"\",\"explanation\":\"Part C has an error because it doesn\u2019t follows the rules of Parallelism.\\nC part should be written as \u2019industrial production grew\u2019 to make the structure of the sentence\\nparallel.\"},{\"id\":\"communication-1-40\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":40,\"page\":7,\"text\":\"40.I am not able to contact him (A)/ because the paper on which I had noted down his address (B)/ has\\nmisplaced (C)/ and cannot be traced easily. (D)\\na) A\\n\\nb) B\\n\\nc) C\\n\\nd) D\",\"answer\":\"\",\"explanation\":\"The third part is erroneous because the sentence seems to say that the paper has itself\\nmisplaced (something) which doesn\u2019t make any sense. It could have read \\\"has got misplaced\\\".\"},{\"id\":\"communication-1-41\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":41,\"page\":7,\"text\":\"41.Ramesh has a tennis racquet (A)/ which looks far more attractive (B)/ than his opponent (C)/ and is also\\nstronger. (D)\\na) A\\n\\nb) B\\n\\nc) C\\n\\nd) D\",\"answer\":\"\",\"explanation\":\"Only two grammatically similar entities can be compared. The sentence appears to\\ncompare Ramesh\u2019s tennis racquet and Ramesh\u2019s opponent. The sentence could have read Ramesh\u2019s\\ntennis racquet is stronger and more attractive than his opponent\u2019s.\"},{\"id\":\"communication-1-42\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":42,\"page\":7,\"text\":\"42.I have secured admission in IIT (A)/ in B.Tech, which is a (B)/ four-years course (C)/ consisting of eight\\nsemesters. (D)\\na) A\\n\\nb) B\\n\\nc) C\\n\\nd) D\",\"answer\":\"\",\"explanation\":\"The third part of the sentence is wrong because it should read \\\"four-year course\\\". The\\nterm \\\"four-year\\\" is used as an adjective for the noun \\\"course\\\" and so, it shouldn\u2019t be pluralised.\"},{\"id\":\"communication-1-43\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":43,\"page\":7,\"text\":\"43.Amphibians are creatures which (A)/ live equally effortlessly (B)/ in water and land are found (C)/ in all the\\ncountries of the world. (D)\\na) A\\n\\nb) B\\n\\nc) C\\n\\nd) D\",\"answer\":\"\",\"explanation\":\"The third part is erroneous. The sentence gets over with \\\"..land\\\" The remaining part in\\nthe question would have made sense if another sentence had started with \\\"They\\\"\"},{\"id\":\"communication-1-44\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":44,\"page\":8,\"text\":\"44.Many middle class individuals (A) /find that they cannot get good medical attention (B) /despite they need it\\nbadly (C) /because of the high cost of treatment. (D)\\na) A\\n\\nb) B\\n\\nc) C\\n\\nd) D\",\"answer\":\"\",\"explanation\":\"The third part is wrong. The word \\\"despite\\\" should be followed by \\\"being...\\\" and not\\nan independent clause. In this sentence, the \\\"despite\\\" could be replaced by \\\"even though\\\" to make it\\ncorrect.\"},{\"id\":\"communication-1-45\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":45,\"page\":8,\"text\":\"45.Anbuselvan leads a content life (A)/ with his relatives in his village (B)/ and rarely visits the city, though\\n(C)/ he has many friends here. (D)\\na) A\\n\\nb) B\\n\\nc) C\\n\\nd) D\",\"answer\":\"\",\"explanation\":\"To mean \\\"satisfied\\\", the word to be used is \\\"contented\\\", whereas the stem reads\\n\\\"content\\\". Thus, the first part is erroneous. A\"},{\"id\":\"communication-1-46\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":46,\"page\":8,\"text\":\"46.He is so versatile(A)/that he is capable of beating(B)/all his other classmates(C)/both in studies, public\\nspeaking and sports.(D)\\na) A\\n\\nb) B\\n\\nc) C\\n\\nd) D\",\"answer\":\"\",\"explanation\":\"The word \\\"both\\\" is used only when talking about two items. But, in this sentence, there\\nare three items. So, it is wrong to use the word here.\"},{\"id\":\"communication-1-47\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":47,\"page\":8,\"text\":\"47.John is one of the students(A)/in the class who has not been absent(B)/for a single day(C)/during the entire\\nyear/(D)\\na) A\\n\\nb) B\\n\\nc) C\\n\\nd) D\",\"answer\":\"\",\"explanation\":\"The sentence seems to suggest that many students have not been absent for a single day\\nand John is one of them. As per the Subject-verb agreement rule, this sentence should use the plural\\nform of the verb. That is, it should read \\\"...who HAVE been absent...\\\"\\n\\nDirections: Choose the option that could best replace the underlined part:\"},{\"id\":\"communication-1-48\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":48,\"page\":8,\"text\":\"48.The impostor eluded detection for so long because she conducted herself as though she were a licensed\\npractitioner.\\na) as though she were a licensed practitioner.\\nb) as though she was a licensed practitioner.\\nc) like she was a licensed practitioner.\\n\\nd) like as if she was a licensed practitioner.\",\"answer\":\"\",\"explanation\":\"The given sentence is correct as it is.\\nWe use as if and as though to make comparisons. They have a similar meaning. We use as if and as\\nthough to talk about an imaginary situation or a situation that may not be true but that is likely or\\npossible.\"},{\"id\":\"communication-1-49\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":49,\"page\":8,\"text\":\"49.More and more holidaymakers are choosing to fly to remote islands in search of the perfect beach; seeking\\nsand, sun and palm trees, rather than centres of entertainment.\\na); seeking sand, sun and palm trees, rather than centers of entertainment.\\nb); seeking sand, sun, palm trees and not entertainment.\\nc), with sand, sun, palm trees and no entertainment.\\nd); they seek sand, sun and palm trees, rather than centers of entertainment.\",\"answer\":\"\",\"explanation\":\"A semi colon comes between two independent clauses that are contextually connected.\\nbut options \\\"seeking sand, sun and palm trees, rather than centers of entertainment.\\\" and \\\"seeking\\nsand, sun, palm trees and not entertainment.\\\" don\u2019t have an independent clause after the semi-colon.\\nThe option \\\", with sand, sun, palm trees and no entertainment.\\\" is incorrect because it doesn\u2019t use a\\n\\nsemicolon. The option \\\"they seek sand, sun and palm trees, rather than centers of\\nentertainment.\\\" uses the semi colon to connect two independent clauses. Hence, it is correct.\"},{\"id\":\"communication-1-50\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":50,\"page\":9,\"text\":\"50.We could not think of a better solution to the problem than his suggestion.\\na) his suggestion.\\n\\nb) the one he told us.\\nc) how he told us must be done.\\n\\nd) how he told us what must be done.\",\"answer\":\"\",\"explanation\":\"'The solution to a problem' can be compared only with 'What' was suggested as a\\nsolution by a person; not with 'his suggestion' alone.\\nSo, option b) is the correct replacement to correct the comparison error.\"},{\"id\":\"communication-1-51\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":51,\"page\":9,\"text\":\"51.It is usual for scientists and social scientists to abandon their theories only if another more attractive theory\\ncomes along and not when they have been proved incorrect.\\na)their theories only if another more attractive theory comes along and not when they have been proved\\nincorrect.\\nb)a theory not because it has been proved incorrect, but because another more attractive theory comes\\nalong.\\nc)their theories not when they have been proved incorrect, but because other more attractive theories come\\nalong.\\nd)a theory only when other more attractive ones come along, rather than when they are proved wrong.\",\"answer\":\"\",\"explanation\":\"It is only in the option a theory not because it has been proved incorrect, but because\\nanother more attractive theory comes along that we have a comparison that is devoid of any parallelism\\nerrors and so, that is the correct answer.\"},{\"id\":\"communication-1-52\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":52,\"page\":9,\"text\":\"52.Dunbar argues that gossip is important in human societies in the maintenance of social cohesion, just as\\nsocial grooming does for other primates.\\na)gossip is important in the maintenance of social cohesion in human society, just as social grooming does\\nfor other primates.\\nb)in human societies gossip is important in social cohesion like social grooming for other primate societies.\\nc)similar to social grooming in primates, human gossip is important in maintaining social cohesion.\\nd)gossip is important in human societies in the maintenance of social cohesion, just as social grooming is in\\nother primate groups.\",\"answer\":\"\",\"explanation\":\"In answer choice \\\"gossip is important in the maintenance of social cohesion in human\\nsociety, just as social grooming does for other primates\\\"., \u2018does\u2019 is incorrect and needs to be changed to\\n\u2018is\u2019. Among the remaining options we need to look for the one that best compares the function of\\ngossip to the function of social grooming. Once we look at it this way, the answer is clear \u2013\\nonly \\\"gossip is important in human societies in the maintenance of social cohesion, just as social\\ngrooming is in other primate groups.\\\" give a correct comparison.\"},{\"id\":\"communication-1-53\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":53,\"page\":9,\"text\":\"53.Inertia-gravity waves cause characteristic stripy patterns in the clouds in the lower atmosphere but they are\\ndisregarded by conventional weather forecasts because they are thought to be too small to interact with\\nlarger systems such as warm and cold fronts.\\na)they are disregarded by conventional weather forecasts because they are thought to be too small.\\nb)they are disregarded by conventional weather forecasts because these waves are thought to be too small.\\nc)conventional weather forecasts disregard them because they think they are too small.\\nd)conventional weather forecasts disregard these waves because they are thought to be too small.\",\"answer\":\"\",\"explanation\":\"In the other three options, it is not clear about whom or what the \\\"they\\\" is referring to.\\nBut, in the option conventional weather forecasts disregard these waves because they are thought to be\\ntoo small it is clear that \\\"they\\\" refers to the waves and so, is the best choice.\"},{\"id\":\"communication-1-54\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":54,\"page\":10,\"text\":\"54.The recent photographs of the giant squid are remarkable because they show these enormous living\\ncreatures as moving around in their natural environment, whereas previous pictures have been of only dead\\nanimals.\\na)because they show these living creatures as moving around in their\\nb)in that they show this most enormous of living creatures moving around in its\\nc)in that they show this enormous living creature moving around in its\\nd)because these enormous living creatures are shown to be moving around in their\",\"answer\":\"\",\"explanation\":\"Option \\\"because they show these living creatures as moving around in their\\\" can be\\neliminated as it tells 'as moving around' which is incorrect. Option \\\"in that they show this most\\nenormous of living creatures moving around in its\\\" also can be eliminated as it gives two superlatives\\ntogether 'most enormous'. Comparing Option \\\"in that they show this enormous living creature\\nmoving around in its\\\" and \\\"because these enormous living creatures are shown to be moving around\\nin their\\\", option \\\"in that they show this enormous living creature moving around in its\\\" is more suitable\\nbecause 'recent pictures' can only 'show'(past) and not 'shown'.\"},{\"id\":\"communication-1-55\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":55,\"page\":10,\"text\":\"55.In archaeological terms the university was a latecomer to the town, which was already centuries old by the\\ntime we first hear of the establishment of a community of scholars and teachers in the late 12th Century.\\na)which was already centuries old by the time we first hear of the establishment of\\nb)already centuries old by the time we first hear of its establishment of\\nc)which was centuries old already when we first hear of the establishment of\\nd)that was already centuries old by the time we first hear that they had established\",\"answer\":\"\",\"explanation\":\"The given sentence is correct as it is.\"},{\"id\":\"communication-1-56\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":56,\"page\":10,\"text\":\"56.A teacher at the school acknowledged that despite government-sponsored endeavours to improve classroom\\nperformance, an extraordinary high percentage of their students fail to gain admission to higher education.\\na)an extraordinary high percentage of their students fail to gain admission to higher education\\nb)an extraordinarily high percentage of its students fail to gain admission to higher education\\nc)an extraordinary high percentage of its students fails to gain admission to higher education\\nd)a high percentage of its students, extraordinarily high in fact, fails to gain admission to higher education\",\"answer\":\"\",\"explanation\":\"By the subject-verb agreement rule of English grammar, when dealing with fractions,\\nthe countability of the noun that follows the percentage decides whether the verb to be used is\\nsingular or plural. An uncountable noun goes with a singular form of the verb while a countable noun\\ntakes the plural form of the noun. Thus,  an extraordinarily high percentage of its students fail to gain\\nadmission to higher education  is correct.\\n\\nSYNONYMS\\nDirections: Select the word from the given options which is closest in meaning to the given word.\"},{\"id\":\"communication-1-57\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":57,\"page\":10,\"text\":\"57.Fervor\\na) Ardor\\n\\nb) Inactive\\n\\nc) Frigidity\\n\\nd) Saneness\",\"answer\":\"\",\"explanation\":\"The word \u2019fervor\u2019 means intense or passionate feeling.\\n\u2019Ardor\u2019 refers to enthusiasm or passion.\\n\u2019Inactive\u2019 means idle or passive.\\n\u2019Frigidity\u2019 means to lack warmth of feeling.\\n\u2019Saneness\u2019 means a sound mind.\\nHence, the word which is closest in meaning to the root word is \u2019Ardor\u2019.\"},{\"id\":\"communication-1-58\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":58,\"page\":10,\"text\":\"58.Squalor\\na) Fortune\\n\\nb) Virtue\\n\\nc) Poverty\\n\\nd) Benevolence\",\"answer\":\"\",\"explanation\":\"\u2019Squalor\u2019 means misery or poverty.\\n\u2019Fortune\u2019 means destiny or luck.\\n\u2019Virtue\u2019 means moral excellence or goodness.\\n\u2019Poverty\u2019 is a synonym of \u2019Squalor\u2019.\\n\u2019Benevolence\u2019 refers to kind or charitable acts.\"},{\"id\":\"communication-1-59\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":59,\"page\":11,\"text\":\"59.Fastidious\\na)Uncouth\\nb) Indifferent\\nc) Heedless\\n\\nd) Meticulous\",\"answer\":\"\",\"explanation\":\"Being \u2019fastidious\u2019 is being very attentive and careful about accuracy.\\n\u2019Uncouth\u2019 refers to someone who is clumsy and lacks sophistication.\\n\u2019Indifferent\u2019 means unconcerned or apathetic.\\n\u2019Heedless\u2019 refers to someone who is careless or thoughtless.\\n\u2019Meticulous\u2019 refers to someone who is very careful and precise.\\nHence, the word which is closest in meaning to the root word is \u2019meticulous\u2019.\"},{\"id\":\"communication-1-60\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":60,\"page\":11,\"text\":\"60.Premonition\\na)\\nDoubt\\n\\nb) Augury\\n\\nc) Providence\\nd) Imperceptions\",\"answer\":\"\",\"explanation\":\"A premonition is a strong feeling of something about to happen.\\nAn augury is an omen - a sign of what will happen in the future.\\nThus, this is the best fit.\"},{\"id\":\"communication-1-61\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":61,\"page\":11,\"text\":\"61.Permeate\\na)Exhaust\\nb) Void\\nc) Drain\\n\\nd) Imbue\",\"answer\":\"\",\"explanation\":\"The word \\\"permeate\\\" means to impregnate, seep.\\nThe word \\\"imbue\\\" shares the same meaning and so, is the best fit.\"},{\"id\":\"communication-1-62\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":62,\"page\":11,\"text\":\"62.Perplex\\na) Encumber\\nb) Clarify\\n\\nc) Enlighten\\n\\nd) Associate\",\"answer\":\"\",\"explanation\":\"To perplex is to confuse or baffle.\\nThe words \\\"enlighten\\\" and \\\"clarify\\\" actually are almost opposites of the stem.\\nThe word \\\"associate\\\" is obviously unrelated word and so, can be eliminated straightaway.\\nThe remaining word \\\"encumber\\\" means \\\"restrict in such a way free movement becomes difficult\\\".\\nIt can be seen that this is the best fit.\"},{\"id\":\"communication-1-63\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":63,\"page\":11,\"text\":\"63.Tumult\\na)\\nTruce\\n\\nb) Bedlam\\n\\nc) Peace\\n\\nd) Concord\",\"answer\":\"\",\"explanation\":\"Tumult is a kind of confusion and so is bedlam. Thus, option Bedlam is the best choice.\"},{\"id\":\"communication-1-64\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":64,\"page\":11,\"text\":\"64.Infuriate\\na) Exasperate\\nb) Placate\\n\\nc) Comfort\\n\\nd) Soothe\",\"answer\":\"\",\"explanation\":\"To infuriate (someone) is to make (someone) very angry.\\nThe words \\\"comfort\\\", \\\"placate\\\" and \\\"soothe\\\" are clearly opposites of the kind of word we are\\nlooking for and so, cannot be correct.\\nThe only one left out is \\\"exasperate\\\" and that is the correct answer.\"},{\"id\":\"communication-1-65\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":65,\"page\":11,\"text\":\"65.Receptacle\\na)\\nDissipation b) Dispersal\\n\\nc) Repository\\nd) Leak\",\"answer\":\"\",\"explanation\":\"A receptacle is an object that is used to store something, A repository is a place where\\nsomething is stored. Thus, Repository is the best bet.\"},{\"id\":\"communication-1-66\",\"sourceKey\":\"communication\",\"source\":\"TCS English Communication\",\"file\":\"TCS_English Communication Trainer Handout Set 2.docx.pdf\",\"category\":\"English Communication\",\"set\":1,\"number\":66,\"page\":11,\"text\":\"66.Importune\\n\\na) Spurn\\n\\nb) Abjure\\n\\nc) Retract\\n\\nd) Beseech\",\"answer\":\"\",\"explanation\":\"'Importune' means to ask for something earnestly. 'Beseech' means the same thing.\"}];\nconst PDF_IMAGES = {\"num-si-ci\":{\"data\":\"data:image/jpeg;base64,\",\"alt\":\"TCS Numerical Ability PDF, page 1: handwritten simple- and compound-interest working\"},\"num-cone-csa\":{\"data\":\"data:image/jpeg;base64,\",\"alt\":\"TCS Numerical Ability PDF, page 3: cone curved-surface-area working\"},\"num-cube-root\":{\"data\":\"data:image/jpeg;base64,\",\"alt\":\"TCS Numerical Ability PDF, page 11: cube-root calculation working\"},\"num-triangle-area\":{\"data\":\"data:image/jpeg;base64,\",\"alt\":\"TCS Numerical Ability PDF, page 23: triangle-in-circle question working\"},\"num-bookshelf\":{\"data\":\"data:image/jpeg;base64,\",\"alt\":\"TCS Numerical Ability PDF, page 23: circular bookshelf geometry working\"},\"num-circle-square\":{\"data\":\"data:image/jpeg;base64,\",\"alt\":\"TCS Numerical Ability PDF, page 24: circle-square geometry working\"},\"reason-paper-fold\":{\"data\":\"data:image/jpeg;base64,\",\"alt\":\"TCS Reasoning Ability PDF, page 17: paper-folding and cutting figure\"},\"reason-venn\":{\"data\":\"data:image/jpeg;base64,\",\"alt\":\"TCS Reasoning Ability PDF, page 18: overlapping-shapes Venn-style reasoning figure\"},\"reason-figure-series\":{\"data\":\"data:image/jpeg;base64,\",\"alt\":\"TCS Reasoning Ability PDF, page 20: figure-series question\"}};\nconst FORMULA_GALLERY = [{\"id\":\"num-si-ci\",\"title\":\"Simple interest and compound interest\",\"source\":\"TCS Numerical Ability PDF \u00b7 page 1\",\"caption\":\"Original handwritten calculation shown under Question 1.\"},{\"id\":\"num-cone-csa\",\"title\":\"Curved surface area of a cone\",\"source\":\"TCS Numerical Ability PDF \u00b7 page 3\",\"caption\":\"Original handwritten steps shown under Question 4.\"},{\"id\":\"num-cube-root\",\"title\":\"Cube-root expression\",\"source\":\"TCS Numerical Ability PDF \u00b7 page 11\",\"caption\":\"Original handwritten solution shown under Question 16.\"},{\"id\":\"num-triangle-area\",\"title\":\"Triangle inscribed in a circle\",\"source\":\"TCS Numerical Ability PDF \u00b7 page 23\",\"caption\":\"Original question working and geometry sketch.\"},{\"id\":\"num-circle-square\",\"title\":\"Circle and semicircle in a square\",\"source\":\"TCS Numerical Ability PDF \u00b7 page 24\",\"caption\":\"Original handwritten geometry solution.\"}];\n\nconst FORMULA_GROUPS = [\n {title:'Aptitude formulas from the TCS numerical handout and JS bank',items:[\n  ['Simple interest','SI = P \u00d7 r \u00d7 t / 100','P = principal, r = annual rate in percent, t = years.'],\n  ['Compound interest (annual)','CI = P[(1 + r/100)^n \u2212 1]','Amount = P(1 + r/100)^n; interest is amount minus principal.'],\n  ['CI \u2212 SI for 2 years','Difference = P(r/100)^2','For annual compounding over two years, as used in the handout\u2019s Question 1.'],\n  ['Profit and selling price','SP = CP(1 + profit%/100)','Reverse the expression to find CP when SP and profit percent are known.'],\n  ['Successive profit rates','Final price = CP \u00d7 (1 + p\u2081/100) \u00d7 (1 + p\u2082/100)','Apply each seller\u2019s profit factor in sequence.'],\n  ['Distance, speed and time','Distance = Speed \u00d7 Time','Rearrange as Speed = Distance/Time or Time = Distance/Speed.'],\n  ['Combined work rate','1/T = 1/A + 1/B','Add individual work rates, then invert the combined rate to get time.'],\n  ['Probability','P(event) = favourable outcomes / total outcomes','Use equally likely outcomes as in the handout\u2019s sweets and box questions.'],\n  ['Mean / average','Mean = Sum of observations / Number of observations','Therefore total sum = mean \u00d7 number of observations.'],\n  ['Cone curved surface area','CSA = \u03c0 r l ;  l = \u221a(r\u00b2 + h\u00b2)','The numerical handout uses the slant height of a right circular cone.'],\n  ['Cone, sphere and hemisphere volumes','Vcone = (1/3)\u03c0r\u00b2h ; Vsphere = (4/3)\u03c0r\u00b3 ; Vhemisphere = (2/3)\u03c0R\u00b3','For recasting, equate the sum of original volumes to the final volume.'],\n  ['Arithmetic progression','a\u2099 = a\u2081 + (n \u2212 1)d','a\u2081 is the first term and d is the common difference.']\n ]},\n {title:'Mechanical formulas from the supplied JavaScript practice bank',items:[\n  ['Moment of a perpendicular force','M = F \u00d7 r','Force multiplied by perpendicular lever arm.'],\n  ['Simply supported beam, central point load','R\u2081 = R\u2082 = P/2','Symmetric loading gives equal support reactions.'],\n  ['Axial normal stress','\u03c3 = F/A','Use consistent force and area units; 1 N/mm\u00b2 = 1 MPa.'],\n  ['Axial elongation','\u03b4 = FL/(AE)','For a uniform prismatic bar under axial load.'],\n  ['Rectangular beam bending stress','\u03c3 = Mc/I = 6M/(b h\u00b2)','For a rectangular section with I = bh\u00b3/12 and c = h/2.'],\n  ['Solid circular shaft torsion','\u03c4max = 16T/(\u03c0d\u00b3)','T must be converted to N\u00b7mm when d is in mm.'],\n  ['External gear pair','N\u2081Z\u2081 = N\u2082Z\u2082','A single external gear mesh reverses direction.'],\n  ['Belt drive, no slip','N\u2081D\u2081 = N\u2082D\u2082','Pulley speeds vary inversely with pulley diameters.'],\n  ['Closed-system first law','\u0394U = Q \u2212 W','Sign convention in the JS bank: work done by the system is positive.'],\n  ['Sensible heat','Q = mc\u209a\u0394T','Assumes constant specific heat and no phase change.'],\n  ['Carnot efficiency','\u03b7max = 1 \u2212 TL/TH','Reservoir temperatures must be in kelvin.'],\n  ['Continuity / volume flow','Q\u0307 = A v','Area and velocity must use compatible SI units.'],\n  ['Reynolds number','Re = \u03c1 V D / \u03bc','Dimensionless flow parameter.'],\n  ['Hydrostatic gauge pressure','p = \u03c1 g h','Pressure increase below a static liquid free surface.'],\n  ['Darcy\u2013Weisbach head loss','hf = f(L/D)V\u00b2/(2g)','Use the Darcy friction factor as represented in the JS bank.'],\n  ['Steady 1-D conduction through a plane wall','Q\u0307 = k A \u0394T / L','Thermal conductivity \u00d7 area \u00d7 temperature difference / thickness.'],\n  ['Newton cooling / convection','Q\u0307 = h A (Ts \u2212 T\u221e)','h is the convection heat-transfer coefficient.'],\n  ['Cutting speed in turning','V = \u03c0 D N / 1000','D in mm and N in rpm gives V in m/min.'],\n  ['Turning material removal rate','MRR \u2248 \u03c0 D N f d / 1000','As represented by the JS practice bank, with its stated units.'],\n  ['Process capability','Cp = (USL \u2212 LSL)/(6\u03c3)','Specification width divided by six standard deviations.'],\n  ['Economic order quantity','EOQ = \u221a(2DS/H)','D = annual demand, S = order cost, H = annual holding cost per unit.'],\n  ['Linear spring rate','k = F/x','For a linear spring, stiffness is load divided by extension.'],\n  ['DC electrical input power','P = V I','Shaft output is lower when motor losses are present.'],\n  ['Pump input power','Pin = \u03c1 g Q H / \u03b7','Q is volume flow rate and \u03b7 is pump efficiency as a fraction.']\n ]}\n];\n\nconst topicFilter=document.getElementById('topicFilter');\nconst sourceFilter=document.getElementById('sourceFilter');\nconst levelFilter=document.getElementById('levelFilter');\nconst searchBox=document.getElementById('searchBox');\nconst questionList=document.getElementById('questionList');\nconst PAGE_SIZE=12;\nlet currentPage=1, filteredQuestions=[];\nlet attempts=0, correctAttempts=0;\ntry{attempts=Number(localStorage.getItem('studyStudioAttempts')||0);correctAttempts=Number(localStorage.getItem('studyStudioCorrect')||0);}catch(e){}\ndocument.getElementById('attemptCount').textContent=attempts;\n\ndocument.getElementById('pdfCount').textContent=PDF_QUESTIONS.length;\ndocument.getElementById('genCount').textContent=window.MECHPREP_GENERATED_QUESTIONS.length;\ndocument.getElementById('totalCount').textContent=PDF_QUESTIONS.length+window.MECHPREP_GENERATED_QUESTIONS.length;\n\nfunction escapeHtml(value){return String(value??'').replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[ch]));}\nfunction allTopics(){const set=new Set();PDF_QUESTIONS.forEach(q=>set.add(q.category));window.MECHPREP_GENERATED_QUESTIONS.forEach(q=>set.add(q.topic));return [...set].sort((a,b)=>a.localeCompare(b));}\nfunction populateTopics(){allTopics().forEach(t=>{const o=document.createElement('option');o.value=t;o.textContent=t;topicFilter.appendChild(o);});}\npopulateTopics();\nfunction allQuestionRecords(){\n const pdf=PDF_QUESTIONS.map(q=>({...q,sourceType:'pdf',difficulty:'Handout'}));\n const generated=window.MECHPREP_GENERATED_QUESTIONS.map(q=>({...q,sourceType:'generated',source:q.role||'Generated JS bank',number:null,set:null,page:null}));\n return [...pdf,...generated];\n}\nfunction topicOf(q){return q.sourceType==='generated' ? q.topic : q.category;}\nfunction filteredRecords(){\n const mode=sourceFilter.value,topic=topicFilter.value,level=levelFilter.value,query=searchBox.value.trim().toLowerCase();\n return allQuestionRecords().filter(q=>{\n   if(mode==='pdf'&&q.sourceType!=='pdf')return false;\n   if(mode==='generated'&&q.sourceType!=='generated')return false;\n   if(topic!=='all'&&topicOf(q)!==topic)return false;\n   if(level!=='all'&&q.difficulty!==level)return false;\n   if(query){const hay=[q.text,q.explanation,q.answer,q.topic,q.category,q.source].join(' ').toLowerCase();if(!hay.includes(query))return false;}\n   return true;\n });\n}\nfunction imageMarkup(q){if(!q.imageId||!PDF_IMAGES[q.imageId])return '';const im=PDF_IMAGES[q.imageId];return `<div class=\"q-image\"><img loading=\"lazy\" src=\"${PDF_IMAGES[q.imageId].data}\" alt=\"${escapeHtml(im.alt)}\"><small>${escapeHtml(im.alt)}</small></div>`;}\nfunction renderQuestion(q,index){\n const isPdf=q.sourceType==='pdf';\n const badges=isPdf?`<span class=\"pill pdf\">Original PDF</span><span class=\"pill\">${escapeHtml(q.source)}</span><span class=\"pill\">Set ${q.set} \u00b7 Q${q.number} \u00b7 PDF p. ${q.page}</span>`:`<span class=\"pill gen\">Generated JS</span><span class=\"pill\">${escapeHtml(q.difficulty)}</span><span class=\"pill topic\">${escapeHtml(q.topic)}</span>`;\n let body='';\n if(isPdf){\n   const ans=q.answer?escapeHtml(q.answer):'Not stated in extracted text';\n   const expl=q.explanation?`<p class=\"explain\">${escapeHtml(q.explanation)}</p>`:'';\n   body=`<div class=\"q-actions\"><button class=\"btn reveal-btn\" data-id=\"${escapeHtml(q.id)}\">Reveal answer & explanation</button><span class=\"option-feedback\">Original wording from the PDF handout.</span></div><div class=\"reveal\" id=\"reveal-${escapeHtml(q.id)}\"><strong>Answer</strong><p>${ans}</p>${expl}</div>`;\n }else{\n   const optionButtons=q.options.map((op,i)=>`<button class=\"answer-option\" data-qid=\"${escapeHtml(q.id)}\" data-index=\"${i}\">${String.fromCharCode(65+i)}. ${escapeHtml(op)}</button>`).join('');\n   body=`<div class=\"option-grid\">${optionButtons}</div><div class=\"option-feedback\" id=\"feedback-${escapeHtml(q.id)}\">Select an option to check your answer.</div><div class=\"reveal\" id=\"reveal-${escapeHtml(q.id)}\"><strong>Worked explanation</strong><p>${escapeHtml(q.explain)}</p></div>`;\n }\n return `<article class=\"q-card\"><div class=\"q-top\"><div class=\"q-badges\">${badges}</div></div><h3>${isPdf?'Exact question from the handout':'Practice question'}</h3><pre class=\"q-text\">${escapeHtml(q.text)}</pre>${imageMarkup(q)}${body}</article>`;\n}\nfunction renderPractice(){\n filteredQuestions=filteredRecords();\n const maxPage=Math.max(1,Math.ceil(filteredQuestions.length/PAGE_SIZE));\n currentPage=Math.min(currentPage,maxPage);\n const start=(currentPage-1)*PAGE_SIZE;\n const visible=filteredQuestions.slice(start,start+PAGE_SIZE);\n document.getElementById('resultsCount').textContent=`${filteredQuestions.length} question(s) \u00b7 ${sourceFilter.value==='pdf'?'original PDF archive':sourceFilter.value==='generated'?'generated JS bank':'combined bank'}`;\n document.getElementById('pageNum').textContent=`Page ${currentPage} of ${maxPage}`;\n document.getElementById('prevPage').disabled=currentPage<=1;\n document.getElementById('nextPage').disabled=currentPage>=maxPage;\n questionList.innerHTML=visible.length?visible.map(renderQuestion).join(''):'<div class=\"q-card\">No questions match these filters. Clear the search or choose another topic.</div>';\n}\n[sourceFilter,topicFilter,levelFilter].forEach(el=>el.addEventListener('change',()=>{currentPage=1;renderPractice();}));\nsearchBox.addEventListener('input',()=>{currentPage=1;renderPractice();});\ndocument.getElementById('prevPage').addEventListener('click',()=>{currentPage=Math.max(1,currentPage-1);renderPractice();});\ndocument.getElementById('nextPage').addEventListener('click',()=>{currentPage+=1;renderPractice();});\ndocument.getElementById('randomBtn').addEventListener('click',()=>{\n const records=filteredRecords();if(!records.length)return;\n const pick=records[Math.floor(Math.random()*records.length)];\n sourceFilter.value=pick.sourceType;\n topicFilter.value=topicOf(pick);\n searchBox.value='';levelFilter.value='all';renderPractice();\n const ix=filteredQuestions.findIndex(q=>q.id===pick.id);currentPage=Math.floor(ix/PAGE_SIZE)+1;renderPractice();\n const first=questionList.firstElementChild;if(first)first.scrollIntoView({behavior:'smooth',block:'start'});\n});\nquestionList.addEventListener('click',ev=>{\n const revealBtn=ev.target.closest('.reveal-btn');\n if(revealBtn){const box=document.getElementById('reveal-'+revealBtn.dataset.id);if(box){box.classList.toggle('open');revealBtn.textContent=box.classList.contains('open')?'Hide answer & explanation':'Reveal answer & explanation';}return;}\n const opt=ev.target.closest('.answer-option');\n if(opt){const q=window.MECHPREP_GENERATED_QUESTIONS.find(x=>x.id===opt.dataset.qid);if(!q)return;\n   const chosen=Number(opt.dataset.index),correct=chosen===q.answer;\n   const article=opt.closest('.q-card');article.querySelectorAll('.answer-option').forEach(b=>{b.disabled=true;const n=Number(b.dataset.index);if(n===q.answer)b.classList.add('correct');else if(n===chosen&&!correct)b.classList.add('wrong');});\n   const fb=article.querySelector('.option-feedback');fb.textContent=correct?'Correct. '+q.explain:'Not quite. The correct option is '+String.fromCharCode(65+q.answer)+'. '+q.explain;\n   attempts++;if(correct)correctAttempts++;document.getElementById('attemptCount').textContent=attempts;\n   try{localStorage.setItem('studyStudioAttempts',String(attempts));localStorage.setItem('studyStudioCorrect',String(correctAttempts));}catch(e){}\n }\n});\n\nfunction renderFormulas(){\n const root=document.getElementById('formulaGroups');\n root.innerHTML=FORMULA_GROUPS.map(group=>`<div class=\"formula-group\"><h2>${escapeHtml(group.title)}</h2><div class=\"formula-layout\">${group.items.map(([title,formula,desc])=>`<article class=\"formula-card\"><h3>${escapeHtml(title)}</h3><div class=\"formula\">${escapeHtml(formula)}</div><p>${escapeHtml(desc)}</p></article>`).join('')}</div></div>`).join('');\n document.getElementById('formulaGallery').innerHTML=FORMULA_GALLERY.map(item=>{const im=PDF_IMAGES[item.id];return `<article class=\"gallery-card\"><img loading=\"lazy\" src=\"${im.data}\" alt=\"${escapeHtml(im.alt)}\"><h3>${escapeHtml(item.title)}</h3><small>${escapeHtml(item.source)}</small><p>${escapeHtml(item.caption)}</p></article>`;}).join('');\n}\nrenderFormulas();renderPractice();\n\nfunction showPage(name){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+name));document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===name));window.scrollTo({top:0,behavior:'smooth'});if(name==='questions')renderPractice();}\ndocument.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));\ndocument.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.go)));\ndocument.getElementById('printBtn').addEventListener('click',()=>window.print());\n</script>\n</body></html>";
  const DEFAULT_TARGET = '#mechprep-study';
  const currentScript = document.currentScript;

  function resolveTarget(target) {
    if (typeof target === 'string') {
      const node = document.querySelector(target);
      if (!node) throw new Error('MechPrepStudy: target not found: ' + target);
      return node;
    }
    if (target && target.nodeType === 1) return target;
    throw new TypeError('MechPrepStudy.mount() expects a CSS selector or an element.');
  }

  function mount(target) {
    const host = resolveTarget(target);
    const frame = document.createElement('iframe');
    frame.title = 'Mechanical and TCS Study Studio';
    frame.setAttribute('loading', 'eager');
    frame.setAttribute('referrerpolicy', 'no-referrer');
    frame.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-forms allow-downloads');
    frame.style.cssText = [
      'display:block', 'width:100%', 'height:100vh', 'min-height:760px',
      'border:0', 'margin:0', 'padding:0', 'background:#0b1020'
    ].join(';');
    host.replaceChildren(frame);
    const bankScript = '<script>' + GENERATED_BANK_SCRIPT.replace(/<\/script/gi, '<\\/script') + '<\/script>';
    frame.srcdoc = STUDY_HTML.replace('</head>', bankScript + '</head>');
    return {
      element: frame,
      unmount: function () {
        if (frame.parentNode === host) host.removeChild(frame);
      }
    };
  }

  function autoMount() {
    const selector = (currentScript && currentScript.getAttribute('data-target')) || DEFAULT_TARGET;
    let host = document.querySelector(selector);
    if (!host) {
      host = document.createElement('div');
      host.id = selector.startsWith('#') ? selector.slice(1) : 'mechprep-study';
      document.body.appendChild(host);
    }
    mount(host);
  }

  window.MechPrepStudy = Object.freeze({
    mount: mount,
    version: '1.0.0',
    description: 'Self-contained Mechanical + TCS study website'
  });

  // Auto-mount for a simple <script src="sem4_2.js"></script> setup.
  // You can disable this with data-autostart="false" and call mount() yourself.
  if (!(currentScript && currentScript.getAttribute('data-autostart') === 'false')) {
    const start = function () {
      try { autoMount(); }
      catch (error) { console.error(error); }
    };
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', start, { once: true });
    } else {
      start();
    }
  }
})();
